window.HS={"groups":[{"id":"shanshui","name":"山水天地","en":"LAND & WATER","color":"#2f6f7e","desc":"丘岗、湖泊、长江与它们的守护","parts":["p01","p05","p06"]},{"id":"jianzhi","name":"建置人烟","en":"PLACE & PEOPLE","color":"#9a5b2e","desc":"一个区怎样长成今天的模样","parts":["p02","p03","p04"]},{"id":"wuchan","name":"物产百业","en":"LIVELIHOOD","color":"#7a2f5c","desc":"菜篮子、鱼篓子与乡镇工厂","parts":["p07","p08","p09","p10","p11","p12","p13"]},{"id":"zhengshi","name":"政事治理","en":"GOVERNANCE","color":"#a03a2c","desc":"一方水土的组织与秩序","parts":["p14","p15","p16","p17","p18","p19","p20","p21","p22","p23"]},{"id":"wenjiao","name":"文教科卫","en":"LEARNING","color":"#2c6e55","desc":"大学之城、光谷之源、杏林春暖","parts":["p24","p25","p26","p27"]},{"id":"minsheng","name":"民生风俗","en":"FOLKWAYS","color":"#b07d16","desc":"过早、方言、村湾与乡愁","parts":["p28","p29"]}],"parts":[{"id":"zongshu","no":null,"title":"总述","start":1,"end":10,"group":null,"tagline":"一座名山得名，半圈环抱武昌城","lead":"如果在地图上找洪山区，你会发现它像一弯新月，从西到北呈半圆形把武昌、青山两区抱在怀里。它因境内的洪山得名，到2000年面积509平方公里，住着60多万人。这里四五千年前就有先民在南湖边打磨石斧、烧制陶罐；后来它长期是武昌城外的郊区，靠种菜、打鱼、种粮过日子。真正的转折发生在1986年：洪山被确定为“以城带郊”的新型城区，乡镇企业、民营科技企业像雨后春笋般冒出来，大学一所接一所沿着珞喻路排开。百余座山峰、二十多个湖泊，再加上二十余所高校，让洪山既有田园风光，又有浓厚书卷气。总述就是这本区志的“导游图”，带你一口气看完洪山从城郊农村走向科教新城的大变化。","numbers":[{"value":"509","unit":"平方公里","label":"2000年全区面积","page":1},{"value":"60.14","unit":"万人","label":"2000年常住人口","page":1},{"value":"20","unit":"余所","label":"辖区内高等院校","page":6},{"value":"75.1","unit":"岁","label":"1999年人均期望寿命（1949年为50.5岁）","page":7}],"stories":[{"title":"五千年前的稻壳","text":"1956年，放鹰台遗址出土了大量带稻壳的烧土和红烧土房屋遗迹。考古人员据此判断，五千多年前这里的先民已经会种稻、纺织、盖房、制陶。再加上南湖周家湾出土的石斧、陶鼎，说明至少在新石器时代晚期，洪山一带就有人类聚居了。","page":6},{"title":"元代江边造战船","text":"历史上洪山不光种地，也造过大船。元代镇南王脱欢曾在何家洲一口气造舰500艘，说明那时这里已有颇具规模的造船场地和相当发达的造船技术。宝通禅寺里那口南宋万斤大铁钟，也见证了古代工匠的铸造本领。","page":6},{"title":"第一家民办科技所","text":"1985年4月，导弹自动控制工程师刘金生辞职来到洪山，办起了全区第一家民办科技机构“洪峰电子应用技术开发部”。区里大力扶持，到1988年底民办科技机构已有约100家，“洪山科技一条街”初具雏形；到2000年，全区民营科技企业达189家。","page":7},{"title":"马家庄的回民村","text":"南宋咸淳十年（1274），一些回族人士到武昌做官，在长虹桥一带形成最早的回民聚居点。清同治五年（1866）前后，又有西北回民南来定居马家庄。直到今天，洪山乡上、下马家庄村仍是武汉市的回民集居点，有回族村民180多人。","page":8},{"title":"武汉首个花园别墅区","text":"1992年11月，洪山区开发公司与香港公司合作，开发了武汉市第一个规模最大、配套齐全的豪华花园别墅——虹景花园。小区占地千亩，建筑面积22万平方米，一期工程被评为国家优秀小区，也拉开了洪山房地产大发展的序幕。","page":5}],"chapterNotes":{},"keywords":["洪山","以城带郊","高校密集区","乡镇企业","民营科技","山水园林","城乡变迁"],"panorama":[{"title":"位置与面积","text":"洪山区位于武汉市东南部，因境内洪山得名。全区从西到北呈半圆形，环抱武昌、青山两区，东抵鄂州，南接江夏，东北与新洲隔江相望。2000年面积509平方公里，辖6乡2镇6街，常住人口60.14万人。"},{"title":"地形与气候","text":"区境处在江汉平原与鄂东南低山丘陵的结合部，以垄岗平原和冲积平原为主，地势由东南低丘向西北平原微微倾斜。气候兼有中亚热带向北亚热带过渡的特征，光热水充足、雨热同季、无霜期长，很适合农业生产。"},{"title":"千年沿革","text":"这里四五千年前已有人类活动。西周属鄂，东周属楚，秦属南郡，汉属江夏郡沙羡县；隋开皇九年（589）起长期属江夏县，民国元年（1912）改属武昌县。历史上一直是武昌城外的郊野，隶属变迁十分频繁。"},{"title":"山环水绕","text":"全区有大小山峰100余座、湖泊20多个，其中13个湖泊常年水面达149平方千米。沿江筑有武金堤、武惠堤、左岭堤三段长江干堤，堤内分为汤逊湖、东沙湖、北湖、严家湖、天兴湖五大水系。"},{"title":"从菜园到新城","text":"建国前这里几乎没有工业，以农业为主，历来是武汉的菜篮子和鱼米之乡。1986年被定为“以城带郊”新型城区后，乡镇企业成为经济支柱，2000年全区国内生产总值40.05亿元，三产比重上升到44.1%。"},{"title":"高校林立","text":"华中科技大学、华中师范大学、华中农业大学、中国地质大学等20余所高校集中在街道口以东，其中全国重点高校5所。如此密集的高等教育区在全国都很少见，也让洪山成为科教与高新技术产业结合的中心城区。"},{"title":"名胜与信仰","text":"近代武汉四大丛林中的宝通寺、莲溪寺都在洪山，分别于1988年和1985年修缮后对外开放，卓刀泉寺也已修葺。伊斯兰教元代传入，明末清初马铨曾在伏虎山、营盘山建清真寺，1953年在旧址修建回民亭。"},{"title":"民风与方言","text":"洪山民风淳朴，舞龙灯、划采莲船、端午赛龙舟等习俗代代相传。方言随地域而变：左岭、花山、九峰接近鄂州口音，青菱接近江夏话，靠近城区的洪山、和平、天兴、建设则近似武昌话。"}],"chapters":[]},{"id":"dashiji","no":null,"title":"大事记","start":11,"end":30,"group":null,"tagline":"三千年风云，写在一山一湖间","lead":"翻开《洪山区志》的大事记，就像沿着一条时间长廊散步。早在西周，这里是楚国鄂王的封地；南朝梁时，东山（今洪山）上立起第一座塔；南宋岳飞在此屯兵近8年，元代又建起今天的洪山宝塔。太平军九位女战士长眠东湖之滨，1911年南湖炮队的炮声拉开辛亥革命序幕。1949年，“洪山区”这个名字第一次出现，那时全区只有14177人；此后大学云集、东湖开发区崛起，洪山成为武汉面积最大的城区。这里挑出约八十件大事，从古到今带你走一遍，其中标星的是最值得记住的转折点。","events":[{"time":"周夷王时（前885—前878）","year":-885,"era":"古代","title":"楚封鄂王，洪山入楚","text":"楚王熊渠封次子红为鄂王，今洪山区一带归鄂王管辖，这是区境见于记载的最早归属。","page":11,"major":false},{"time":"楚怀王六年（前323）","year":-323,"era":"古代","title":"鄂君启金节过巡司河","text":"楚怀王为鄂君启铸造金节，相当于水陆免税通行证，限船150只、车50辆。鄂君启的船队就从今区境沿巡司河入江，再溯汉水北上。","page":11,"major":false},{"time":"高祖六年（前201）","year":-201,"era":"古代","title":"始置沙羡县","text":"西汉始设沙羡县，今区境属之。","page":11,"major":false},{"time":"梁元帝承圣元年（552）","year":552,"era":"古代","title":"洪山第一座塔","text":"东山（宋代改称洪山）西麓建起无影塔，又称兴福寺塔，高11.25米、四层八面，是洪山最早的塔。原塔后毁，今塔为宋代重建。","page":11,"major":true},{"time":"开皇九年（589）","year":589,"era":"古代","title":"江夏县登场","text":"隋朝改郢州为鄂州、改汝南县为江夏县。此后直到清代，江夏县未变，今区境长期属之。","page":11,"major":false},{"time":"天宝六年（747）","year":747,"era":"古代","title":"李邕归葬九峰山","text":"书法家李邕遭丞相李林甫陷害致死，归葬江夏九峰山。他的故居遗址在洪山西麓修静寺，即今施洋墓与宝通寺之间。","page":12,"major":false},{"time":"天宝年间（742—756）","year":742,"era":"古代","title":"宝通寺铸大铁佛","text":"宝通寺铸造两座大铁佛，高4米，底座宽8米，垂膝而坐，神态逼真，可惜在“文化大革命”中被毁。","page":12,"major":false},{"time":"绍兴四年至十一年（1134—1141）","year":1134,"era":"古代","title":"岳飞屯兵洪山","text":"抗金名将岳飞在洪山、白浒、长虹桥等地屯兵近8年，并以此为基地3次北伐抗金。","page":12,"major":true},{"time":"绍兴十一年（1141）","year":1141,"era":"古代","title":"“南市”兴起","text":"宋金“绍兴议和”后，鄂州商业和水运兴盛，城南至江边一带形成鼎盛的“南市”，今区境成为南方贸易的水陆门户。","page":12,"major":false},{"time":"至元十七年（1280）","year":1280,"era":"古代","title":"洪山宝塔始建","text":"在洪山始建灵济塔，俗称洪山宝塔，到至元二十八年（1291）竣工，前后历时十余年。","page":12,"major":true},{"time":"至正二十四年（1364）","year":1364,"era":"古代","title":"常遇春洪山破敌","text":"朱元璋派大将常遇春在洪山南麓击败从岳州赶来救援鄂州的陈友谅旧部，活捉张必先。","page":12,"major":false},{"time":"万历十六年（1588）","year":1588,"era":"古代","title":"大旱饥荒","text":"这一年大旱，饥民剥树皮充饥，死者甚多；次年又遭大水。明代区境旱涝灾害频繁。","page":12,"major":false},{"time":"万历四十一年（1613）","year":1613,"era":"古代","title":"熊廷弼捐资修堤","text":"熊廷弼罢官回乡，出资募捐加修县内堤垸20余公里，又修汤逊湖至武泰闸的道路和保安门外新桥1座；万历四十六年再修武金堤。","page":12,"major":false},{"time":"崇祯十六年（1643）","year":1643,"era":"古代","title":"张献忠改设上江县","text":"五月三十日张献忠建立大西政权，改江夏县为上江县；两年后李自成又改为瑞符县，清军占领武昌后复名江夏县。","page":13,"major":false},{"time":"康熙三年（1664）","year":1664,"era":"古代","title":"江夏成湖北省会","text":"湖广行省分为湖北、湖南两省，江夏县成为湖北省会所在，洪山境域属之。","page":13,"major":false},{"time":"咸丰三年（1853）","year":1853,"era":"近代","title":"太平军攻克武昌","text":"太平天国东王杨秀清督军区境，翼王石达开攻克武昌城；十月湘军夺回武昌，此后双方在洪山一带反复争夺。","page":13,"major":false},{"time":"咸丰六年（1856）","year":1856,"era":"近代","title":"九女墩的由来","text":"太平军与湘军在区境激战，十二月太平军分7路突围，牺牲万余人。当地农民把其中英勇战死的9名女战士埋在东湖之滨，世称“九女墩”。","page":13,"major":true},{"time":"同治四年（1865）","year":1865,"era":"近代","title":"重建宝通禅寺","text":"湖北巡抚胡林翼决定重建在战火中受损的宝通禅寺。","page":13,"major":false},{"time":"同治十年（1871）","year":1871,"era":"近代","title":"洪山宝塔大修","text":"冬季，洪山宝塔开始大修，到同治十三年（1874）三月完工。","page":13,"major":false},{"time":"光绪十二年（1886）","year":1886,"era":"近代","title":"罕见大雪","text":"冬天大雪，平地积雪2米，河港冰冻可以行人，有人畜和过往商旅冻毙于路。","page":13,"major":false},{"time":"光绪十八年（1892）","year":1892,"era":"近代","title":"张之洞引种美棉","text":"湖广总督张之洞花白银两千两引进美国棉种34担，在区境试种。两年后又在南湖植桑5百万株，养蚕缫丝。","page":13,"major":false},{"time":"光绪二十四年（1898）","year":1898,"era":"近代","title":"卓刀泉办农务学堂","text":"张之洞在卓刀泉创办农务学堂，次年招生120名，后迁址改名湖北高等农业学堂，是湖北近代最早的高等农业学堂，也是华中农业大学的源头。","page":13,"major":true},{"time":"宣统二年（1910）","year":1910,"era":"近代","title":"南湖农业试验场","text":"设立占地84.5公顷的南湖农业试验场，又创办武昌林场及洪山、卓刀泉、九峰3个支场。同年九峰特产“丰布”畅销全国。","page":14,"major":false},{"time":"宣统三年（1911）","year":1911,"era":"近代","title":"南湖炮队打响首义炮声","text":"9月南湖炮队士兵闹事后，革命党人仍按计划准备起义。10月9日夜，驻区境的新军南湖炮队打响推翻清王朝的炮声，辛亥革命由此拉开序幕。","page":14,"major":true},{"time":"民国元年（1912）","year":1912,"era":"近代","title":"江夏县改名武昌县","text":"1月1日，民国政府改江夏县为武昌县，洪山境域属之，直到1949年后才划归武汉市管辖。","page":14,"major":false},{"time":"民国七年（1918）","year":1918,"era":"近代","title":"瞽目女校创办","text":"12月，美籍瑞典人艾瑞英创办瞽目女校，即后来位于石牌岭的武汉市盲童学校的前身。","page":14,"major":false},{"time":"民国十二年（1923）","year":1923,"era":"近代","title":"施洋烈士遇害","text":"2月15日，共产党员、劳工律师施洋被军阀吴佩孚、萧耀南秘密杀害。新中国成立后在洪山建起施洋烈士陵园，董必武为之题诗。","page":14,"major":true},{"time":"民国十六年（1927）","year":1927,"era":"近代","title":"武豹长途汽车通车","text":"7月15日，武豹长途汽车通车，从武昌大东门经卓刀泉、鲁巷到豹澥，全程30千米。","page":14,"major":false},{"time":"民国十七年（1928）","year":1928,"era":"近代","title":"第一架飞机落南湖","text":"6月，区境南湖第一次有飞机降落。那时南湖还是一大片空地，既没有机场也没有跑道。","page":14,"major":false},{"time":"民国十九年（1930）","year":1930,"era":"近代","title":"周苍柏创设海光农圃","text":"民族资本家周苍柏在东湖创设海光农圃，建有多种娱乐设施，是东湖风景开发的早期篇章。","page":14,"major":false},{"time":"民国二十四年（1935）","year":1935,"era":"近代","title":"南湖飞机场开建","text":"5月20日，张学良主持在区境修建南湖飞机场，开辟通往上海、重庆、昆明、西安、南京5条航线。","page":15,"major":false},{"time":"民国二十四年（1935）11月24日","year":1935,"era":"近代","title":"黎元洪国葬卓刀泉","text":"国民政府在卓刀泉为民国前大总统黎元洪举行国葬。","page":15,"major":false},{"time":"民国二十七年（1938）","year":1938,"era":"近代","title":"日军占领武昌","text":"3月日机轰炸南湖，死伤平民200余人；10月26日日军登陆占领武昌，进入洪山境内。当年冬，新四军武工队在驼子店、王店一带开展抗日斗争。","page":15,"major":false},{"time":"民国二十八年（1939）","year":1939,"era":"近代","title":"日军地勤反战烧飞机","text":"2月19日，日本空军地勤人员反战，烧毁南湖机场轰炸机13架、油库1座。同年中共李家桥支部建立。","page":15,"major":false},{"time":"民国三十三年（1944）","year":1944,"era":"近代","title":"奇袭白浒湾机场","text":"6月21日，汤楚英、姜南平带领1个排奇袭日军正在修建的白浒湾飞机场，迫使工程停工。","page":15,"major":false},{"time":"民国三十七年（1948）","year":1948,"era":"近代","title":"连雨143天","text":"连续降雨达143天，境内大部分受涝，受涝面积达20000公顷。","page":15,"major":false},{"time":"1949年5月17日","year":1949,"era":"当代","title":"洪山解放","text":"下午5时，解放军第四十军一五三师经左岭、鲁巷、卓刀泉、街道口、宝通寺进入武昌市区，洪山境域随之解放。","page":16,"major":true},{"time":"1949年11月16日","year":1949,"era":"当代","title":"“洪山区”之名首现","text":"武汉市建立7个郊区，“洪山区”作为行政区名称首次出现。当时辖4个乡、84个自然村，人口14177人，农民中文盲占95%。","page":16,"major":true},{"time":"1951年5月29日","year":1951,"era":"当代","title":"东湖划为风景区","text":"中南军政委员会决定将东湖地带划为武汉市风景区，面积约105.5平方千米，其中水面约38.2平方千米。","page":16,"major":true},{"time":"1952年12月","year":1952,"era":"当代","title":"董必武撰《九女墩记》","text":"董必武撰写《九女墩记》并赋诗，称赞太平天国九位无名女战士。","page":16,"major":false},{"time":"1953年10月","year":1953,"era":"当代","title":"华中师范学院成立","text":"华中师范学院在桂子山成立，1985年更名华中师范大学。同年中南民族学院博物馆建成，是中国最早的校园博物馆。","page":17,"major":false},{"time":"1954年4—8月","year":1954,"era":"当代","title":"百年未遇大洪水","text":"百年未遇特大洪水来袭，两区1553.3公顷土地被淹，8月武汉关水位达29.73米。干部群众日夜巡堤抢险，战胜了洪水。","page":17,"major":true},{"time":"1954年10月","year":1954,"era":"当代","title":"首个郊区信用社","text":"武汉市第一个郊区信用社——东亭乡信用社在区境成立。","page":17,"major":false},{"time":"1954年12月","year":1954,"era":"当代","title":"华中工学院落成喻家山","text":"华中工学院在喻家山建成，首届招生1400余名；后改名华中理工大学，2000年再改名华中科技大学。","page":17,"major":false},{"time":"1955年2月17日","year":1955,"era":"当代","title":"重设洪山区","text":"中共武汉市委调整郊区区划，重设洪山区，辖2街18乡，机关驻武昌高家湾。同年8月，中南体育学院迁驻卓刀泉。","page":17,"major":false},{"time":"1956年10月","year":1956,"era":"当代","title":"武汉测量制图学院成立","text":"武汉测量制图学院（后改名武汉测绘学院）在广埠屯成立。同年毛泽东游览卓刀泉。","page":18,"major":false},{"time":"1958年8月20日","year":1958,"era":"当代","title":"武汉首个人民公社","text":"武汉市第一个农村人民公社——和平人民公社成立。9月，3000多人到花山“大办钢铁”，全区建土高炉110多座。","page":18,"major":false},{"time":"1960年1月27日","year":1960,"era":"当代","title":"高压线跨越长江","text":"第一条高空跨越长江的220千伏高压输电线从汉阳沌口通到青菱乡石嘴镇，3月5日正式送电。","page":19,"major":false},{"time":"1974年2月","year":1974,"era":"当代","title":"武汉邮电科学研究院成立","text":"邮电部武汉邮电科学研究院在区境吴家湾成立，后来成为中国光通信研发的重镇。","page":21,"major":false},{"time":"1975年8月","year":1975,"era":"当代","title":"地质学院迁入鲁巷","text":"北京地质学院迁入鲁巷，改名武汉地质学院（后为中国地质大学）。同月第三届全国运动会划船比赛在东湖举行。","page":21,"major":false},{"time":"1976年1月","year":1976,"era":"当代","title":"洪山环绕武汉市区","text":"区划调整后洪山区环绕武汉市区，辖12个公社2个街道，人口32万，其中农业人口28.76万。","page":21,"major":false},{"time":"1981年9月18日","year":1981,"era":"当代","title":"波音客机试飞南湖","text":"美国波音737—200型客机在南湖机场试飞成功。","page":22,"major":false},{"time":"1983年9月10日","year":1983,"era":"当代","title":"农民自建文化中心","text":"全国第一家由农民投资兴建的大型文化中心——和平公社三角路文化中心成立，引来全国乃至日本、瑞士等国客人参观。","page":23,"major":false},{"time":"1984年3月20日","year":1984,"era":"当代","title":"日本首相访北港村","text":"日本首相中曾根康弘访问洪山乡北港村。同年1月，全区12个人民公社改为乡。","page":23,"major":false},{"time":"1985年12月28日","year":1985,"era":"当代","title":"世界最大抄锣","text":"武汉锣厂（前身高洪太锣厂）制成两面直径1.42米、每面重60千克的大抄锣，时为世界最大，其中1面运往日本名古屋。","page":23,"major":false},{"time":"1986年6月","year":1986,"era":"当代","title":"成为“以城带郊”城区","text":"狮子山、关山、葛化等街道划归洪山，新设珞南街。全区面积509平方千米，占武汉城区面积58%，成为武汉面积最大的城区。","page":24,"major":true},{"time":"1987年12月8日","year":1987,"era":"当代","title":"百头白鳍豚溯江","text":"上午9时，天兴洲附近长江水域出现约百头白鳍豚溯江而上的奇观。","page":24,"major":false},{"time":"1988年12月28日","year":1988,"era":"当代","title":"首次拍卖国企产权","text":"武汉首次拍卖全民所有制企业——洪山砖瓦场产权。同月武汉测绘科技大学为正负电子对撞机研制的激光垂直系统达国际最高精度。","page":25,"major":false},{"time":"1990年11月1日","year":1990,"era":"当代","title":"宝通禅寺佛像开光","text":"宝通禅寺举行佛像开光典礼。同年武汉锣厂为亚运会制作直径1.46米的世界最大抄锣。","page":25,"major":false},{"time":"1991年3月6日","year":1991,"era":"当代","title":"东湖高新区获批","text":"国务院批准武汉东湖新技术开发区为国家新技术产业开发区，开发区位于洪山区关山街至九峰乡之间。","page":26,"major":true},{"time":"1992年3月28日","year":1992,"era":"当代","title":"磨山楚文化景区建成","text":"东湖磨山楚文化旅游区景点建成。同年9月风光村龙舟队在北京国际龙舟邀请赛获两项亚军。","page":26,"major":false},{"time":"1995年3月9日","year":1995,"era":"当代","title":"全省首个千万元税收乡","text":"和平乡税收居全省乡镇之首，入库1188万元，成为全省第一个突破千万元大关的乡镇。","page":27,"major":false},{"time":"1995年4月1日","year":1995,"era":"当代","title":"南湖机场迁天河","text":"南湖机场正式迁址天河机场，南湖结束了作为机场的历史。","page":27,"major":false},{"time":"1997年3月28日","year":1997,"era":"当代","title":"白沙洲大桥开工","text":"长江武汉段第三座大桥——白沙洲大桥开工，2000年10月28日通车，南起洪山区青菱乡。","page":28,"major":false},{"time":"1998年夏","year":1998,"era":"当代","title":"全民抗洪","text":"特大洪水中天兴乡进入高水位，守护人员安全转移；区内各界捐款捐物达342万元，区防汛指挥部获湖北省抗洪抢险集体一等功。","page":29,"major":false},{"time":"1998年12月18日","year":1998,"era":"当代","title":"华中农大百年校庆","text":"从卓刀泉农务学堂起步的华中农业大学迎来建校100周年。","page":29,"major":false},{"time":"1999年6月25日","year":1999,"era":"当代","title":"全市首次“海选”村官","text":"洪山乡向阳村“海选”村官，这在全市2070个村委会中是第一次。","page":29,"major":false},{"time":"1999年11月28日","year":1999,"era":"当代","title":"红菜薹摘得金牌","text":"洪山村“洪塔牌”大股子红菜薹获99中国国际农业博览会湖北省名牌产品奖第一名。","page":30,"major":false},{"time":"2000年4月","year":2000,"era":"当代","title":"黎元洪墓修复","text":"4月4日，黎元洪墓在卓刀泉土公山修复竣工；两天后青菱乡乔木湾发生岩溶地陷17处，990人安全转移，无人伤亡。","page":30,"major":false},{"time":"2000年5月","year":2000,"era":"当代","title":"高校合并组建新名校","text":"华中理工大学等合并组建华中科技大学；武汉工业大学等3校合组武汉理工大学；武汉大学与武汉测绘科技大学等合并组建新的武汉大学。","page":30,"major":true},{"time":"2000年12月26日","year":2000,"era":"当代","title":"石牌岭唐墓出土文物","text":"考古队在石牌岭唐墓挖出近50件文物，有精巧的人面兽身陶瓷等，数量和价值为当年武汉地区罕见。","page":30,"major":false},{"time":"2002年5月22日","year":2002,"era":"当代","title":"天兴洲大桥开钻","text":"国内最大的公铁两用桥——武汉天兴洲长江大桥详勘工作开钻。","page":945,"major":false},{"time":"2002年10月5日","year":2002,"era":"当代","title":"首届国际龙舟赛","text":"洪山乡风光村举办首届国际龙舟赛，47个国家和地区的运动员参赛，风光村代表队夺得4500米组冠军。","page":945,"major":false},{"time":"2003年3月28日","year":2003,"era":"当代","title":"石门峰名人文化公园开园","text":"石门峰名人文化公园开园，已建园区约600亩，有名人塑像百余座。同年湖北出版文化城落成。","page":946,"major":false},{"time":"2004年5月1日","year":2004,"era":"当代","title":"九峰森林动物园开园","text":"九峰森林动物园在五一黄金周开园。","page":947,"major":false},{"time":"2004年12月18日","year":2004,"era":"当代","title":"首届洪山菜薹文化节","text":"首届洪山菜薹文化节开幕，千年名菜有了自己的节日。","page":948,"major":true},{"time":"2005年8月28日","year":2005,"era":"当代","title":"武汉销品茂开业","text":"坐落在团结村的武汉销品茂开业，总投资8亿元，总建筑面积20多万平方米。","page":949,"major":false},{"time":"2006年3月20日","year":2006,"era":"当代","title":"和平、洪山乡改街","text":"和平乡、洪山乡正式改为街道并挂牌，城市化又迈一步。","page":949,"major":false},{"time":"2006年12月26日","year":2006,"era":"当代","title":"第二届菜薹节","text":"以“昔日金殿御盘菜，走入寻常百姓家”为主题的第二届洪山菜薹节开幕。","page":951,"major":false}],"chapters":[]},{"id":"p01","no":1,"title":"自然环境","start":31,"end":46,"group":"shanshui","tagline":"百座小山十四湖，一口古泉说关公","lead":"洪山区的“底子”长什么样？简单说就是：山不高、水很多、地很平。全区93%的土地海拔低于40米，最高的丁管山也只有240.3米，可境内14个湖泊加起来有113平方公里，占了全区面积的两成多，东湖、南湖、汤逊湖、严西湖都在这片“江汉湖群”里。长江在区内流程75公里，把湖、港、塘串在一起。这里冬冷夏热、雨热同季，菜农最爱，可也常被“梅雨”“南洋风”“秋老虎”折腾：1954年、1998年的大洪水，1978年连续75天的高温酷暑，2000年青菱乡突然出现的地陷，都写在这一篇里。还有四眼井、卓刀泉、活灵泉这些带着故事的老泉眼，读起来像一部洪山的“自然身世说明书”。","numbers":[{"value":"113","unit":"平方公里","label":"境内14个湖泊总面积，占全区22.2%","page":35},{"value":"240.3","unit":"米","label":"全区最高点丁管山海拔","page":33},{"value":"136","unit":"种","label":"区内天然鱼类品种","page":41},{"value":"75","unit":"天","label":"1978年35℃以上高温天数","page":45}],"stories":[{"title":"四眼井的消失","text":"街道口曾有一口“四眼井”，井深约40米，井底有4个铜钱大小的泉眼，一年四季不干不溢，水质甘甜，冬暖夏凉，村民世代饮用。1956年修武黄公路珞喻路段时，这口井被填埋，井虽然没了，“四眼井”这个地名却一直叫到今天。","page":36},{"title":"关公卓刀出清泉","text":"伏虎山麓的卓刀泉，传说是关羽行军时把刀插在坛下，泉水随之涌出。碑文说这泉水“冬温”“色淡碧，味甘如醴，饮之可疗疾”。井深约3丈，泉水清澈、四季不减，至今仍有当地居民在饮用。清康熙《武昌府志》就记载了这眼泉。","page":36},{"title":"常年18℃的活灵泉","text":"左岭镇泉井村有一眼地下喷泉叫活灵泉，清同治《武昌县志》就有记载。泉水清亮纯净，常年恒温18℃，冬暖夏凉。冬天村民到这里洗衣被，夏天过路人在此冲凉解暑。泉水流量约每秒1升，直到今天，它还是当地村民的饮用水源。","page":36},{"title":"小暑南洋十八天","text":"洪山的盛夏有句老话叫“小暑南洋十八天”：小暑前后常刮干热的南风，一刮就是半个月，白天能到37℃以上。1978年大旱，35℃以上高温天气达75天，比此前最热的1934年还多10天，8月上旬气温冲到41.3℃。","page":37},{"title":"烽火村突现地陷","text":"2000年4月6日，青菱乡烽火村乔木湾突然发生岩溶地陷，最深处下陷15米。到9日共发现地陷17处，最大的坑直径70余米，倒塌或部分倒塌房屋16栋59间，安全转移农户196户、990人，所幸处置及时。","page":44}],"chapterNotes":{"1":"讲洪山的地层构造和地形：哪里是低山丘陵、哪里是垄岗平原，最高最低点各在哪。","2":"介绍长江、巡司河、十四个湖泊和地下水、古泉，以及四季气候、日照、降水和风。","3":"盘点土壤类型与分布，以及区内的树木、野菜、鱼类、武昌鱼、白鳍豚等动植物。","4":"梳理地震、地陷记录和洪涝、干旱、寒潮、冰凌等气象灾害，附历年水旱灾情。"},"keywords":["垄岗平原","江汉湖群","长江","古泉","梅雨","南洋风","洪涝干旱","地陷"],"chapters":[{"no":1,"title":"地质 地貌","page":32,"zhuanji":false,"sections":["地质","地貌"]},{"no":2,"title":"水文气候","page":35,"zhuanji":false,"sections":["地表水","地下水","气候"]},{"no":3,"title":"土壤 动植物","page":39,"zhuanji":false,"sections":["土壤","植物","动物"]},{"no":4,"title":"自然灾害","page":42,"zhuanji":false,"sections":["地质灾害","气象灾害"]}]},{"id":"p02","no":2,"title":"建置 街乡镇","start":47,"end":76,"group":"jianzhi","tagline":"十四块拼图，拼出一弯洪山月","lead":"“洪山区”这个名字其实很年轻：1949年11月它第一次出现时，只管着东湖和沙湖之间4个乡、84个自然村，因为洪山就在这4个乡里，区名便叫“洪山”。此后几十年，它被撤销、恢复、合并、拆分了好几轮，一度成为环绕武汉的“大郊区”，1985年又一口气把江北5个乡和3个街道划了出去，面积少了144.73平方公里。直到1986年改为“城区带郊区”，版图才稳定下来：到2000年辖6个街道、6个乡、2个镇。这一篇就像一本“洪山户口簿”，一个个介绍珞南、关山这些高校和工厂扎堆的街道，也带你认识种菜的洪山乡、种西瓜的江心洲天兴乡、产茶的九峰乡，还有从负债穷村变成“荆楚第一村”的徐东村。","numbers":[{"value":"84","unit":"个","label":"1949年洪山区初设时管辖的自然村","page":50},{"value":"144.73","unit":"平方公里","label":"1985年划出江北乡街后减少的面积","page":52},{"value":"47","unit":"公里","label":"全区东西最大横距","page":47},{"value":"800","unit":"万元","label":"徐东村出资设立的高雅音乐发展基金","page":75}],"stories":[{"title":"“洪山区”名字的由来","text":"1949年11月，武汉在江南设了洪山、武泰、挹江3个郊区，这是历史上第一次出现“洪山区”。它接管了东湖和沙湖之间的官园、武珞、沙湖、东亭4个乡，共84个自然村、14177人。因为洪山就在这4个乡里，区名就叫洪山，一直沿用至今。","page":50},{"title":"江心洲上的西瓜乡","text":"天兴乡是长江中的一座江心洲，洲名就是乡名。1984年后这里以种西瓜为主，每年上市约1250万公斤，占全市西瓜上市量的15%至20%。可它也常被洪水围困，1998年大洪水后全乡实行“平垸行洪、移民建镇”，整体搬到洪山乡、和平乡的移民新村。","page":71},{"title":"农民盖的溜冰场","text":"1983年，和平乡三角路村投资100多万元建起三角路文化中心，里面有1800平方米的室内溜冰场和1000多平方米的室内舞厅，先后接待40万人次。这种“农民自己办文化”的做法吸引了全国20多个省区和英国、日本等国的客人前来参观。","page":64},{"title":"穷村变“荆楚第一村”","text":"徐东村人均只有4分多地，80年代中期还背着债，村民退休每月只拿12.8元。此后十多年，村里办起武汉第一家村级房地产公司，还有出租车队、驾校、酒店。2000年在全省“十强村”中名列第一；1995年更出资800万元资助乐团，乐团冠名“武汉徐东乐团”。","page":75},{"title":"关山村“借智”致富","text":"1976年关山村每个劳力日均工资不足1元，人心思迁。改革后村里请武大、华工、华农等高校代培人才150余人，还聘20多位专家教授当客座顾问。它与华中理工大学等共同研制的高压绝缘测试车填补国内空白，获全国星火计划博览会金奖。","page":76}],"chapterNotes":{"1":"从西周鄂王辖地讲到2000年6街6乡2镇，梳理洪山的位置、隶属变化和历次区划调整。","2":"逐一介绍珞南、关山、狮子山、红旗、张家湾、葛化6个街道的人口、由来、产业和配套。","3":"介绍洪山、和平等6乡与花山、左岭2镇的土地、沿革、经济，并选介徐东、关山两个名村。"},"keywords":["行政区划","隶属沿革","街道","乡镇","以城带郊","徐东村","关山村","天兴洲"],"places":[{"name":"珞南街道","type":"街道","text":"位于珞珈山以南，面积13.5平方公里，因地处珞珈山之南得名，1986年8月成立。武汉理工大学等高校和科研院所云集，街道口劝业场年销售额达2亿元，是武汉十三大市场之一。","page":54},{"name":"关山街道","type":"街道","text":"位于区境东南、关山西北，面积34平方公里，因境内泛称关山得名。1958年后汽轮发电机厂、鼓风机厂等大厂相继建成，成为以机电为主的新型工业区，华中工学院1953年在此建成。","page":55},{"name":"狮子山街道","type":"街道","text":"位于区境西南，东、北濒临南湖，面积14.41平方公里，因境内狮子山得名。华中农业大学、湖北省农业科学院等农业科研院所集中于此，是一条浓浓“农科味”的街道。","page":56},{"name":"红旗街道","type":"街道","text":"位于区境东北、青王公路西侧，面积23.6平方公里，1981年2月成立。居民多是建厂征地时“农转工”的工人，散居在17个村委会的177个自然湾，城乡交错，到2000年尚未形成街市。","page":57},{"name":"张家湾街道","type":"街道","text":"位于区境西南、武咸公路东侧，面积23.4平方公里，以境内张家湾自然村得名，1981年2月成立。辖区内有起重机厂、焦化厂等11家大中型企业，1996年社会总产值突破1亿元。","page":58},{"name":"葛化街道","type":"街道","text":"位于区境最东端，与鄂州交界，面积仅1.809平方公里，因辖区有葛店化工厂得名。1958年前还是一片山丘农田，此后建成化工区，1980年葛化出口的氯化石蜡获全国同类产品评比第一。","page":58},{"name":"洪山乡","type":"乡","text":"位于大东门以东、南湖以南，面积74平方公里，因境内洪山得名。昔日“九岭十八凹”满是山丘坟地，后来成为城市菜篮子；1986年社会总产值破亿元，是武汉农村3个亿元乡之一。","page":59},{"name":"和平乡","type":"乡","text":"位于区境东北，沿用原和平公社名称。传统蔬菜区，后成为武汉菜、猪、鱼基地；乡镇企业兴旺，在武汉率先实现“亿元乡”，1990年、1995年两度获评“全国最佳乡镇”、捧回“大地杯”。","page":62},{"name":"建设乡","type":"乡","text":"位于区境东部，俗称北湖地区，隔长江与阳逻相望，面积80平方公里。历史上是粮食产区，60年代转为“稻菜兼作”，后发展蔬菜、水产、畜禽三大产业，2000年农民人均纯收入3920元。","page":64},{"name":"青菱乡","type":"乡","text":"位于武昌城区西南、西靠长江，面积60多平方公里，以境内青菱湖得名。以种菜为主，90年代发展猕猴桃、草莓、特种水产，形成“一村一品”，1996至1998年连续获湖北综合实力十强乡镇。","page":66},{"name":"九峰乡","type":"乡","text":"位于区境东部，面积36平方公里，因境内九峰山得名，乡政府驻王家店老镇街。传统水稻区，保丰茶场名茶获“陆羽杯”一等奖，后又依托山水建成森林公园、高尔夫球场等休闲旅游一条线。","page":68},{"name":"天兴乡","type":"乡","text":"位于青山与谌家矶之间的长江江心，面积约30平方公里，洲名即乡名。以种西瓜闻名，曾占全市西瓜上市量的15%至20%；1996年建成自来水厂，结束47年肩挑手提饮水的历史。","page":70},{"name":"花山镇","type":"镇","text":"位于区境东部，面积58平方公里，因境内花山得名，镇政府驻驼子店。曾是武汉市粮食主产区之一，什锦钢锉等产品远销港澳和日本，90年代建设粮油、蔬菜、林果茶、精养鱼池“四个一万亩”基地。","page":72},{"name":"左岭镇","type":"镇","text":"位于区境东端、长江南岸，面积44.7平方公里，原属鄂州，1985年划归洪山区。历史上以种水稻为主，后发展粮油果菜、猪鱼禽蛋综合经营，镇皮鞋厂的男式皮鞋曾获省部优质产品称号。","page":73},{"name":"徐东村","type":"乡","text":"和平乡名村，人均4分多地，从负债穷村发展为“荆楚第一村”。2000年位列全省乡镇企业综合实力“十强村”第一，1999年营业收入15亿元，还出资800万元资助“武汉徐东乐团”。","page":75},{"name":"关山村","type":"乡","text":"洪山乡名村，地处鲁巷至关山一带。靠调整农业结构和“借智经营”致富，与高校合研高压绝缘测试车获星火金奖，后在东湖开发区腹地建起鲁巷商业服务中心，一期鲁巷广场2000年开业。","page":76}],"chapters":[{"no":1,"title":"建置","page":47,"zhuanji":false,"sections":["区境位置","隶属沿革","行政区划"]},{"no":2,"title":"街道","page":54,"zhuanji":false,"sections":["珞南街道","关山街道","狮子山街道","红旗街道","张家湾街道","葛化街道"]},{"no":3,"title":"乡镇","page":59,"zhuanji":false,"sections":["洪山乡","和平乡","建设乡","青菱乡","九峰乡","天兴乡","花山镇","左岭镇","名村选介"]}]},{"id":"p03","no":3,"title":"人口","start":77,"end":96,"group":"jianzhi","tagline":"从一万四到六十万，郊区变成了城","lead":"1949年洪山区刚成立时，只有14177人，还不如今天一个大社区；到2000年，全区常住人口已经是601389人。人多了，是因为孩子生得多吗？恰恰相反，这里的出生率从80年代的13‰左右一路降到2000年的6.05‰。真正的原因是区划一次次调整，加上大学、工厂、开发区把成千上万的人带到洪山。人口的“底色”也变了：1982年，近八成在业人口在种地打鱼；到2000年，全区非农业人口已占69.4%。这里还被称为武汉的“文化区”，大专院校集中，受教育人口比例高于其他城区；30多个少数民族散居在高校和大企业里。不过普查数字也提醒人们：男女性别比偏高，是个值得关注的问题。","numbers":[{"value":"601389","unit":"人","label":"2000年底常住人口（1949年建区时14177人）","page":77},{"value":"69.4","unit":"%","label":"2000年非农业人口占比","page":80},{"value":"1726","unit":"人/平方公里","label":"2000年人口普查人口密度","page":83},{"value":"123.54","unit":":100","label":"2000年人口普查男女性别比","page":83}],"stories":[{"title":"五十年人口涨了四十多倍","text":"1949年11月洪山区成立时只管4个乡，总人口14177人。此后区划不断变动：1976年汉桥区并入，人口一度到33万多；1985年江北乡街划出后降到20万左右；1986年关山、狮子山等街道划入，又猛增到45万多。到2000年，全区已有601389人。","page":78},{"title":"民国时识字的女性极少","text":"据1936年《武昌县志》记载，武昌县识字人数只占全县人口的16.4%，其中男性57998人，女性只有3223人，女子受教育者仅为男子的5.3%。而建国后的洪山大学、科研单位集中，有武汉“文化区”之称，居民整体文化素质高于其他城区。","page":90},{"title":"菜农变成上班族","text":"1982年人口普查时，洪山在业人口中78.64%从事第一产业，第三产业只占4.57%。随着“以城带郊”和乡镇企业兴起，到2000年第三产业从业者已占29.89%，制造、建筑、运输、餐饮等行业的劳动者明显增多。","page":92},{"title":"三十多个民族同城住","text":"1990年人口普查显示，散居洪山的少数民族有蒙古、回、藏、维吾尔、苗、土家等30多个，千人以上的是回、壮、土家族。他们多在高校和大型企事业单位，中南民族学院尤为集中；上下马庄则是回民聚居地。少数民族人口从1982年的2820人增至2000年的13638人。","page":89},{"title":"当年几岁成家","text":"根据1982年第三次人口普查推算，洪山区男性平均初婚年龄为25.14岁，女性为23.73岁。当时15岁及以上人口中，有配偶的占61.76%，离婚的仅占0.65%，可以看出那个年代婚姻家庭相当稳定。","page":91}],"chapterNotes":{"1":"用一串数字讲清洪山人口如何随区划变动而增减，出生率、迁移和人口密度怎样变化。","2":"从性别、年龄、民族、文化、婚姻家庭和职业几个角度，看洪山人的“画像”如何改变。","3":"介绍计划生育的管理机构、宣传方式、优生优育和技术服务网络的发展历程。"},"keywords":["人口普查","人口密度","非农业人口","性别比","少数民族","文化区","人口变动"],"chapters":[{"no":1,"title":"人口规模","page":77,"zhuanji":false,"sections":["人口数量与变动","人口分布与密度"]},{"no":2,"title":"人口构成","page":83,"zhuanji":false,"sections":["人口性别与年龄构成","人口社会经济构成"]},{"no":3,"title":"人口控制","page":93,"zhuanji":false,"sections":["管理机构","宣传教育","优生优育","服务管理"]}]},{"id":"p04","no":4,"title":"城乡建设","start":97,"end":152,"group":"jianzhi","tagline":"从一根“扁担”路，到一张城市网","lead":"1934年，从喻家山到武昌城只有一条4米宽的碎石路，叫“武葛公路”，那是当时洪山唯一一条政府修建、通往外面的路。几十年里，洪山的交通长期是“一根扁担伸到底”——武珞路、珞喻路一条线贯穿东西。1986年变成新城区后，32条道路先后新建、拓宽，雄楚大街、卓刀泉路、关山一路织成了路网；长江二桥、白沙洲大桥相继通车。这一篇讲的就是洪山“长成城市”的过程：怎么规划、怎么管地、修路架桥、通水通气、种树建园、扫街建厕、盖房造楼。你会读到将近500年只修过3次的明代北洋桥，用糯米浆砌成的长虹桥，岳飞手植松的后代“岳松”，也会看到东湖边14所高校从喝湖水改喝长江水的故事。","numbers":[{"value":"32","unit":"条","label":"1986年后新建拓宽改造的道路","page":97},{"value":"618","unit":"米","label":"白沙洲大桥（武汉长江三桥）主跨","page":116},{"value":"38.83","unit":"%","label":"2000年全区绿化覆盖率","page":97},{"value":"47","unit":"座","label":"2000年全区公厕（1986年接手时仅3座危厕）","page":145}],"stories":[{"title":"近500年的北洋桥","text":"北洋桥原是北洋渡口。明弘治十七年（1504），江夏县官员周玺看到渡船翻沉淹死多人，便与友人陈延英倡议修桥，陈捐银1000余两，石匠从200里外运来青石1.2万余片。这座红砂石拱桥建成近500年只维修过3次，武钢20吨以上的载重车从上面开过，桥体安然无恙。","page":116},{"title":"糯米浆砌的长虹桥","text":"长虹桥跨巡司河，是武昌通往湖南、两广、云贵的驿道必经之地。明万历末年熊廷弼修堤时重修此桥，把磨平的砖块用糯米浆加石灰粘接，砌成3孔拱桥。太平天国、辛亥革命和北伐时期，这里都发生过激战。","page":116},{"title":"岳飞手植的“岳松”","text":"宋绍兴五年（1135），岳飞驻江夏，在洪山上亲手种下一棵松树以示其志，后人称为“岳松”。原树已经不在，现在宝通寺岳飞亭旁的这棵是清同治年间补种的。2000年调查时，它高12米，干围1.28米，长势尚可。","page":141},{"title":"高校改喝长江水","text":"建国前洪山没有自来水管网，1931年武汉大学自建了日供水800吨的小水厂。后来东湖水厂、白沙洲水厂陆续扩建，1990年白沙洲水厂扩建通水，历时5年的“湖改江”工程完工，东湖岸边14所大专院校和沿线居民都喝上了长江水。","page":120},{"title":"山名里的传说","text":"马鞍山森林公园有17座山林，各有来历：太渔山相传是西周姜太公垂钓之处，古名一直沿用；吹笛山相传因明太祖朱元璋在此吹过竹笛而得名。公园开放后，到2000年共接待省内外游客100多万人次。","page":127}],"chapterNotes":{"1":"从1918年的武昌商埠图讲到1990年分区规划，看洪山如何被规划成科教与产业新区。","2":"介绍土地规划、基本农田与山湖保护、土地定级发证、征地拆迁和违法建筑查处。","3":"梳理道路网形成、古桥与长江大桥、六大排水系统和城镇路灯，北洋桥、长虹桥是亮点。","4":"讲自来水从无到有、“湖改江”、管道燃气、电网建设和公交线路的发展。","5":"游览九峰国家森林公园、马鞍山森林公园、磨山和东湖，了解街道、校园、堤防绿化与古树。","6":"介绍门前三包、干道整治、街巷清扫、垃圾清运和公厕从3座危厕到47座的变化。","7":"讲房地产从“干打垒”平房起步，到商品房、花园别墅和房改的发展与管理。","8":"介绍建筑企业、工程建设与监管，并选介丽岛花园、名都花园、南湖山庄等特色小区。"},"keywords":["城市规划","道路桥梁","北洋桥","长江二桥","园林绿化","九峰森林公园","市容环卫","房地产"],"chapters":[{"no":1,"title":"城乡规划","page":98,"zhuanji":false,"sections":["总体规划","分期规划","专项规划","乡镇建设规划"]},{"no":2,"title":"土地管理","page":100,"zhuanji":false,"sections":["土地规划","地籍管理","执法监察"]},{"no":3,"title":"市政设施","page":105,"zhuanji":false,"sections":["城乡道路","城乡桥粱","城区排水","城镇路灯","第五节"]},{"no":4,"title":"公用事业","page":120,"zhuanji":false,"sections":["供 水","供气","供电","公共交通"]},{"no":5,"title":"园林 绿化","page":125,"zhuanji":false,"sections":["园林","绿化","绿化基地建设","园林绿化管理"]},{"no":6,"title":"市容管理与环境卫生","page":142,"zhuanji":false,"sections":["市容管理","环境卫生","管理机构"]},{"no":7,"title":"房地产","page":147,"zhuanji":false,"sections":["房地产市场与开发","房地产管理"]},{"no":8,"title":"建筑","page":149,"zhuanji":false,"sections":["建筑企业","建筑工程","建筑工程监管","特色建筑"]}]},{"id":"p05","no":5,"title":"环境保护","start":153,"end":174,"group":"shanshui","tagline":"湖水变黑之后，洪山学会了治污","lead":"洪山区的空气和噪声，在武汉中心城区里算是“优等生”：1999年空气质量属良好，城区区域噪声平均52分贝，低于国家一类标准。可这份成绩单背后，也有不少让人揪心的记录：70年代以后，东湖、沙湖、南湖、严西湖成了工业废水和生活污水的“接收站”，有的湖水发黑发臭，湖里的鱼肉甚至带着一股煤油味；关山的炭黑粉尘、石牌岭的窑炉黑烟，让居民不敢开窗晒衣。这一篇讲的就是洪山怎样一步步“还账”：建烟尘控制区、搬迁污染大户、禁用含铅汽油、给工厂装上废水处理设备，还在鱼塘里搞起生态农业试验。远郊的九峰、花山、左岭和天兴洲，则依旧保持着湖光山色和田园风光。","numbers":[{"value":"52","unit":"分贝","label":"1999年城区区域环境噪声平均值","page":153},{"value":"93","unit":"%","label":"1988至1992年建成的烟尘控制区覆盖城区面积比例","page":157},{"value":"2000","unit":"辆/小时","label":"2000年街道口一带车流量（1986年不到500辆）","page":167},{"value":"11","unit":"家","label":"关停的污染企业","page":153}],"stories":[{"title":"带煤油味的湖鱼","text":"70年代，沙湖每天要接纳32家企业排放的近5万吨废水，鱼产量从1977年的96.5万公斤锐减到1981年的3万公斤。监测发现，湖里鱼肉的酚含量超过评价标准，吃起来有近似煤油的异味。80年代后期沿岸工厂开始治理，重金属污染才得到控制。","page":155},{"title":"炭黑厂搬走了","text":"1973年武汉炭黑厂在关山三角塘建成，后来设备老化，炭黑粉尘能飘散好几平方公里，关山地区10多万人深受其扰。1992年市政府决定让它停产搬迁到葛化化工区；石牌岭的武昌耐火材料厂也于1988年被兼并转产，4万多居民从此告别烟尘。","page":166},{"title":"鱼塘里的生态实验","text":"1985年起，北港村16户承包的135亩鱼塘被选为国家环保局16个农业生态研究点之一。塘埂、水面、塘底种青饲料，再引入鸡、鸭、猪，形成种养配套、少废弃物的循环。到1988年，鱼的亩产比1984年增长59.24%，人均收入达2400元。","page":161},{"title":"中国第一台治污设备","text":"武汉仪表厂（181厂）为治理本厂电镀废水，1964年开始研究处理技术。1974年，它造出了中国第一台（套）电解法处理含铬、含氰废水的设备，此后成批生产电镀、医疗废水处理设备，成为国企环保产业的龙头。","page":169},{"title":"从无铅汽油到尾气路检","text":"街道口的车越来越多，汽车尾气成了新公害。1998年5月1日起，武汉全面禁止使用含铅汽油，到年底辖区近100家加油站全部停售含铅汽油；1999年下半年开始上路检测尾气，两年检测2500辆，不合格车辆限期安装净化器。","page":167}],"chapterNotes":{"1":"体检洪山的水、空气、噪声和农村环境：饮用水达标情况、各大湖泊污染、酸雨和污灌土壤。","2":"介绍区环境监测站的工作，以及北港生态农业、南湖污水排放标准等监测研究成果。","3":"讲工业废水、烟尘、尾气、噪声的治理，污染企业整改、清洁工厂创建和历年污染事故。","4":"介绍环保机构沿革、法制宣传和建设项目环评、“三同时”、排污申报等管理制度。"},"keywords":["环境保护","湖泊污染","烟尘控制区","噪声","汽车尾气","生态农业","环境监测"],"chapters":[{"no":1,"title":"环境质量","page":154,"zhuanji":false,"sections":["水环境质量","第二节","声环境质量","农村环境质量一概况"]},{"no":2,"title":"环境监测","page":160,"zhuanji":false,"sections":["监测机构","监测研究"]},{"no":3,"title":"环境污染治理","page":165,"zhuanji":false,"sections":["工业废水治理","空气污染治理","噪声污染治理","污染企业治理","创建清洁无公害工厂","污染事故与污染纠纷处理","发展环保产业"]},{"no":4,"title":"环境保护管理","page":169,"zhuanji":false,"sections":["组织机构","法制宣传教育","建筑环境管理"]}]},{"id":"p06","no":6,"title":"水利","start":175,"end":192,"group":"shanshui","tagline":"地面比洪水低两米，全靠一道长堤","lead":"洪山沿江的地面高程只有24至25米，比20世纪90年代长江平均洪水位27.11米还低2米多——换句话说，堤外的江水常常比堤内人家的屋基还高。守住这一切的，是武金堤、武惠堤、左岭堤三段长江干堤，总长37.697公里。洪水来得越来越勤：1865至1948年的83年间，武汉关水位27米以上的大水只有6次；1949至2000年就有12次，仅90年代就有5次。这一篇讲洪山人如何与水共处：从明代熊廷弼募修堤闸，到张之洞修武昌南堤；从“十八段”“万人挡”这些带着伤疤的险段，到1998年全区军民在堤上苦守76天。还有泵站、水库、湖港治理这些“看不见的工程”，默默替城市排涝、给田地送水。","numbers":[{"value":"37.697","unit":"公里","label":"洪山区管理的长江干堤全长","page":175},{"value":"12","unit":"次","label":"1949至2000年武汉关27米以上大洪水（此前83年仅6次）","page":175},{"value":"76","unit":"天","label":"1998年全区军民上堤抗洪历时","page":191},{"value":"15.521","unit":"万棵","label":"2000年底武金、武惠堤防浪林护堤林","page":187}],"stories":[{"title":"一道堤修了近四百年","text":"武金堤始建于明代。万历四十年（1612），熊廷弼回乡募捐倡修堤闸；清道光年间周天爵大修时改过走向；光绪二十五年（1899）张之洞修武昌南堤，基本定下今天的线路。1931年后按28.28米标准加高，此后又多次培厚，才有了如今的武金堤。","page":182},{"title":"五家共管的“衬子堤”","text":"1931年以前，左岭一带没有正式的堤，五家湖、河湖只靠土埂与长江相隔，五家湖因由五家共管而得名。1936年后修起的堤长不足千米，面宽才1米左右，每隔10米在内侧打一个土衬子，俗称“衬子堤”，走向弯弯曲曲，1954年大水时曾在此溃口。","page":184},{"title":"“十八段”的由来","text":"武惠堤上有一段叫“十八段”。1931年大水后由民众自发修筑，当时救济署补助面粉，分成十八段分别培修，因此得名。由于施工质量差、各段接合不良，水位到26.7米就会出现500米长的散浸带，是历史隐患，建国后经多次加固才大大缓解。","page":190},{"title":"险中之险“万人挡”","text":"武惠堤14公里处的“万人挡”，1954年大水时破口350米，幸亏及时抢堵才没有酿成大灾，却在堤脚冲出一个长400米、宽200余米的大深潭，成为武惠堤的险中之险。此后多次加培堤身、加大压浸台、填塘，1990年和1998年又两次加宽防浪台。","page":189},{"title":"1998年的76天","text":"1998年长江、汉江洪峰在武汉叠加，先后形成8次洪峰，警戒线以上水位持续83天。洪山全区上堤人数达30万人次，处理管涌、散浸、崩岸等险情146处。从6月30日上堤到9月14日撤离，军民同洪水搏斗了76天，终于保住了大堤。","page":191}],"chapterNotes":{"1":"介绍泵站、水库、取水工程的建设与管理，以及汤逊湖、东沙湖、北湖等五大水系的治理。","2":"细说武金堤、武惠堤、左岭堤的历史与现状，堤防加固、防浪林种植和管理机构。","3":"讲万人挡、十八段等险段如何治理，以及1996、1998、1999年三场大汛的抗洪经过。"},"keywords":["长江干堤","武金堤","武惠堤","防汛抗洪","1998年洪水","险段治理","水系治理","泵站"],"chapters":[{"no":1,"title":"水利工程","page":176,"zhuanji":false,"sections":["建设工程","水系治理"]},{"no":2,"title":"防洪工程","page":181,"zhuanji":false,"sections":["长江干堤","基础设施","堤防管理"]},{"no":3,"title":"防汛抗洪","page":189,"zhuanji":false,"sections":["险段治理","大汛年份抗洪"]}]},{"id":"p07","no":7,"title":"农业","start":193,"end":251,"group":"wuchan","tagline":"金殿玉菜出洪山，鱼米菜乡供江城","lead":"如果说武汉人的冬天有一种固定的味道，那多半来自洪山的菜地。这片509平方公里的土地上，农业面积就占了460平方公里，历来是武汉的“菜篮子”和“鱼篓子”。翻开农业篇，能看到一部浓缩的乡村变迁史：民国时，佃农一年辛苦只够维持三到六个月生活；1951年土改让农民分到了田；合作化、人民公社走过弯路；1978年底关山等大队悄悄试行联产责任制，几年后全区九成以上生产队“包”了起来，农民人均收入从1983年的420元涨到2000年的4227元。蔬菜是这里的支柱产业，2000年全区上市商品蔬菜40万吨，约占武汉早市蔬菜的45%；水域16.87万亩，鲜鱼年产比1949年增长78倍。而最能代表洪山的，还是那一棵紫红色的洪山菜薹。","numbers":[{"value":"45","unit":"%左右","label":"2000年洪山上市蔬菜占武汉早市蔬菜总量的比例","page":213},{"value":"4227","unit":"元","label":"2000年农村人均收入（1983年为420元）","page":194},{"value":"78","unit":"倍","label":"2000年鲜鱼产量38538吨，比1949年增长的倍数","page":217},{"value":"16.87","unit":"万亩","label":"全区可养水面","page":193}],"stories":[{"title":"李大方的“六个一”","text":"和平乡大洲村李大方一家9口人，1984年投资7830元，置下手扶拖拉机、沼气池、猪圈、鱼塘、大棚和一片菜地，号称“六个一”。菜叶喂猪，猪粪发沼气，沼气烧饭照明，沼渣再养鱼浇菜，一年上市蔬菜12.5万公斤、肥猪80头、鲜鱼5500公斤，纯收入2万元，成了联产承包后专业户的样板。","page":198},{"title":"湖主与湖霸","text":"建国前，洪山的湖泊多被大户占为私产。清同治年间李姓大户承包青菱湖、黄家湖湖课，世代当湖主；汤逊湖被九姓、六姓分别霸占，为争湖产屡打官司甚至械斗，1918年干脆成立汤逊湖实业公司，湖主变股东。流动渔民入湖要先交“水课”，冬天湖主自捕时，渔民卖鱼所得七成以上要交给湖主。","page":220},{"title":"五色彩色珍珠","text":"洪山湖塘多，也养过珍珠。1971年起东湖、南湖等渔场试养珍珠，到1972年接种3万余只蚌，收获珍珠50余公斤。1974年，武汉市水产研究所参照南湖一处珍珠室提供的染色法，试验有核珍珠成功，培育出红、黄、绿、蓝、紫五色彩色珍珠，光彩夺目。","page":224},{"title":"黄牛挤奶起步","text":"洪山养奶牛最早从洪山公社武跃大队开始，1955年起步时用的是黄陂黄牛挤奶。后来引进良种荷兰公牛及精液逐步杂交改良，才有了黑白、黄白花的奶牛群。到80年代末，全区已有奶牛场23个，存栏奶牛2036头，年产奶4000吨。","page":230},{"title":"从木犁到微耕机","text":"建国前耕地靠木柄铁铧步犁，一人一牛一天只能耕2至3亩，灌溉靠脚踏或手摇龙骨水车，菜农挑着扁担竹筐上市。50年代推广双轮双铧犁，1958年喊出“消灭肩挑背驮”；后来青菱乡建群村一个月内购进微耕机14台，全区有14个村实现了“无耕牛村”。","page":200}],"chapterNotes":{"1":"从地主收租到土改分田，再到合作化、人民公社和家庭联产承包，看洪山农民身份的几度变化。","2":"耕地、劳力、种子、肥料和农机农具，记录洪山农业从人力畜力走向小型机械化的过程。","3":"水稻、小麦、棉花、油菜等作物的耕作制度和品种演变，双季稻曾一度占到水稻的八成多。","4":"洪山最拿手的蔬菜生产：种植规模起伏、大棚与滴灌新技术，以及红菜薹、洲藕等名优品种。","5":"依江傍湖的水产业：各大湖泊养殖、湖主旧制、人工孵化、网箱养鱼、珍珠培育和新鱼种引进。","6":"养猪、养牛、养鸡鸭的变迁，奶牛业如何从黄牛挤奶发展成城郊重要产业，以及疫病防治。","7":"从荒山造林、毁林炼钢到茶园果园开发，洪山林特生产的几个阶段与绿化成果。","8":"南湖、洪山一带聚集的农业科研机构和它们的成果，清末南湖农业试验场就设在这里。","9":"农业管理机构的分分合合，以及产业结构调整、分配制度与服务体制改革。","0":"专记洪山菜薹：从油菜的演化讲到“金殿玉菜”的贡品身世、独特小气候和原产地保护。"},"keywords":["洪山菜薹","菜篮子","联产承包","江汉湖群","水产养殖","奶牛业","都市型农业"],"caitai":{"lead":"洪山菜薹原本只产在武汉洪山一带，因茎叶紫红，又叫紫菜薹、红菜薹，是从油菜一路演化出来的芸薹菜家族成员。古人很早就爱吃菜薹：《夏小正》有“正月采芸”的记载，北魏《齐民要术》把芸薹菜列为21种重要蔬菜之一，东晋《拾遗记》说“色紫者为上蔬”。据《生物史》载，武昌红菜薹在唐代已是名菜；洪山宝通寺所产的紫菜薹质嫩味甘，曾作为贡品献给皇帝，有“金殿玉菜”之称，与武昌鱼并称楚天两大名菜。它为何偏偏长在这里最好？专家发现宝通寺一带有独特小气候：北有洪山挡寒风，南有南湖添温润；中国地质大学测定这里是高钙、富含微量元素的灰潮土。解放初红菜薹种植不到千亩，1980年已达17027亩。2004年初，洪山区投入300万元改造原产地，用GPS划出保护红线，注册“鄂洪山菜薹”证明商标，并举办第一届洪山菜薹文化艺术节。","facts":[{"value":"7000","unit":"年","label":"陕西半坡遗址出土炭化油菜籽的年代，油菜栽培史由此可溯","page":250},{"value":"17027","unit":"亩","label":"1980年红菜薹种植面积，比建国初增长16倍","page":216},{"value":"5","unit":"个月","label":"红菜薹从10月底上市到翌年春分罢园的供应期","page":216},{"value":"300","unit":"万元","label":"2004年初投入原产地沟渠改造和扩种的资金","page":251}],"quotes":[{"src":"《夏小正》","text":"正月采芸，二月荣芸。"},{"src":"《吕氏春秋》","text":"菜之美者，阳华之芸。"},{"src":"东晋王嘉《拾遗记》","text":"芸有三种，色紫者为上蔬，味辛；色黄者为中蔬，味甘；色青者为下蔬，味咸。常供御膳及宗庙祭祀。"},{"src":"李时珍《本草纲目》","text":"此菜易起薹，须采其茎食。因枝多，故云芸菜。"},{"src":"徐毓华《湖北乡土地理》","text":"马鞍之煤，宝通寺之菜，黄鹄矶头之鲤，均占优胜之土物也。"},{"src":"南宋范成大诗","text":"桑下春蔬绿满畦，菘心青嫩芥薹肥。溪头先择店头卖，日暮裹盐沽酒归。"}],"timeline":[{"time":"距今约7000年","text":"陕西半坡遗址出土大量炭化油菜籽，油菜栽培历史久远"},{"time":"夏代","text":"历书《夏小正》记“正月采芸，二月荣芸”，正月前后采摘菜薹"},{"time":"北魏","text":"贾思勰《齐民要术》把芸薹菜列为21种重要蔬菜之一"},{"time":"唐代","text":"据《生物史》载，武昌特产红菜薹在唐时已是名菜"},{"time":"明代","text":"李时珍《本草纲目》记载此菜易起薹，须采其茎食"},{"time":"1907年","text":"《湖北乡土地理》将“宝通寺之菜”列为湖北优胜土物"},{"time":"1949—1980年","text":"解放初种植不到千亩，70年代破万亩，1980年达17027亩"},{"time":"2004年","text":"投入300万元，GPS划定原产地保护红线，注册证明商标，办首届菜薹节"}]},"specialties":[{"name":"红菜薹","text":"又叫紫菜薹、洪山菜薹，吃的是嫩花茎，甜脆爽口，与武昌鱼并称楚天两大名菜，旧时作为湖北特产进贡。8月育苗、9月定植，10月底上市直到翌年春分，供应期长达5个月，是冬春当家菜。","page":216},{"name":"莲藕（洲藕）","text":"史载三国孙吴时武汉就“多藕多茭”。佳品“洲藕”主产于天兴洲，藕身肥壮、节节均匀，生吃可当水果，也能焖炒煨汤、做罐头蜜饯藕圆。1982年后洪山莲藕种植面积突破3万亩。","page":216},{"name":"黄州萝卜","text":"在青山东兴洲、八吉府一带疏松肥沃的土地上种植，方志记载有一个萝卜重10余斤的。民间称它“土人参”，民谣唱道：“萝卜上了街，药铺无买卖；萝卜进了城，药铺关了门。”80年代种植面积达2.5万亩。","page":216},{"name":"建茄一号","text":"建设乡菜科所用本地武昌鳝鱼头紫线茄作父本、成才墨茄作母本杂交育成。皮薄肉嫩、纤维少、口味香，比母本早收15天左右、增产三到四成，亩产可达3500至4000公斤，90年代种植面积达1万亩。","page":216},{"name":"彩色珍珠","text":"1974年，武汉市水产研究所参照南湖一处珍珠室提供的染色法，在洪山水域试验有核珍珠成功，培育出红、黄、绿、蓝、紫五色彩色珍珠，光彩夺目，是珍贵的装饰品。","page":224}],"chapters":[{"no":1,"title":"农业生产关系","page":194,"zhuanji":false,"sections":["封建土地所有制","土地改革","农业合作化","人民公社化","家庭联产承包责任制"]},{"no":2,"title":"农业生产条件","page":198,"zhuanji":false,"sections":["耕地 劳力","种子 肥料、","农机农具"]},{"no":3,"title":"粮棉油种植业","page":209,"zhuanji":false,"sections":["粮食种植","棉花种植","油料作物种植"]},{"no":4,"title":"蔬菜种植业","page":213,"zhuanji":false,"sections":["概况","种植规模","新技术应用","主要品种与名优特品种"]},{"no":5,"title":"水产业","page":217,"zhuanji":false,"sections":["发展沿革","水域分布","水域经营管理","水产养殖方式","捕捞","渔业赋税","渔政管理"]},{"no":6,"title":"畜牧业","page":230,"zhuanji":false,"sections":["家畜 家禽","饲料","疫病防治","技术成果与培训","畜牧管理"]},{"no":7,"title":"林业","page":236,"zhuanji":false,"sections":["林业资源","苗木繁育","植树造林","林木管理"]},{"no":8,"title":"农业科技","page":242,"zhuanji":false,"sections":["科研机构","技术推广","科研成果","交流与培训"]},{"no":9,"title":"农业管理","page":247,"zhuanji":false,"sections":["机构","产业结构调整","分配制度改革","农业服务体制改革"]},{"no":0,"title":"洪山菜薹","page":250,"zhuanji":true,"sections":[]}]},{"id":"p08","no":8,"title":"乡镇企业","start":252,"end":266,"group":"wuchan","tagline":"铁匠铺走出来的五星级酒店","lead":"1949年武汉解放时，洪山农村的工副业产值只占农业总产值的3.2%，靠的是走村串户的铁匠、木匠、箍匠，还有农家夜里织布、天亮成匹的老手艺。半个世纪后，这里的乡镇企业已达12788家，2000年营业收入198.95亿元，利税占全区财政总收入的四分之一。它是怎么长大的？最早是公社农具厂、砖瓦窑和织包头布的小作坊；70年代国家在区内大量征地，失地农民在扶持下办起织布厂；改革开放后，村里人把饭馆开进了武珞路，把激光设备、美式蝶阀做进了国家重点新产品名录。2000年，和平乡徐东集团投资6亿元，建成全国第一家村办五星级酒店。这一篇，讲的就是洪山农民“洗脚上岸”的故事。","numbers":[{"value":"12788","unit":"家","label":"2000年全区乡镇企业数量","page":253},{"value":"198.95","unit":"亿元","label":"2000年乡镇企业营业收入","page":253},{"value":"3.2","unit":"%","label":"1949年农村工副业产值占农业总产值比重","page":252},{"value":"6","unit":"亿元","label":"徐东集团建设全国首家村办五星级酒店的投资","page":257}],"stories":[{"title":"驼子店的包头布","text":"花山、白浒一带解放前就织土布，主打“清水包头”。1952年前后，驼子店一带半数以上农户兼织包头，有560台土布机，年产20万匹左右。1958年，当地与湖北省丝绸公司商定由对方供丝3万公斤、农业社加工包头出口印度等国。后来因供销等原因，这门老手艺逐渐停产。","page":255},{"title":"“童记镰刀”","text":"50年代的农具全靠手工匠人打造，铁铺岭的龚铁匠讲质量、讲信誉，深受农户喜爱。1963年，湖北省轻工业局组织全省10多个县的公社农具厂操作比赛，花山农具厂童缓华打制的镰刀受到赞誉，被评为“童记镰刀”。","page":254},{"title":"郊区第一家农民餐馆","text":"1979年11月，武汉市郊区第一家农民餐馆——和平公社三角路烤鸭店开业。1982年，洪山公社向阳大队投资150万元在武珞路盖起9层和7层两栋主楼的向阳饭店；三角路村还建起武汉第一座农民文化中心，有溜冰场、舞厅、游泳池和700座小剧场。","page":257},{"title":"村里造出激光器","text":"1994年，和平乡团结村与华中理工大学激光实验室6位科技人员合办激光设备公司，投入2000万元开发横流CO2激光加工设备等产品。1998年，其横流CO2激光器获得国家重点新产品证书。团结村先后从高校引进43名工程技术人才。","page":260},{"title":"九峰草莓结束空白","text":"90年代，九峰乡引进草莓种植技术，在500亩地上种草莓，年收入达900万元；此前青菱乡各村广种草莓，结束了武汉市郊无草莓种植的历史。天兴乡长江沙洲上的“洲瓜”也很出名，“心里红”无籽西瓜很受欢迎。","page":253}],"chapterNotes":{"1":"乡镇企业遍布农业、工业、运输建筑和商贸服务各行业，从茶场珍禽园到机械厂、织布厂、饭店商场。","2":"乡镇企业的名优产品和新产品开发，减速机、蝶阀、激光设备、摩托车等填补多项空白。","3":"管理机构、质量认证、技术引进、职工培训、职称评聘和产权制度改革，看乡镇企业如何走向规范。"},"keywords":["乡镇企业","社队企业","包头布","徐东集团","团结村","科技联姻","产权改革"],"chapters":[{"no":1,"title":"行业分布","page":253,"zhuanji":false,"sections":["农业","工业","运输建筑业","商贸服务业"]},{"no":2,"title":"产品","page":258,"zhuanji":false,"sections":["名优产品","新产品开发"]},{"no":3,"title":"企业管理","page":262,"zhuanji":false,"sections":["管理机构","质量管理","技术引进","职工教育","职称评聘","企业改革"]}]},{"id":"p09","no":9,"title":"工交 邮电","start":267,"end":296,"group":"wuchan","tagline":"从驿道独轮车到两座长江大桥","lead":"20世纪50年代以前，洪山地区没有一家像样的工业企业，货物靠肩挑背驮、独轮车运送，公文走清代驿道，民间通信全靠“信脚”。这一篇讲的，就是这片城郊如何被工厂、公路、铁轨和电话线一点点织进现代城市。1958年“全民大办钢铁”，全区6万多劳力土法上马，炼出的却是废铁；真正的变化来自改革开放后，1979年乡镇工业产值破亿，2000年工业总产值达23.17亿元。关山一带聚集着鼓风机厂、电机厂等大厂，马应龙眼药也从老字号走进南湖新厂房。交通上，武汉长江二桥、白沙洲长江大桥都落在洪山境内；南湖机场曾是湖北最大的民用航空港，1995年才把天空交给天河。到2000年，洪山农村百户已拥有电话35部。","numbers":[{"value":"680.7","unit":"公里","label":"2000年全区公路通车里程","page":268},{"value":"800","unit":"多万人次","label":"南湖机场运营期间共运送的中外旅客","page":288},{"value":"618","unit":"米","label":"白沙洲长江大桥主跨，当时国内第一、世界第三的双塔双索面斜拉桥","page":279},{"value":"23","unit":"万多户","label":"2000年洪山地区实际电话装机用户","page":268}],"stories":[{"title":"南湖机场最后一班","text":"南湖机场1936年由湖北省建设厅承建，抗战时曾被日军占作军用。新中国成立后供民航使用，是湖北省最大的民用航空港。1995年4月14日22时19分，南湖机场降落最后一个航班，第二天清晨一架波音737从天河机场起飞，南湖机场正式关闭，累计运送旅客800多万人次。","page":288},{"title":"马应龙眼药落户南湖","text":"马应龙八宝眼药始创于河北定州，明代万历年间由马金堂研制成功。1919年后人马歧山南下，在武昌斗级营开店，后改店为厂。几经公私合营与改名，1964年迁到南湖周家湾，1966年定名武汉市第三制药厂。80年代开发的马应龙麝香痔疮膏获国家经委“金龙奖”。","page":275},{"title":"唐代的长虹桥","text":"洪山乡井冈村的长虹桥建于唐代，是一座宽10米、长30米的单拱桥。明万历四十七年（1619），熊廷弼修筑邑南堤时重修了它。长虹桥是城南驿道的起点，曾是湖北省城通往江南各地的交通要道，千百年来车马行人不绝。","page":279},{"title":"万里长江第一内环","text":"武汉长江二桥位于洪山区徐东村，1995年6月18日建成通车，全长4678米，主跨400米，时为亚洲跨度最大的预应力钢筋混凝土斜拉桥。它与上游6.8公里处的武汉长江大桥组成28公里市区内环线，被称为万里长江第一条城市跨江内环线。","page":279},{"title":"大办钢铁炼出废铁","text":"1958年“全民大办钢铁”，洪山全区投入劳动力6万多人，因“土法上马”，炼出来的却是废铁。此后又刮起办厂风，郊区钢铁厂、通用机械厂、化工厂等都因资金不足、原料匮乏而停产。直到改革开放后，乡镇工业才真正崛起。","page":267}],"chapterNotes":{"1":"区属工业、驻区大厂和洪山经济开发区：从公社农具厂到电机厂、葛店化工厂与马应龙制药。","2":"公路、桥梁、渡口、长江航运、武大铁路和南湖机场，记录洪山从驿道小路到立体交通网的变迁。","3":"从清代驿站、自行车邮路到电话村村通，看洪山的邮政和电信如何一步步跟上时代。"},"keywords":["关山工业区","马应龙","武汉长江二桥","白沙洲大桥","南湖机场","武大铁路","邮政电信"],"chapters":[{"no":1,"title":"工业","page":268,"zhuanji":false,"sections":["区属工业","驻区工业企业","武汉洪山经济开发区"]},{"no":2,"title":"交通运输","page":277,"zhuanji":false,"sections":["公路运输","水路运输","铁路运输","航空运输","交通运输管理"]},{"no":3,"title":"邮政 电信","page":290,"zhuanji":false,"sections":["邮政","电信"]}]},{"id":"p10","no":10,"title":"商贸 旅游","start":297,"end":339,"group":"wuchan","tagline":"从凭票买布到拆墙开店","lead":"洪山是江南诸省进出武汉的东南门户，春秋战国时鄂君启的商船队就从这里经过。民国时，白浒、驼子店、王家店、石嘴等集镇是物资集散地，粮行、布铺、茶馆、鱼行一应俱全。新中国成立后，商品一度要凭票供应：1954年起棉布定量，1969年后每人每年布票只有1丈5尺；“文革”时下馆子要自己端菜端饭，一顿饭排两三次队。改革开放后风气一变：1987年前后，区里打开72处临街楼房底层做门面，拆掉大单位、大院校临街围墙28堵开设门点；广埠屯菜场“菜市合一”走出困境，徐东平价广场创下全国彩电亿元柜。到2000年，全区商业网点17217个，社会零售总额46.63亿元。这一篇还带你逛逛洪山的湖光山色与休闲农庄。","numbers":[{"value":"17217","unit":"个","label":"2000年全区商业网点（1988年底为1207家）","page":298},{"value":"46.63","unit":"亿元","label":"2000年全区社会零售总额","page":298},{"value":"28","unit":"堵","label":"1987—1988年拆除的大单位临街围墙，改作门点","page":329},{"value":"8","unit":"亿元","label":"徐东平价广场年销售额，创全国连锁单店最高纪录","page":324}],"stories":[{"title":"一丈五尺布票","text":"建国初，洪山人穿的多是土布，驼子店、石嘴都有土布市场。1954年起棉布定量凭票供应，每人每年2丈5尺；1961年连毛巾、袜子、内衣等10种商品都要凭票，1969年后布票减到每人1丈5尺。直到1983年才取消棉布凭票供应，可那时化纤布已经流行起来了。","page":303},{"title":"拆掉围墙开门面","text":"1987—1988年，洪山推行“打、破、调、引、改、建”六字方针：打开临街楼房底层72处，破除大单位、大专院校、科研院所临街封闭院墙28堵，开设照相、洗澡、美容、理发等门点，还引进“天龙大酒店”“鲍鱼大王”等34家名优特店。1988年底商业网点增加到1207家。","page":329},{"title":"广埠屯菜场模式","text":"广埠屯菜场1957年建场时只是一个150平方米的简易工棚。1993年一度拆菜摊、不卖菜，1994年又率先在菜场里开办集贸市场，与青菱、建设、洪山等乡直挂直销，“菜市合一”走出困境，被市政府命名为“广埠屯菜场模式”在全市推广，经营品种达1860个。","page":325},{"title":"全国第一个彩电亿元柜","text":"1997年10月，中商徐东平价广场在长江二桥南头开业，营业面积37000平方米，主打“超市百货化、百货经营超市化”。它先后创造32个单品全国销量第一，产生了全国第一个彩电亿元柜，曾以8亿元年销售额创全国连锁单店最高纪录。","page":324},{"title":"自己端菜的年代","text":"“文化大革命”中，餐馆推行“自我服务”，顾客要自己端茶端饭，吃一顿饭要排队2至3次，菜是“大锅菜”。1978年后，广埠屯餐馆、关山餐馆的红白案品种增加到100多个，洪山酒家的芙蓉鱼片、珊瑚鳜鱼、橘瓣鱼丸颇有影响。","page":316}],"chapterNotes":{"1":"个体私营、集体供销社和国营商业此消彼长，看洪山商业所有制几十年的起伏变化。","2":"百货、布匹、烟酒、粮油到生产资料，一件件商品从凭票供应走向敞开销售的历程。","3":"餐馆与服务业的变迁，从集镇米粑麻花、“自我服务”到醉江月、锦华园等大型酒楼。","4":"农贸市场、批发市场、超市和电脑城，以及广埠屯菜场、街道口劝业场等明星市场。","5":"商业行业管理、粮政管理和商业、粮食购销体制改革，告别统购统销的过程。","6":"从收购莲藕、鲜鱼、猪鬃出口，到招商引资与经济技术协作，洪山外经外贸的起步与发展。","7":"洪山的山水资源与旅游景点、酒店旅行社、科教旅游线和生态农业旅游规划。"},"keywords":["凭票供应","集贸市场","广埠屯菜场","徐东平价","街道口电脑城","外经外贸","生态农业旅游"],"sights":[{"name":"武汉东湖海洋世界","text":"坐落在东湖湖畔，建筑面积3万平方米，展示千余种、万余尾海洋珍稀鱼类，设热带雨林馆、海底隧道、极地企鹅馆、长江鱼馆、海洋剧场等9个展区，可看人鲨共舞、海兽表演，是国家AAA级旅游景点和科普教育基地。","page":334},{"name":"武汉东湖鸟语林","text":"位于东湖风景区之滨，占地32亩，是集鸟类观赏、鸟艺表演、鸟类救护于一体的主题公园。园内征集世界各地珍稀鸟类200多种8000余只，有鸬鹚高台跳水、海鸥空中接鱼等表演，还有天鹅湖、鸳鸯溪、鸵鸟园等景点。","page":334},{"name":"张公山寨","text":"毗邻武钢白玉山，与东湖风景区隔坝相望，湖面2万亩，有99个湖汊、56个山头环抱。湖边张公山、吴主寺、鼓架山等地流传着孙权、朱元璋、刘伯温、张之洞等人的典故，是集湿地生态与农业休闲于一体的生态园。","page":335},{"name":"海星楚云庄","text":"2005年创立，位于东湖磨山，占地约200亩，有水上楼阁、观鱼台和土家风味吊脚楼。游客可以吃正宗农家菜、药膳和竹制吊锅，看湖北巴山舞表演，品尝现场大锅炒瓜子花生、糍粑和石磨豆浆。","page":335},{"name":"三鲜基地垂钓中心","text":"由和平乡铁机集团创建，集鲜花种植、奶牛养殖、精养鱼池为一体，占地三百余亩。奶牛场有纯种奶牛200头，日产鲜奶2.5吨；100亩精养鱼池可休闲垂钓，配有水上餐厅、垂钓长廊和游泳池。","page":335},{"name":"东湖生态园","text":"位于东湖落雁岛，占地150亩，三面环水，与磨山隔湖相望。园内有溪流瀑布、亭台水榭、小桥流水，餐位与绿树交错分布，靠窗还能边吃边赏湖景，是集生态休闲与旅游观光于一体的农业生态园。","page":335},{"name":"渔家唱晚休闲农庄","text":"坐落在严东湖畔，四面环山、碧波万顷，远离闹市，荷苇竞生、鸟飞蝉鸣，是武汉市郊难得的休憩去处。严东湖的螃蟹体大味美，鱼类鲜嫩，龙虾肉实洁净，是这里的招牌湖鲜。","page":335}],"chapters":[{"no":1,"title":"所有制结构","page":298,"zhuanji":false,"sections":["个体私营商业","集体商业","国营商业"]},{"no":2,"title":"商品经营","page":300,"zhuanji":false,"sections":["百货","纺织品","五金交电 化工","糖烟酒副食品","第五节","土产日用杂品","废旧物资回收","粮油购销","生产资料"]},{"no":3,"title":"饮食服务业","page":315,"zhuanji":false,"sections":["餐饮业","服务业"]},{"no":4,"title":"商品市场","page":319,"zhuanji":false,"sections":["农贸市场","专业批发市场","超市、电脑市场","市场选介"]},{"no":5,"title":"商业管理","page":326,"zhuanji":false,"sections":["行业管理","粮政管理","商业经营体制改革","商业管理体制改革","粮食购销体制改革"]},{"no":6,"title":"外经外贸","page":331,"zhuanji":false,"sections":["对外贸易","招商引资与经济技术协作","外经外贸管理"]},{"no":7,"title":"旅游业","page":334,"zhuanji":false,"sections":["旅游资源","旅游景点","旅游设施","旅游经营","管理与旅游规划"]}]},{"id":"p11","no":11,"title":"金融","start":340,"end":350,"group":"wuchan","tagline":"从铜板官票到银行通存通兑","lead":"一枚铜钱有多重？清雍正年间武昌宝武局铸的制钱每文重1钱2分，到光绪三十年只剩3分2厘——钱越铸越轻，私铸小钱满街跑。金融篇就从这些老钱讲起：张之洞在武昌开铸龙洋、开办湖北官钱局，官票一度信用昭著，最后滥发到信用破产；1948年金圆券登场，几个月后一枚银元要换543万元金圆券。新中国成立后，钱袋子慢慢稳了：1952年南湖莲溪乡19户贫农凑起旭光信用合作小组，1954年东亭乡建起洪山第一个农村信用社；改革开放后，各大银行纷纷进驻，储蓄网点遍布城乡，还办起营业11小时的“夜市银行”。到2000年，由农村信用社发展而来的江南信用合作联社存款余额已达18.14亿元。","numbers":[{"value":"19","unit":"户","label":"1952年创立旭光信用合作小组的南湖莲溪乡贫农","page":343},{"value":"18.14","unit":"亿元","label":"2000年底江南信用合作联社各项存款余额","page":343},{"value":"1683","unit":"倍","label":"1947年8月米价相当于1946年1月米价的倍数","page":345},{"value":"543","unit":"万元","label":"1949年5月一枚银元可兑换的金圆券","page":345}],"stories":[{"title":"越铸越轻的制钱","text":"清雍正年间，两湖铸币的宝武局设在武昌三佛阁街，所铸制钱每文重1钱2分。咸丰元年因铜价贵减为8分，光绪二十二年张之洞改用进口铜机器铸造，重7分，到光绪三十年只剩3分2厘。钱越来越轻，民间私铸“鹅眼小钱”渔利，官府收税都不收小钱，币制一片混乱。","page":344},{"title":"官票的兴衰","text":"光绪二十二年（1896），张之洞拨银5万两、制钱5万串作基金，开办湖北官钱局发行“官票”。起初准备金充足，可完粮纳税，流通到整个长江流域。可到民国十五年，官票发行额达1.3亿串，大量垫支军政费用，信用破产，每张兑银从9钱多跌到3分，官钱局只好停业。","page":344},{"title":"金圆券的疯狂","text":"1948年8月，国民政府发行金圆券取代法币，强令百姓用黄金白银兑换。没过几个月物价狂涨：每头猪的屠宰税从5元涨到400元；1949年2月末一枚银元换金圆券961元，到5月要换543万元。此前法币贬值时，一周内米价就从每斗2100万元涨到4800万元。","page":345},{"title":"19户贫农办信用社","text":"1952年土改复查结束后，农民急需资金互助。南湖莲溪乡19户贫农率先创立旭光信用合作小组，1954年10月东亭乡成立洪山区第一个农村信用社，当年底全区就有16个。几经撤并改组，1997年发展为江南信用合作联社，2000年存款余额达18.14亿元。","page":343},{"title":"1万元换1元","text":"新中国成立之初，人民币面额最大到5万元券。1955年3月发行新人民币，旧币1万元等于新币1元；1957年发行1分、2分、5分金属分币，1980年又发行1角至1元4种金属币，因数量不多被人们收藏。1999年发行的新版100元和20元一直沿用。","page":345}],"chapterNotes":{"1":"驻区各大银行、城市信用社与农村信用社的来龙去脉，看洪山金融体系如何搭建起来。","2":"从制钱、银两、铜元、官票到法币、金圆券和人民币，一部浓缩的货币变迁史与现金管理。","3":"储蓄、信贷、保险和证券业务的发展，从贷款买水车到代缴水电费、开设夜市银行。"},"keywords":["制钱","湖北官钱局","金圆券","人民币","农村信用社","储蓄","保险证券"],"chapters":[{"no":1,"title":"金融机构","page":340,"zhuanji":false,"sections":["银行","信用社"]},{"no":2,"title":"货币","page":344,"zhuanji":false,"sections":["通用货币","人民币现金管理"]},{"no":3,"title":"金融业务","page":346,"zhuanji":false,"sections":["储蓄","信贷","保险 证券"]}]},{"id":"p12","no":12,"title":"财政税务","start":351,"end":365,"group":"wuchan","tagline":"一本账本里的半世纪家底","lead":"区里的钱从哪里来、花到哪里去？财政税务篇就是洪山的“家庭账本”。1956年洪山建立一级财政，此后几十年，市对区的分账办法几乎年年在变：一会儿“以收定支，三年不变”，一会儿“收支两条线”，一会儿“超收分成、结余留用、一年一定”，屠宰税、渔业税常常整笔留给区里。税制的变迁更像一部简化史：清末厘金名目繁多，1931年才裁撤；1950年货物税还有1136个细目，几年后简并到174目；从“税利合一”试点、武钢“一税两费”试点到两步“利改税”，再到1994年分税制、国税地税分家。账本越理越清，家底也越来越厚：1998年洪山税收突破2亿元大关，2000年财政支出达2.76亿元。","numbers":[{"value":"2.76","unit":"亿元","label":"2000年全区财政支出","page":351},{"value":"2.99","unit":"亿元","label":"2000年国税部门完成各税收入（1998年首次突破2亿元）","page":363},{"value":"1136","unit":"个","label":"1950年货物税细目数，1953年简并为174目","page":360},{"value":"6.1424","unit":"亿元","label":"2000年登记的区属国有资产总量","page":357}],"stories":[{"title":"厘金的终结","text":"鸦片战争后清政府赔款缠身，在全国征收“厘金”，各地税率不一，还常承包给乡里征收。光绪三十一年湖北改厘金为统捐，民国元年又改为过境销场税。直到1930年底，国民政府通令全国裁撤厘金，湖北急电各地在年底前一律撤销。可此后地方税捐依旧名目繁多，不胜枚举。","page":359},{"title":"千目货物税瘦身","text":"1950年开征的货物税分10大类、51个项目、1136个细目，同年7月就减并为358个；1953年又简为36项174目。1958年税制改革时，货物税与商品流通税、营业税、印花税干脆合并成了工商统一税。从繁到简，是新中国税制几十年的主旋律。","page":360},{"title":"年年变的分账法","text":"市里和区里怎么分钱？1958年是“以收定支，三年不变”；1961年改成收支两条线，区不再是一级财政；1971年恢复一级财政，超收部分对半分成；1976年起又变成“一年一定”。1978年还规定渔业税、屠宰税全部留给区里，这本账几乎年年重算。","page":353},{"title":"武汉试点“利改税”","text":"1959年，财政部在武汉等7个城市试点“税利合一”，把国营企业的税和利润合并缴纳。1981年1月，武汉又先在武汉钢铁公司试点，把上缴利润改为“一税两费”。1983年和1984年两步“利改税”推开，国营大中型企业按55%税率缴纳所得税。","page":360},{"title":"国税地税分家","text":"1994年分税制改革，洪山组建国税分局和地税分局两套机构，按税种分别征管。当年共完成4项收入1.77亿元，超收3572万元。1995年是分设后第一年，地方各税完成4961万元，到2000年增加到1.24亿元。","page":363}],"chapterNotes":{"1":"区级财政的建立与体制变迁，收入从哪来、钱花在哪，以及预算外资金、国有资产和会计管理。","2":"从清末厘金到分税制的税制演变，几十个税种的兴废，国税与地方税务的征管改革和收入增长。"},"keywords":["一级财政","分税制","利改税","厘金","货物税","国税地税","国有资产"],"chapters":[{"no":1,"title":"财政","page":351,"zhuanji":false,"sections":["机构沿革","财政收入","财政支出","预算外资金管理","第五节","会计管理"]},{"no":2,"title":"税务","page":358,"zhuanji":false,"sections":["机构沿革","第二节","地方税务"]}]},{"id":"p13","no":13,"title":"经济综合管理","start":366,"end":392,"group":"wuchan","tagline":"九个五年计划里的算盘声","lead":"经济综合管理听起来枯燥，其实藏着许多普通人的日常：一斤糖多少钱、开个小店要不要执照、商标被假冒怎么办。从1953年到2000年，洪山走过了9个五年计划：“大跃进”时提出亩产千斤稻、万斤菜的口号，结果1959年油料亩产从90公斤跌到16公斤；改革开放后，计划和市场“双轨”并行，猪肉、鸡蛋、粮食价格陆续放开。1981年6月，全区个体工商户只有230户，到2000年已登记17177户，私营企业3029户。普查数字也记下了洪山的成长：1982年第三次人口普查登记371904人，2000年第五次普查增至878388人。到2000年，洪山村人均收入达14055元，全区人均收入过万元的村有4个。","numbers":[{"value":"878388","unit":"人","label":"2000年第五次人口普查洪山区登记人口（1982年为371904人）","page":380},{"value":"17177","unit":"户","label":"2000年底全区登记个体工商户（1981年6月仅230户）","page":383},{"value":"14055","unit":"元","label":"2000年洪山乡洪山村人均收入，全区最高","page":378},{"value":"1697","unit":"件","label":"2000年全区企业注册商标","page":384}],"stories":[{"title":"千斤稻万斤菜","text":"“二五”计划时提出“千、百、万”运动：亩产千斤稻、百斤皮棉、万斤菜。1958年大办钢铁，全区投入最多达6万人，占全部劳动力的60%，炼出的却是不能用的废钢铁。到1959年，粮食亩产从153公斤降到105公斤，油料亩产从90公斤跌到16公斤。","page":369},{"title":"古巴糖卖4元","text":"解放初白糖按产地批发价加14%出售。1962年实行高价商品政策，古巴糖每斤从0.64元一下提到4元；1965年7月起古巴糖才与国产白糖同价。1984年后猪肉、鸡蛋价格陆续放开，1992年以后大部分商品价格随行就市。","page":387},{"title":"四个万元村","text":"到2000年，洪山人均收入超过5000元的村有32个，超8000元的有7个，超过万元的有4个：洪山乡洪山村人均14055元，卓刀泉村12866元，姚家岭村12207元，和平乡徐东村10000元。","page":378},{"title":"罚没走私汽车","text":"1980年，工商部门查处走私倒卖进口物品案69起，查获收录机、电子表、化纤布料、电动缝纫机等。1981年到1987年中又罚没走私日本汽车4辆、雅马哈摩托车3辆。到2000年，全区共查处走私小汽车33辆，以及VCD机、数码相机等。","page":385},{"title":"学杂费一块五","text":"1952年，洪山高小杂费1.5元，初小1元，少数民族和军烈属免缴。1966年起郊区高、初中学杂费3元，高、初小1.5元。1973年调整后，住读生交住宿费1.5元，走读生上晚自习要缴电费1元，这个标准一直执行到1985年。","page":388}],"chapterNotes":{"1":"从“一五”到“九五”，洪山各个五年计划的编制与执行，大跃进的教训和改革开放后的跨越。","2":"统计机构与报表制度，以及历次人口、农业、工业和第三产业普查留下的洪山数据。","3":"企业与个体工商户登记、商标广告、合同管理和市场监管，看个体私营经济如何壮大。","4":"审计监督与物价管理，棉花、猪肉、白糖、大米和学杂费价格从国家定价走向市场调节。","5":"计量、质量和标准化管理，洪山技术监督工作的建立与质量振兴活动。","6":"钢材、木材、汽油等计划物资的分配，以及物资部门走向市场调节的转型。"},"keywords":["五年计划","人口普查","个体工商户","私营企业","物价放开","商标管理","物资分配"],"chapters":[{"no":1,"title":"计划管理","page":366,"zhuanji":false,"sections":["机构沿革","计划编制","计划实施"]},{"no":2,"title":"统计管理","page":379,"zhuanji":false,"sections":["机构沿革","经济统计","资料管理"]},{"no":3,"title":"工商行政管理","page":382,"zhuanji":false,"sections":["机构沿革","工商企业登记管理","商标与广告管理","合同管理","市场管理"]},{"no":4,"title":"审计管理","page":386,"zhuanji":false,"sections":["审计管理","物价管理"]},{"no":5,"title":"质量技术监督管理","page":389,"zhuanji":false,"sections":["机构沿革","计量管理","质量管理","标准化管理"]},{"no":6,"title":"物资管理","page":390,"zhuanji":false,"sections":["机构沿革","计划供应","市场调节"]}]},{"id":"p14","no":14,"title":"中国共产党","start":393,"end":439,"group":"zhengshi","tagline":"从李家桥一个支部说起","lead":"洪山最早的党组织活动，可以追溯到北伐军打进武昌城的1926年。那年冬天，石嘴、南湖、青山一带纷纷成立农民协会，会员多达3万人，农民办夜校、组织自卫军。1939年，王近生在十字岭一带发展组织，在李家桥（今洪山乡李桥村）建起了洪山境内的第一个党支部。抗战中，青山、花山、九峰一带成了运送伤员和给养的秘密交通线；1948年成立的武鄂中心临时支部只有21名党员，却在渡江战役中帮解放军打开了缺口。新中国成立后，区委驻地几经搬迁，1959年起才固定在武昌珞喻路6号。这一篇还记下了很多和老百姓直接相关的事：组织近6万民工疏浚东沙港，带领群众战胜1954年的大洪水，开展“一五”到“三五”普法，以及给老干部办老年大学、组建合唱团。","numbers":[{"value":"3","unit":"万人","label":"1926年区境各农民协会会员总数","page":394},{"value":"57826","unit":"人","label":"建国初疏浚东沙港组织的民工人数","page":409},{"value":"29.73","unit":"米","label":"1954年大水时武汉关最高水位","page":409},{"value":"13349","unit":"名","label":"1982年区第三次党代会时全区党员数","page":405}],"stories":[{"title":"三万农民进农会","text":"1926年10月10日北伐军攻克武昌城，到12月，昌明（今石嘴）、永丰、南湖、青山、徐家棚等地都成立了农民协会，会员达3万人。农会带着农民反对土豪劣绅、发展生产，还开办农民学校、组织农民自卫军。1927年大革命失败后，农会和自卫军相继解体，党组织转入秘密状态继续活动。","page":394},{"title":"李家桥的第一个支部","text":"1939年2月，王近生受中共武昌县委派遣，到十字岭一带发展党组织，成立十字岭区委，并在李家桥建立党支部。李家桥就是今天洪山乡的李桥村，这个支部是洪山境域内的第一个党支部，洪山地区的中共基层组织从这里起步。","page":395},{"title":"九峰花山交通线","text":"1942年8月，鄂南工委派姜南平带一支小部队来到武昌县北部的青山、花山、九峰一带，建立武北区委。这片地方成了鄂南主力部队机动作战的重要通道，也是运送伤员和给养的交通线。1944年成立的武鄂工委又组建了多支抗日游击武装，在汤逊湖、豹澥、九峰等地配合新四军五师打击日伪军。","page":395},{"title":"21名党员迎渡江","text":"1948年春，经江汉区城工部批准，武鄂中心临时支部成立，只有21名党员，活动于今花山、九峰、左岭一带的沿江地区。渡江战役开始后，他们配合解放军占领滩头阵地、打开渡江缺口，又发动民兵、民工支援大军南下。1949年5月武汉解放，这个支部完成了使命。","page":395},{"title":"15天疏通东沙港","text":"东沙港是东湖、沙湖经青山闸流入长江的港口，因多年战乱失修淤塞，湖水排不出去，船也过不了，沿湖田地常常被淹。建国初，洪山区、挹江区和武昌县第九区联合组织民工57826人，干了15天把港道疏通，三区受益田地达11171亩，还开荒545.4亩、植树53250株。","page":409}],"chapterNotes":{"1":"从1926年的农民协会讲到抗战交通线和渡江前夜的临时支部，回顾1949年前的革命斗争。","2":"梳理建国后洪山区委的历次分合和驻地变迁，以及历任书记名录和区委下属工作机构。","3":"依次记录1956年起的历次区党员代表大会，能看到各个时期的党员人数和当时定下的奋斗目标。","4":"按时间顺序回顾区委各个时期的重大决策，从土改、修港抗洪讲到改革开放后的发展思路。","5":"介绍区纪委的恢复和重建，以及教育监督、廉政责任制和案件查处工作。","6":"讲基层支部怎样一步步建起来，也介绍干部培养、老干部门球队和合唱团、知识分子工作等情况。","7":"涉及时事宣传、理论学习、党校培训，还有党史办编写出版组织史、大事记等地方史料的经过。","8":"介绍统战部的沿革和落实政策工作，并给出区内民主党派、少数民族、宗教信众等群体的概况。","9":"讲政法委和综治办的工作，涵盖三个五年普法、治安联防队和安全小区创建，与居民生活关系较近。"},"keywords":["农民协会","李家桥党支部","武北区委","渡江战役","东沙港","1954年洪水","普法","党史资料"],"chapters":[{"no":1,"title":"建国前洪山地区中共组织","page":394,"zhuanji":false,"sections":["土地革命战争时期中共组织","抗日战争时期中共组织","解放战争时期中共组织"]},{"no":2,"title":"建国后中共洪山区地方组织","page":395,"zhuanji":false,"sections":["第一节","中共洪山区委","中共洪山区委工作机构"]},{"no":3,"title":"中共洪山区代表大会","page":404,"zhuanji":false,"sections":["中国共产党洪山区党员","第二节","中国共产党","中国共产党","中国共产党","中国共产党","中国共产党","中国共产党"]},{"no":4,"title":"中共洪山区委决策纪略","page":408,"zhuanji":false,"sections":["恢复国民经济和基本完成","开始全面建设社会主义时期","“文化大革命”时期","社会主义现代化建设新时期"]},{"no":5,"title":"纪律检查","page":415,"zhuanji":false,"sections":["教育监督","党风廉政建设责任制","案件查处"]},{"no":6,"title":"组织建设","page":417,"zhuanji":false,"sections":["基层党组织建设","第二节","干部队伍建设","党员队伍建设","老干部工作","知识分子工作","机关中共组织建设"]},{"no":7,"title":"思想建设","page":427,"zhuanji":false,"sections":["时事宣传","理论教育","思想政治工作","地方中共党史资料征集","党校教育"]},{"no":8,"title":"统一战线工作","page":432,"zhuanji":false,"sections":["机构沿革","落实政策","学习教育活动","完善多党合作和","第五节","服务经济建设"]},{"no":9,"title":"政法工作","page":435,"zhuanji":false,"sections":["机构沿革","组织协调","政法干部队伍建设","社会治安综合治理"]}]},{"id":"p15","no":15,"title":"人民代表大会","start":440,"end":462,"group":"zhengshi","tagline":"代表跑出来的一条新马路","lead":"人大代表平时都在做什么？洪山区的这一篇给出了不少具体答案。1955年4月，洪山区由选民直接选出第一届人大代表，召开了第一届人民代表大会。代表任期最早是2年，后来改为3年，第十届起改为5年。代表们闭会期间也有不少事要做，围绕老百姓关心的问题“视察、检查、调查、评议”。有一条坑洼难走的石牌岭路，10名代表上门调查，写成议案，被列为大会“第一号议案”，第二年就修好了。关山的居民被炭黑厂的粉尘困扰多年，几届代表一直呼吁，这家工厂终于在1997年底整体迁走。夹套河疏浚、天兴乡防治血吸虫，也都有代表的身影。从六届到十一届，代表们共提出议案617件、建议2439件，建议的答复率是100%。","numbers":[{"value":"1955","unit":"年","label":"选民直选产生洪山区第一届人大代表","page":440},{"value":"617","unit":"件","label":"六届一次至十一届三次会议人大议案总数","page":457},{"value":"2439","unit":"件","label":"同期代表建议数，答复率100%","page":457},{"value":"63.8","unit":"%","label":"第十一届区人大代表中大专以上文化程度占比","page":441}],"stories":[{"title":"石牌岭路成了一号议案","text":"石牌岭从前是武昌东郊的岗地，坟冢遍布、碑牌林立，因此叫这个名字。那里有一条修于20世纪50年代的小路，又窄又陡，积水横流，常出交通事故。1987年，珞南街10名代表走访群众，写出调查报告，在区八届人大二次会议上提出议案，被列为第一号议案。区政府投资20万元，加上集资7.5万元，1988年8月整治完工。","page":460},{"title":"炭黑厂终于搬走了","text":"关山的武汉炭黑厂建厂20多年，设备老化，粉尘和废气长期困扰周边居民。可它是全国十大炭黑骨干企业之一，搬迁需要约2亿元，所以这件事多年没有解决。各级代表一次次调查，还到天津、苏州、上海等地考察，提出切实可行的异地改造方案。1997年底，这家工厂整体并入郊外的葛化集团。","page":461},{"title":"夹套河不再淹宿舍","text":"夹套河是张家湾、白沙洲一带唯一的排水港道，全长6.6公里。它1952年修成后一直没有疏浚过，1983年一场大雨后，部分地区被水泡了3天，宿舍一楼没法住人。1986年1月，四级人大代表一起视察，提出综合治理的建议。市政府采纳后，按6个流量的标准进行了整治。","page":458},{"title":"再送瘟神到天兴洲","text":"血吸虫病一度被消灭，从1980年起又在长江沿线出现。天兴乡有阳性钉螺的面积从3300亩猛增到10320亩。1988年4月，代表们视察疫区，提出增拨经费、增加专业人员、在疫区设置警示牌等6条建议，得到市、区两级政府的重视，推动了当地的血防工作。","page":458}],"chapterNotes":{"1":"介绍人大代表选举的四个步骤、代表构成和任期的变化，并按届次记述1955年以来的历次大会。","2":"介绍1979年设立的区人大常委会及其下属委员会、会议制度，以及乡镇主席团和街道联络处。","3":"讲区人大怎样就普法、计生、治安等事项作出决定，怎样监督“一府两院”，以及议案建议如何办理。","4":"讲代表闭会期间的视察检查，石牌岭路、夹套河、炭黑厂等民生难题都在这一章。"},"keywords":["人大代表","直接选举","石牌岭路","武汉炭黑厂","夹套河","血吸虫防治","议案建议"],"chapters":[{"no":1,"title":"区人民代表大会","page":440,"zhuanji":false,"sections":["代表选举","第二节"]},{"no":2,"title":"区人民代表大会常务委员会","page":446,"zhuanji":false,"sections":["区人大常委会组成","工作机构与工作制度","乡镇人民代表大会主席团","街道人大代表工作联络处"]},{"no":3,"title":"区人大及其常委会主要工作","page":452,"zhuanji":false,"sections":["行使决定权","依法监督","人事任免","议案建议"]},{"no":4,"title":"闭会期间代表活动","page":457,"zhuanji":false,"sections":["祝察工作","检查工作","评议政府部门工作"]}]},{"id":"p16","no":16,"title":"人民政府","start":463,"end":484,"group":"zhengshi","tagline":"从江夏县衙到科技一条街","lead":"一百多年前，洪山归江夏县管，一县大事全由知县说了算。衙门里有“三班六房”，不少差役没有工钱，靠从老百姓打官司的规费中抽钱养家。民国年间改叫武昌县，又经历了军阀兵变、日军侵占，县政府几次瘫痪。新中国成立后，洪山区光区划调整就经历了十多次，直到1987年左岭镇划进来，才形成6个街道、2个镇、6个乡、509平方公里的格局。这一篇最有看头的，是区政府怎样借助辖区高校、科研院所多的优势谋发展：在珞喻路建起10公里长的科技一条街，请城里的退休技术人员来当“星期天工程师”。书里也记下了政府带领群众应对1954年洪水、1998年大水、2000年大旱和青菱乡地陷的经过，以及编年鉴、修地方志的事情。","numbers":[{"value":"509","unit":"平方公里","label":"2000年全区土地面积","page":463},{"value":"60.1","unit":"万人","label":"2000年全区人口，其中农业人口18.4万余人","page":463},{"value":"300","unit":"多家","label":"科技一条街建成仅1年入驻的科技企业和门店","page":463},{"value":"18733","unit":"卷","label":"1998年区档案馆馆藏档案及资料总数","page":483}],"stories":[{"title":"县衙里的三班六房","text":"晚清江夏县衙设有吏、户、礼、兵、刑、工六房，另有皂班、壮班、快班三班。按同治八年的记载，全县拿俸银的官员不过二十几人，轿夫、仵作、门斗之类的公差没有正式工资，除了地方财政给点补贴，就从老百姓的田土、婚嫁纠纷里索取规费。当时赋税很重，民间有“贫家无半月之藏”的说法。","page":464},{"title":"一夜兵变十年难复","text":"民国十年（1921），湖北督军王占元克扣军饷，引发武昌兵变。他自兼师长的鄂军第二师从6月7日夜里12点一直抢到第二天清晨，武昌城最繁华的地段被烧成一片。第二天，驻扎在金口镇的一个连又抢了典当行和商户27家。亲眼看到的人说：“全城重创，十年难复。”","page":464},{"title":"十公里科技一条街","text":"1988年，区委、区政府决定在珞喻路建一条10公里长的新技术一条街，用优惠政策吸引国内外有技术的单位和个人来创业。只用了1年，街上就有了300多家科技企业和门店，来自北京、深圳、海南等15个城市。据书中记载，建这条街投资2000万元，国家和地方财政没有出一分钱。","page":463},{"title":"请来星期天工程师","text":"1984年，区里提出“一引、两变、三迎接”的方针，其中一项是欢迎城里工厂的科技人员和退休人员来当顾问、做“星期天工程师”，让乡镇企业成为大专院校、研究所、大工厂新技术的中试基地。1987年又出台10条优惠政策，鼓励技术人才走出高楼深院，到乡镇企业承包、领办企业。","page":477},{"title":"乔木湾突然地陷","text":"区政府施政纪略里记了一场少见的灾害：青菱乡乔木湾发生岩溶地陷，先后发现陷坑17处，最大的直径70多米，倒塌和部分倒塌的房屋有59间。区领导及时组织救灾，把住在危险地段的196户群众安全转移。同一部分还记录了1998年的特大洪水和2000年的大旱。","page":477}],"chapterNotes":{"1":"从晚清江夏县衙讲到民国武昌县政府、日伪维持会，再到建国后区政府十多次分合。","2":"按时间顺序记录区政府各个时期的主要施政，从土改、抗洪讲到科教兴区和乡镇企业发展。","3":"介绍区政府法制办和监察局的设立，以及依法行政、专项监察、纠正不正之风等工作。","4":"介绍侨联、民族宗教和对台工作，包括侨眷牵线的中外交流和区内各宗教信众人数。","5":"讲信访接待制度的建立、档案馆藏规模，以及《洪山区志》《洪山年鉴》等地方文献的编修过程。"},"keywords":["江夏县","三班六房","武昌兵变","区划调整","科技一条街","星期天工程师","乔木湾地陷","洪山年鉴"],"chapters":[{"no":1,"title":"机构沿革","page":464,"zhuanji":false,"sections":["建国前县署机构","建国后区级人民政府"]},{"no":2,"title":"区人民政府施政纪略","page":474,"zhuanji":false,"sections":["国民经济恢复及基本","开始全面建设社会主义时期","“文化大革命”时期","社会主义现代化建设新时期"]},{"no":3,"title":"法制 监察","page":478,"zhuanji":false,"sections":["法制工作","监察工作"]},{"no":4,"title":"侨务 民族 宗教事务 对台工作","page":480,"zhuanji":false,"sections":["侨务工作","民族宗教事务","对台工作"]},{"no":5,"title":"信访 档案 地方志","page":482,"zhuanji":false,"sections":["信访工作","档案工作","地方志工作"]}]},{"id":"p17","no":17,"title":"人民政协","start":485,"end":496,"group":"zhengshi","tagline":"一条银鲫鱼游出千万产值","lead":"政协委员都是些什么人？在洪山，有华中农业大学的教授，有水产专家，也有医生、书画家和各界人士。区政协成立于1983年12月，第一届有委员139人，到第五届增加到218人。他们做的事，很多和老百姓的餐桌、饭碗直接相关。政协常委陈本德推广“异育银鲫”养殖，提出“1144”工程，后来的高体鲫养殖工程3年实现产值8276万元。教授把实验室培育的莲米苗送到花山镇的田里，蔬菜专家到青菱乡教农民种茭白。洪山乡上下马庄的回民群众喝水困难，委员们调查后写成提案，2000年问题得到解决。区政协还牵头到北京海淀考察，为建设“科技一条街”出主意，又编了14辑《洪山文史》，为地方留下244.7万字的史料。","numbers":[{"value":"218","unit":"人","label":"第五届区政协届初委员数（第一届为139人）","page":486},{"value":"1551","unit":"件","label":"1983年12月至2000年1月受理的政协提案","page":494},{"value":"15850","unit":"亩","label":"推广3年后的异育银鲫养殖面积","page":492},{"value":"244.7","unit":"万字","label":"14辑《洪山文史》征集的稿件总量","page":495}],"stories":[{"title":"陈本德和他的鱼","text":"1984年，区政协常委陈本德看到洪山养殖水面多，开始推广“异育银鲫”，3年后养殖面积达到15850亩。之后他去广东学习技术，提出“精养、高产、优质、高效”的建议，又提出千亩连片高产攻关试验。区政协的“1144”工程建议案，目标是1万亩鱼池亩产千斤。到1993年，他又推出高体型异育银鲫养殖模式，在全区大面积推广。","page":492},{"title":"要建“武汉硅谷”","text":"1987年2月，区委提出要把洪山建成“武汉硅谷”。4月，由区政协牵头，区里有关领导到北京海淀区考察。区政协主席会议随后提出9条建议，并在常委会议上正式提交建设洪山“科技一条街”的建议案。此后几年，委员们又围绕科技工业园和一条街的延伸规划不断提出建议。","page":493},{"title":"教授下田送莲苗","text":"1984年3月，区政协副主席、华中农业大学教授王就光把实验室培育的300株莲米种苗送到花山镇大田里栽种，还给农民讲莲米育种藕的方法和蔬菜病虫害防治，听讲的有700多人次。1997年，区政协又请蔬菜专家到青菱乡红霞村传授茭白种植技术，并买了335本农技书免费送给农户。","page":493},{"title":"马庄回民喝上好水","text":"洪山乡上下马庄的回民群众长期饮水困难。1999年，区政协组织委员去现场调查视察，并写成提案。在区政府和有关部门的支持下，这个问题在2000年得到解决。珞南街政协联委也根据委员建议，推动修建了石牌岭荷花池、吴家湾、卓刀泉等集贸市场，方便附近居民买菜。","page":494}],"chapterNotes":{"1":"介绍1983年成立的区政协，五届委员的人数、界别和学历构成，以及各工作机构。","2":"讲委员们怎样建言献策，从银鲫养殖、科技一条街到马庄饮水，还有提案和文史编研。"},"keywords":["区政协","异育银鲫","陈本德","武汉硅谷","科技一条街","提案","洪山文史"],"chapters":[{"no":1,"title":"组织机构","page":485,"zhuanji":false,"sections":["政协洪山区委员会","工作机构","乡镇街政协联络委员会"]},{"no":2,"title":"政协工作","page":492,"zhuanji":false,"sections":["政治协商","民主监督","提案工作","对外联络","文史编研","基层政协工作"]}]},{"id":"p18","no":18,"title":"民主党派 工商联","start":497,"end":505,"group":"zhengshi","tagline":"皮鞋厂进商场，老板当村官","lead":"说到民主党派和工商联，很多人觉得离自己很远。其实在洪山，他们做的不少事就发生在身边。到2000年，6个民主党派在洪山建立了区工作委员会，一共283人，成员大多是教师、医生、工程师和企业家。民进成员多在中小学任教，常到边远乡镇学校上课、评课，他们的提案促成了区职业技术教育中心和示范高中的建设。农工党成员大多在医药卫生界，经常下乡义诊，给乡村医生办讲座。工商联在1956年就开始在洪山活动，到2000年有会员325人。有一家快停产的小皮鞋厂，经工商联牵线“引厂进店”，进了中南商业大楼，一年产值从二十几万元涨到八十万元。九峰乡新洪村还出现了民营企业家当村支书、当选村长的事，开了民营企业家任村官对口扶贫的先例。","numbers":[{"value":"283","unit":"人","label":"2000年末洪山6个民主党派区工委总人数","page":497},{"value":"325","unit":"人","label":"2000年末区工商联会员数","page":504},{"value":"146","unit":"件","label":"1993—2000年民建洪山工委集体和个人提案","page":502},{"value":"1435","unit":"万元","label":"区工商联“光彩事业”扶贫总投资","page":505}],"stories":[{"title":"武汉民进从这里起步","text":"洪山是武汉市民进组织的发源地。1953年，华中师范学院院长杨东莼受民进中央委托，在武汉筹建民进组织。五六十年代，华师、武大都有民进支部，后来武昌中小学里的民进会员也多是由这些老会员介绍入会的。1986年以前，洪山只有马房山中学1个支部、16名会员。","page":500},{"title":"提案建起职教中心","text":"民进会员多是中小学教师，提案也多和教育有关。他们提出大力发展职业技术教育，区政府采纳后把石牌岭中学建成洪山区职业技术教育中心；提出兴建示范高中，示范高中后来建成；还建议抓住高校扩招的机会，区内随后建设了3处高校学生公寓。","page":501},{"title":"小皮鞋厂进了大商场","text":"80年代末90年代初市场疲软，区里不少企业产品积压，有的半停产。工商联四处联系武汉的大商场帮会员找销路。卓刀泉中学办的远新皮鞋厂原本快停产了，经牵线以“引厂进店”的方式进入中南商业大楼经营，1990年一年产值就从二十几万元增加到八十万元。","page":505},{"title":"企业家当上村长","text":"1995年起，区工商联开展“光彩事业”，组织民营企业对口扶贫。武汉当代科技发展公司和九峰乡新洪村联合成立农工商股份公司，对全村进行综合开发，公司总经理艾路明被任命为村党支部书记，后来又当选村长。书中称这是民营企业家任村官对口扶贫的第一例。","page":505}],"chapterNotes":{"1":"民革洪山区工委从只有6人的综合支部发展而来，曾捐助中山舰修复、资助贫困小学生。","2":"民盟洪山组织成立于1981年，成员中高级教师较多，常送教下乡，多提教育方面的提案。","3":"讲洪山作为武汉民进发源地的由来，以及民进会员推动职教中心、示范高中建设的提案。","4":"民建洪山组织1987年以9名会员起步，成员多在工业企业，常就国企改革提出建议。","5":"农工党洪山区工委成员多在医药卫生界，常下乡义诊、给乡村医生上课，还提出过农村改水等提案。","6":"九三学社洪山区工委2000年成立，成员中高级职称占89%，其中有全国劳模。","7":"区工商联1958年成立，中断多年后恢复，为会员企业找销路，开展光彩事业扶贫。"},"keywords":["民主党派","工商联","民进发源地","职教中心","引厂进店","光彩事业","企业家村官"],"chapters":[{"no":1,"title":"中国国民党革命委员会洪山区工作委员会","page":497,"zhuanji":false,"sections":["组织机构","第二节"]},{"no":2,"title":"中国民主同盟武汉市洪山区工作委员会","page":499,"zhuanji":false,"sections":["组织机构","主要工作"]},{"no":3,"title":"中国民主促进会武汉市洪山区工作委员会","page":500,"zhuanji":false,"sections":["组织机构","主要工作"]},{"no":4,"title":"中国民主建国会武汉市洪山区工作委员会","page":501,"zhuanji":false,"sections":[]},{"no":5,"title":"中国农工民主党武汉市洪山区工作委员会","page":501,"zhuanji":false,"sections":["组织机构","主要工作","组织机构","主要工作"]},{"no":6,"title":"中国九三学社武汉市洪山区工作委员会","page":503,"zhuanji":false,"sections":["组织机构","参政任职"]},{"no":7,"title":"洪山区工商业联合会","page":504,"zhuanji":false,"sections":["组织沿革","历届代表大会","主要工作"]}]},{"id":"p19","no":19,"title":"人民团体","start":506,"end":531,"group":"zhengshi","tagline":"十万知青曾在这片郊野","lead":"农会、工会、共青团、妇联、科协、残联，这些团体陪伴过好几代洪山人。1927年武昌县第一次农民代表大会召开后，农民协会烧地契、减租子，提出“一切权力归农会”。1951年，武昌郊区成立了新中国成立后的第一个农民协会。工会从1960年起步，到2000年已有会员3.2万人。90年代遇到下岗潮，工会搞起“送温暖”工程，设立困难职工求助热线；妇联办起“巾帼家政服务站”，帮下岗女工做钟点工、开家庭小饭桌。残联十年间组织白内障复明手术686例，也为残疾人安排就业。团区委每年3月5日都组织志愿者上街修钟表、补自行车。这一篇专门有一节讲知青：1968年到1976年，洪山先后接收安置回乡和下乡知识青年近10万人。","numbers":[{"value":"10","unit":"万人","label":"1968—1976年洪山接收安置的回乡和下乡知青（近）","page":531},{"value":"3.2","unit":"万人","label":"2000年全区工会会员","page":508},{"value":"686","unit":"例","label":"1990—2000年残联组织的白内障复明手术","page":530},{"value":"820","unit":"人次","label":"巾帼家政服务站3年安置的下岗女工","page":524}],"stories":[{"title":"一切权力归农会","text":"1927年1月，武昌县召开第一次农民代表大会。之后农民协会建立了农民自卫军，在张家铺、青山一带打击土豪劣绅，烧掉地主的地契，开展减租，喊出“一切权力归农会”。同年“七一五”分共后，农会和自卫军转入地下。1951年3月，武昌郊区成立了新中国成立后的第一个农民协会，暂时代行乡村政权的职能。","page":507},{"title":"知青下乡到洪山","text":"1957年，团区委按照“自愿报名、家长同意”的办法，组织中学青年分三批下乡学习劳动。1962年以后，城里的社会青年越来越多，插队成了一条出路，到1963年12月，全市已有千余名知青到洪山农村插队落户。1968年11月到1976年，全区先后接收安置回乡和下乡知青近10万人。","page":531},{"title":"送温暖与求助热线","text":"90年代，工会坚持实施“送温暖”工程，1991到1996年筹集资金300多万元，帮助了4000多人次。1997年募集“送温暖基金”，现场捐款就有62.8万元。1999年春节，区总工会开通困难职工救助热线，7天接到求助电话73人次。工会还建立再就业基地，帮助5570人次职工重新上岗。","page":514},{"title":"巾帼家政服务站","text":"1998年初，区妇联配合再就业工程，在下岗女工中开展“巾帼家政服务行动”，率先办起洪山区巾帼家政服务站。各街道、居委会随后建起服务队和服务点，提供钟点工、家庭幼儿园、家庭小饭桌、家庭护理等服务。3年里共安置下岗女工820人次，多次被评为市“十佳”巾帼家政服务站。","page":524},{"title":"重见光明的686人","text":"1990年区残联成立后，开展白内障复明、小儿麻痹症矫治、聋儿听力语言训练三项康复，后来扩大到7项。十年里完成白内障复明手术686例、小儿麻痹症矫治239例。区内有各类残疾人25000人，到2000年共安置有劳动能力的残疾人就业4000人次。","page":530}],"chapterNotes":{"0":"专记知识青年上山下乡，从1957年首批中学生下乡讲到洪山安置近10万名知青。","1":"从1927年的农民协会讲到建国初代行乡村政权的农会，以及之后的贫协和农会。","2":"介绍区工会的历次代表大会、劳动竞赛和劳模表彰，以及“送温暖”、帮扶困难职工和再就业。","3":"讲团区委组织学雷锋、青年志愿者、希望工程和少先队等活动，以及历次团代会。","4":"讲区妇联历届妇代会，以及巾帼建功、双学双比、五好家庭和巾帼家政服务等活动。","5":"介绍科协的科普站、科普橱窗和青少年航模比赛，残联的康复就业，以及区青联。"},"keywords":["农民协会","知识青年","上山下乡","送温暖工程","巾帼家政","青年志愿者","残疾人康复","科普"],"chapters":[{"no":1,"title":"农民协会","page":506,"zhuanji":false,"sections":["组织沿革","主要活动"]},{"no":2,"title":"洪山区工会","page":508,"zhuanji":false,"sections":["组织沿革","洪山区工会会员代表大会","主要工作"]},{"no":3,"title":"中国共产主义青年团洪山区委员会","page":517,"zhuanji":false,"sections":["组织沿革","洪山区共青团代表大会","主要工作"]},{"no":4,"title":"洪山区妇女联合会","page":523,"zhuanji":false,"sections":["组织沿革","洪山区妇女代表大会","主要工作"]},{"no":5,"title":"其他人民团体","page":525,"zhuanji":false,"sections":["第一节","洪山区残疾人联合会","洪山区青年联合会"]},{"no":0,"title":"知识青年上山下乡","page":531,"zhuanji":true,"sections":[]}]},{"id":"p20","no":20,"title":"司法","start":532,"end":565,"group":"zhengshi","tagline":"从挨家查炉灶到人手一张身份证","lead":"说到公检法，很多人只会想到抓坏人。这一篇里其实有不少和普通人日常生活有关的事。1950年，公安在天兴洲查出11亩大烟苗，新政府随后开始禁毒，旧社会留下的烟毒逐步被禁绝。1955年，民警挨家挨户检查炉灶，一次就查出2256个不安全的灶。1953年，公安管理的“特种行业”里还有评书场和皮影场；到2000年，名单上换成了几百家印刷厂和汽车修理铺。1986年3月洪山开始发身份证，当年就发出15万多张。法院的离婚案卷也能看出社会变化：1956年农业合作社普遍建立后，农村离婚案里93%是女方起诉。司法局1981年成立时只能借广播站两间房办公，到2000年，全区已有调解委员会327个，调解成功率达97.3%。","numbers":[{"value":"158157","unit":"人","label":"1986年洪山首批领到居民身份证的人数","page":538},{"value":"97.3","unit":"%","label":"1985—2000年人民调解组织调解民间纠纷的成功率","page":564},{"value":"93","unit":"%","label":"1956年农村离婚案中由女方起诉的比例","page":553},{"value":"3000","unit":"多件","label":"2000年区公证处年办证量（组建时不足百件）","page":563}],"stories":[{"title":"天兴洲的大烟苗","text":"1950年2月，政务院颁布严禁鸦片烟毒的通令。同年5月6日，有人在天兴洲种了11亩大烟苗，被当时的青山公安局查获，没收烟土47两。1952年6月，郊区成立禁毒办事处，查处吸毒违法人员337人。此后毒品犯罪逐步得到控制，在洪山境内一度禁绝。","page":537},{"title":"评书场也归公安管","text":"建国初，旅店、旧货、刻字、印刷等行业都被列为“特种行业”，由公安管理。1953年，全区登记的特种行业有50家，其中有评书场2家、皮影场1家、电影院1家、旅栈44家。1964年，修自行车和修钟表也被纳入管理。到2000年，特种行业增加到833家，其中印刷业301家、机动车修理业240家。","page":538},{"title":"挨家挨户查炉灶","text":"洪山郊区的消防工作从1955年开始。那年11月，公安分局开展防火、防特、防盗、防灾害事故的“四防”宣传，在46246户中查出不安全炉灶2256个，改好了1685个，还检查出年久失修的烟囱309个。第二年，全区配备了473名防火员，组建了1522人的义务消防队。","page":538},{"title":"合作社后她们敢离婚了","text":"1950年《婚姻法》废除包办婚姻、纳妾和童养媳。1956年农业合作社普遍建立后，区法院审结的44件农村离婚案中，有41件是女方起诉，其中27件是因为入社后男女同工同酬、生活有了保障，女方才敢提出离婚。1981年新《婚姻法》实施后，法院改以夫妻感情是否确已破裂作为判离的基本标准。","page":553},{"title":"借两间房起家","text":"1981年6月9日，洪山区司法局成立，只借了区广播站的两间房办公。区公证处组建时有3名公证员，一年办证不到百件，到2000年一年能办3000多件，业务扩展到婚前财产公证等120多种。律师事务所1984年成立时只有4名律师，2000年发展到3所16人，累计办案5000多件。","page":563}],"chapterNotes":{"1":"公安这一章讲派出所和联防队的变迁，以及禁毒、禁赌、特种行业管理、户口和身份证、消防等工作。","2":"检察院这一章介绍审查批捕、经济检察、监所检察和控告申诉等各项业务。","3":"法院这一章讲刑事、民事、经济和行政审判，离婚、继承、劳动争议、房产纠纷能反映社会的变化。","4":"司法局这一章讲公证和律师从无到有，人民调解网络的建立，以及刑释人员安置帮教工作。"},"keywords":["禁毒","特种行业","身份证","消防","婚姻法","人民调解","公证","律师"],"chapters":[{"no":1,"title":"公安","page":533,"zhuanji":false,"sections":["机构沿革","惩治犯罪","治安管理","户政管理","消防管理"]},{"no":2,"title":"检察","page":539,"zhuanji":false,"sections":["机构沿革","刑事检察","法纪检察","经济检察","监所检察","控告申诉检察","第七节"]},{"no":3,"title":"审判","page":547,"zhuanji":false,"sections":["机构沿革","刑事审判","民事审判","经济审判","行政审判","案件复查"]},{"no":4,"title":"司法行政","page":563,"zhuanji":false,"sections":["机构沿革","公证 律师","第三节","第四节"]}]},{"id":"p21","no":21,"title":"军事","start":566,"end":588,"group":"zhengshi","tagline":"千年兵家地，洞里也读书","lead":"洪山是武汉的东大门和南大门，山多湖多，自古就是攻打武昌城的必经之地。南宋时岳飞在这一带屯兵8年，三次从这里北伐抗金；元末徐寿辉的义军以“吃甘蔗”为暗号，里应外合拿下武昌；太平军三次在洪山与清军交战，东湖边的九女墩纪念的就是战死的女兵。1938年那场“四二九”空战，飞行员陈怀民驾机撞向日机，坠落的日机有的就掉在青山、洪山一带。日军占领洪山近7年，左岭“上罗村”被反复洗劫，从此被叫作“破罗村”。新中国成立后，部队和民兵一次次上堤抗洪，1984年还用3个多月修通了磨山环山路。当年“深挖洞”修的防空洞，后来被改成教室、仓库，还有人在里面养蘑菇、养娃娃鱼。","numbers":[{"value":"8","unit":"年","label":"南宋岳飞在洪山、白浒、长虹桥一带屯兵时间","page":572},{"value":"21","unit":"架","label":"1938年“四二九”空战击落的日机","page":574},{"value":"5.4","unit":"公里","label":"1984年部队55天完成路基的磨山环山道路全长","page":585},{"value":"156","unit":"个","label":"七八十年代全区修建的各类人防工程","page":587}],"stories":[{"title":"东湖边的九女墩","text":"1854年10月，清军攻占洪山，太平军守将率部从东门经洪山撤出武昌，在洪山和清将塔齐布的部队遭遇，双方血战。太平军的童子军和女兵几百人奋战到底，最后集体投东湖牺牲。东湖北岸的“九女墩”，就是乡民为纪念9位女战士修建的。","page":573},{"title":"陈怀民撞向敌机","text":"1938年4月29日，39架日机来袭武汉，中国空军升空迎战。飞行员陈怀民被5架日机围攻，脱身不得，便开足油门撞向一架日机，与敌同归于尽。这场空战前后约30分钟，共击落日机21架，残骸分别落在孝感、黄冈、梁子湖以及青山、洪山等地，中国空军也损失了12架飞机。","page":574},{"title":"58人夜袭机场","text":"1943年冬，日军强迫几千名民工在白浒湾修建军用机场。1944年6月20日黄昏，汤楚英、姜明斋带着58人，分乘5条民船绕过沿江据点，午夜在白浒湾上岸，用机枪打灭探照灯后发起突袭，20分钟就结束战斗，自己无一伤亡。日军第二天扑了个空，此后停建了白浒机场。","page":574},{"title":"上罗村变破罗村","text":"1938年到1942年，日军三次进入左岭的上罗村。第一次拆门板、楼板烧火做饭，第二次拆房砍树，第三次把仅剩的两人合抱的大树和村前一排枣树全部砍光，13幢房屋被拆。全村四姓13户60人，有6人被杀害。经过这场劫难，上罗村从此被叫作“破罗村”。","page":575},{"title":"防空洞里上自习","text":"华中理工大学在喻家山下有一处地下工事，从洞口到实验室约1000米，顶部覆盖的岩土超过40米。因为恒温、隔振，这里被用来做引力实验，通道里还装修了十几间教室，可供四五百人上课自习。全区的人防工程到2000年有44.5%被利用起来，有人在里面种食用菌、养娃娃鱼。","page":587}],"chapterNotes":{"1":"介绍驻区军事机关、医院和部队，清末南湖陆军中学堂等老军校，以及历代地方武装。","2":"从清代募兵、民国抽壮丁讲到新中国的志愿兵役、义务兵役和预备役，能看出百姓当兵方式的变化。","3":"讲洪山的历代战事，从岳飞屯兵、太平军三战洪山到“四二九”空战，附日军罪行录。","4":"讲民兵组织几经变化，以及花山民兵连拉练、历次抗洪抢险中的民兵队伍。","5":"写驻军支援关山工业区、修建磨山环山路，以及抗洪英雄高建成的事迹。","6":"介绍人防工程从“深挖洞”到平战结合、以洞养洞，还有初中生的“三防”课程和防空演练。"},"keywords":["岳飞","太平军","九女墩","四二九空战","白浒山机场","破罗村","磨山环山路","人防工程"],"chapters":[{"no":1,"title":"军事机构 驻军 地方武装","page":567,"zhuanji":false,"sections":["军事机构","驻军","地方武装"]},{"no":2,"title":"兵役","page":571,"zhuanji":false,"sections":["解放前兵役制度","解放后兵役制度"]},{"no":3,"title":"战事","page":572,"zhuanji":false,"sections":["民国以前战事","民国时期战事"]},{"no":4,"title":"民兵","page":576,"zhuanji":false,"sections":["组织机构","组织建设","军事训练","第四节","保卫和建设社会主义"]},{"no":5,"title":"拥政爱民","page":583,"zhuanji":false,"sections":["第一节","防汛救灾","支援地方社会主义建设","参加“三支”“两军”","军民共建“两个文明”活动"]},{"no":6,"title":"人民防空","page":586,"zhuanji":false,"sections":["人民防空机构","防空工程建设及开发利用","“三防”教育与演练"]}]},{"id":"p22","no":22,"title":"劳动 人事 社会保障","start":589,"end":610,"group":"zhengshi","tagline":"从铁饭碗到劳动合同","lead":"父母那一辈常说“顶职”“铁饭碗”“八级工”，这些说法在这一篇里都有出处。建国初期，有些人的工资是按大米折算的；1952年改为八级工资制，“工资分”一度是计算工资的单位。在计划经济年代，工作靠国家统一招工分配，父母退休了还能让一个子女“顶职”进厂。改革开放后，劳动服务公司、技术工人交流会、劳动力市场相继出现。1998年，洪山的职业介绍中心装上大型电子屏，开始滚动发布招工信息。到2000年，区里80%的企业完成改制，职工告别了“全民工”“集体工”的身份，全部签订劳动合同。退休金也从企业自己发，变成由国家、单位、个人三方共同缴费，全区建立了65758个养老保险个人账户。职工人均年工资从1981年的584元涨到了2000年的3237元。","numbers":[{"value":"584","unit":"元","label":"1981年职工人均年工资（2000年为3237元）","page":589},{"value":"65758","unit":"人","label":"2000年洪山地区建立养老保险个人账户人数","page":610},{"value":"15368","unit":"人次","label":"1992—2001年经劳动力市场实现再就业的下岗职工","page":600},{"value":"2265","unit":"人","label":"1986—2000年办理退休、死亡职工农村子女招收转户粮关系","page":603}],"stories":[{"title":"用大米算工资","text":"武汉刚解放时，几种工资制度同时存在：机关人员多实行供给制，接收的旧公教人员照领原工资，少数从东北解放区来的人员用实物（大米）作为工资计算单位。1952年第一次工资改革，工人实行八级工资制，统一以“工资分”计算；1956年取消“工资分”，改为直接按人民币定工资标准。","page":594},{"title":"父母退休子女顶职","text":"职工退休后招收一个符合条件的子女进单位工作，是劳动部1956年首次提出的。此后这项政策几停几复，1978年又恢复并形成制度，1983年起因病提前退休的已不再办理子女顶职。家在农村、25岁以下未婚的子女也能进原单位，1987年洪山一年就招了253人。","page":603},{"title":"告别全民工身份","text":"1986年，洪山开始在全民所有制单位试招合同制工人。1991年，洪山商场等3家单位试点全员劳动合同制。1995年区政府规定，凡是与区内企业、机关、团体建立劳动关系的人，都要签劳动合同。到2000年底，80%的区属企业完成改制，职工不再分“全民”“集体”，全部实行劳动合同制。","page":604},{"title":"大屏幕上找工作","text":"1998年7月1日，扩建后的洪山区职业介绍服务中心与市劳动力市场信息联网，大屏幕滚动发布招工和求职信息。政府还出资安排年龄偏大的特困下岗职工去做保安、保绿、保洁。1992到2001年，经劳动力市场推荐就业32316人次，其中下岗职工再就业15368人次。","page":600},{"title":"养老金三方来出","text":"过去退休费全由企业负担。1995年起改为国家、单位、个人三方共同负担，个人先按工资的3%缴费，以后逐步提高到8%。发放实行“新人新办法、中人中办法、老人老办法”：1995年以后参加工作的人，退休后按个人账户余额除以120按月领取。","page":610}],"chapterNotes":{"1":"讲劳动管理的方方面面，从招工顶职、八级工资讲到劳动力市场、下岗再就业和全员劳动合同制。","2":"讲干部管理、职称评聘、军转干部安置、大中专毕业生分配，以及机关事业单位工资改革。","3":"讲劳动保险怎样从企业自己负担过渡到社会保险，以及养老保险个人账户的建立。"},"keywords":["八级工资制","顶职","铁饭碗","劳动合同制","下岗再就业","劳动力市场","养老保险"],"chapters":[{"no":1,"title":"劳动","page":590,"zhuanji":false,"sections":["管理机构","职工队伍","国家计划安置","劳动工资","“再就业”工程","劳动保护","劳动监察","劳动争议仲裁","退休顶职退职","劳动制度改革"]},{"no":2,"title":"人事","page":604,"zhuanji":false,"sections":["管理机构","干部管理","人才交流","工资制度改革","编制工作"]},{"no":3,"title":"社会保障","page":608,"zhuanji":false,"sections":["管理机构","劳动保险","养老保险"]}]},{"id":"p23","no":23,"title":"民政","start":611,"end":630,"group":"zhengshi","tagline":"从施粥救荒到农民有养老金","lead":"清末民国时，穷人日子过不下去，往往只能指望慈善团体在春荒时施粥、施衣。新中国成立后，冬令救济、春荒救济开始由政府来做。这一篇记的都是贴近百姓生活的事：洪山大水不断，1954年、1998年的洪灾里，民政部门每天派卡车转移灾民，每人先发7.5公斤大米、5公斤面条。2000年乔木湾发生地陷，3天里塌出18个坑，但无一人伤亡。1981年，和平乡建起农村福利院，25位五保老人住了进去。1992年，洪山被列入全国农村社会养老保险试点，农民也开始有了养老金。结婚要登记，丧葬要火化，村委会第一次“海选”，新街道取名有了规矩，“卓刀泉”“石牌岭”这些老地名被保留了下来。","numbers":[{"value":"88151","unit":"人次","label":"1992—2000年农村社会养老保险投保人数","page":618},{"value":"100","unit":"%","label":"1999年洪山区火化率","page":623},{"value":"94","unit":"%","label":"到2000年复员退伍军人安置率（共安置2902人）","page":611},{"value":"4092.94","unit":"万元","label":"1993—2000年洪山销售社会福利彩票总额","page":620}],"stories":[{"title":"大水来时卡车接人","text":"1998年7月初，建设乡建洲、天兴乡、青菱乡花园三个民垸的堤防先后溃口，全区受灾人口10万多人。从6月30日起，民政部门每天派10辆大卡车转移安置灾民，每人先发7.5公斤大米、5公斤面条。各界捐款640万元，连同区政府拨付的救灾款一起发到灾民手里。","page":617},{"title":"乔木湾三天十八坑","text":"2000年4月6日下午，青菱乡烽火村乔木湾突然发生岩溶地面塌陷，范围东西长300米、南北宽250米，3天内先后塌出大小18个坑，最深约15米，倒塌和损坏房屋50栋。政府紧急转移安置灾民196户，18个陷坑全部回填，这场灾害没有造成人员伤亡。","page":617},{"title":"五保老人住进福利院","text":"1981年11月，洪山区第一所农村社会福利院在和平乡建成，25位五保老人住了进去。到1999年底，8个乡镇都有了福利院，共有床位396张，五保老人入院率达到70%。区社会福利院1986年刚建成时只有1辆三轮车，用水用电都靠大队，后来才接通自来水、修了水泥路。","page":618},{"title":"棺材拆了一千多具","text":"清末民初，武汉流行土葬，实行火葬的人甚至会被以“不孝”论罪。1950年起，武汉市逐步推行火葬。1976年，市民政局在花山公社开现场会推动移风易俗，花山公社一下子拆掉了早年备好的棺材1047具。到1999年，洪山区火化率达到100%。","page":623},{"title":"给新街道起名字","text":"1998年，区地名办经过一年调查，制定了地名命名规划：大致南北走向、与长江平行的路叫“大道、路”，东西走向、与长江垂直的路叫“大街、街、巷”，居民小区叫“园”。“卓刀泉”“街道口”“石牌岭”“四眼井”“八吉府”等老地名被保留下来，新区则出现了“彩虹园”“关山园”等名字。","page":622}],"chapterNotes":{"1":"介绍民政机构的变迁，以及救灾救济、社区服务、农村保障、优抚工作四个方面的改革。","2":"讲烈士陵园和清明祭扫、抚恤金发放、退伍军人安置，以及拥军优属活动。","3":"讲历次水灾、地陷中的救灾，以及福利院、农村养老保险、福利工厂和福利彩票。","4":"讲婚姻登记、社团登记、地名命名、行政区界勘定，以及从土葬到火葬、石门峰公墓改造的殡葬改革。","5":"从1999年村委会首次海选讲到居委会改为社区，还有珞南街社区服务经验在全国推广。","6":"介绍残疾人康复就业和老龄工作，包括重阳敬老活动和乡镇老年学校。"},"keywords":["社会救济","1998年洪水","乔木湾地陷","五保老人","农村养老保险","殡葬改革","地名规划","村委会海选"],"chapters":[{"no":1,"title":"民政机构与体制改革","page":612,"zhuanji":false,"sections":["民政机构","民政工作体制改革"]},{"no":2,"title":"优抚安置","page":613,"zhuanji":false,"sections":["褒扬","抚恤安置","拥军优属"]},{"no":3,"title":"社会救济与福利","page":615,"zhuanji":false,"sections":["困难灾害救济","社会福利"]},{"no":4,"title":"社会事务管理","page":620,"zhuanji":false,"sections":["婚姻登记管理","社团登记管理","地名、勘界管理","殡葬改革"]},{"no":5,"title":"基层政权建设","page":624,"zhuanji":false,"sections":["村民委员会建设","居民委员会建设","社区建设与服务"]},{"no":6,"title":"残疾人与老龄事业","page":628,"zhuanji":false,"sections":["残疾人事业","老龄事业"]}]},{"id":"p24","no":24,"title":"教育","start":631,"end":720,"group":"wenjiao","tagline":"从两所学堂到二十所大学","lead":"晚清时，今洪山一带只有两所初等小学堂；1934年全区县立、私立小学加起来，学生才185人。直到1958年，花山、挽月、十里铺等12所中学开办，郊区才结束了“没有中学”的历史。半个世纪后，画面完全不同：2000年全区有各类学校218所、在校生近9万人，小学适龄儿童入学率100%；更惊人的是，华中科技大学、华中师范大学、华中农业大学、中国地质大学、武汉理工大学等20余所高校都“住”在洪山，让这里成为全国智力最密集的地区之一。这一篇从幼儿园一路写到大学，也写了盲童学会“定向行走”、聋生学美术、农民扫盲、民办学校兴起，以及老人们在老年大学里学古筝、练木兰拳——一部“人人有学上”的变迁史。","numbers":[{"value":"218","unit":"所","label":"2000年末全区各类学校，在校学生88859人","page":632},{"value":"20","unit":"余所","label":"洪山辖区内的高等院校","page":677},{"value":"12","unit":"所","label":"1958年郊区首批创办的中学，从此结束郊区无中学的历史","page":631},{"value":"60","unit":"所","label":"2000年底社会力量办学校数，在校生14085人","page":703}],"stories":[{"title":"郊区第一批中学","text":"1958年以前，武汉郊区连一所中学都没有。这一年，花山、挽月、十里铺、七十一中等12所中学同时开办，第一年招了58个班、2733名学生，教职工124人。不过随后几年学生劳动太多，十里铺中学的土高炉还评上过“先进炉”，课堂教学反倒受了影响。","page":631},{"title":"四个女孩的盲校","text":"武汉市盲童学校前身是1919年美籍瑞典传教士创办的武昌瞽目女校，开办时只有4名女盲童、1名教师。1961年迁到洪山石牌岭，是湖北唯一的盲人学校。学校开设“定向行走”课，盲生人人学一样乐器，还首创盲人舞蹈；按摩专业毕业生中有人当上了主任医师。","page":692},{"title":"武汉第一个无盲区","text":"解放初的冬学里，农民一般能认200来个字，学会记账写便条。到1980年4月，全区13个公社都成为基本无盲公社，16—40岁的7048人基本脱盲，洪山获得武汉市农村第一个“基本无盲区”称号。后来扫盲对象扩大到45岁，全区建起11万多份文化户口册。","page":699},{"title":"学校开酒家","text":"1980年代，区教育局的勤工俭学办公室办过印刷厂、鹌鹑饲养场、汽车运输队，还开了一家“钟声滋补酒家”，是全市教育系统最早办的酒店之一，生意一度最为兴旺，收入用来补贴办学、安置教职工待业子女。1999年酒家改制，门面对外出租。","page":711},{"title":"老年大学里的冠军","text":"1986年洪山区老年大学建校时只有一间教室、一门保健课、46名学员；到2006年已开109个班、学员2348名。课程从古诗词、书法到钢琴、古筝、电脑，学员们还在全国木兰武术比赛中夺得6枚金牌，在香港国际武术大奖赛上捧回金牌。","page":719}],"universities":[{"name":"华中科技大学","text":"2000年5月由华中理工大学、同济医科大学、武汉城市建设学院合并组建。前身华中工学院成立于1952年，后首批列入“211工程”，合并时有两院院士14名。","page":678},{"name":"华中师范大学","text":"源头可追溯到1871年的文华书院，1953年定名华中师范学院，1985年改为现名。至2000年共培养16万人才，被誉为“中南地区人民教师的摇篮”。","page":679},{"name":"华中农业大学","text":"前身是1898年张之洞创办的湖北农务学堂，1952年组建华中农学院。校园在南湖狮子山，三面环湖，占地7425亩，以农科为优势、生命科学为特色。","page":680},{"name":"中国地质大学（武汉）","text":"前身是1952年由北大、清华等校地质系组建的北京地质学院，1975年南迁武汉，以地球科学为特色。建校以来先后有60余位院士在校工作、任教。","page":681},{"name":"武汉理工大学","text":"教育部直属“211工程”重点建设高校，拥有4座图书馆、藏书300万册，全日制本专科生28000余人；光纤传感器、高速船舶、电动汽车等成果走向产业化。","page":682},{"name":"中南财经政法大学","text":"2000年由中南财经大学与中南政法学院合并组建，源自1948年创建的中原大学，以经济、法学、管理为主干。校园占地2300亩，运动场曾作全国大学生运动会主会场。","page":683},{"name":"中南民族学院","text":"国家民委直属，1951年创建，坐落南湖之滨，建有全国第一家民族学博物馆。曾为确定毛南、仫佬、土家、京等民族成分提供依据，女书研究受世界关注。","page":684},{"name":"武汉体育学院","text":"1953年创办于南昌，1955年迁至东湖之畔，是新中国首批高等体育学府之一。以水上和重竞技项目见长，学生在奥运会、亚运会等赛事中夺得金牌273枚。","page":684},{"name":"武汉大学测绘学院","text":"前身是1956年成立的武汉测量制图学院，后改武汉测绘科技大学，2000年并入新武汉大学。中国南极测绘研究中心设于此，被国际测绘界誉为“测绘教育之都”。","page":685},{"name":"湖北工学院","text":"1985年由湖北轻工业学院和湖北农业机械专科学校合并组建，湖北省重点建设高校，1986年获硕士学位授予权，也是全国重点建设的职业技术教育师资培训基地。","page":686},{"name":"武汉化工学院","text":"1972年创建，原名湖北化工石油学院，1980年改为现名，位于光谷中心。其混凝土增强密实剂解决了水布垭工程技术难题，脱墨剂供应全国七成以上大中型造纸企业。","page":686},{"name":"武汉科技学院","text":"1978年经国务院批准创建，位于南湖之滨，以纺织服装为特色，设有纺织服装学院等5个二级学院，与英国利兹大学等合作办学，已培养各类人才12000余人。","page":687},{"name":"湖北商业高等专科学校","text":"创办于1907年，前身湖北商业中学学堂，开中国商科职业教育之先河。百年间多次更名，校名始终不离一个“商”字，2000年被评为全国毕业生就业工作先进集体。","page":687},{"name":"湖北广播电视大学","text":"1979年1月创办的省属开放大学，形成省、市、县三级办学网络，有589个教学班（点）。至2000年累计输送大专毕业生近20万人，完成各类培训40万余人次。","page":688},{"name":"湖北函授大学","text":"1984年创办的民办公助成人高等函授学校，实行“超前指导—自学—辅导—面授—复习—考试”六环节教学法，至2000年共招收各类学员5万多人。","page":688},{"name":"长江职业学院","text":"1999年在湖北经济管理大学基础上建立的民办高职院校，是当时湖北唯一有资格颁发高等学校毕业文凭的民办学校，已向社会输送毕业生近两万人。","page":689},{"name":"武汉职业技术学院","text":"1999年3月由武汉无线电工业学校、湖北省国防科技工业职工大学合并成立，后又并入电子、纺织服装两所学校，2000年在校生13000名，设12个系、42个专业。","page":689},{"name":"湖北省经济管理干部学院","text":"1983年在省工业学校基础上成立，同年设国家经贸委武汉培训中心。实行毕业证与职业资格证“多证制”，并与美国高校合作举办MBA教育。","page":690},{"name":"华中科技大学武昌分校","text":"创建于2000年10月，当年占地110亩，招生380人，开设计算机科学与技术、电子科学与技术、新闻学、通信工程4个专业。","page":690},{"name":"洪山区电视大学","text":"前身是1985年成立的洪山区电大工作站。1999年秋首批开办开放教育本科专业，改写了洪山没有自己本科学历教育的历史。","page":690}],"chapterNotes":{"1":"从公社幼儿园到省级示范园，讲保教结合、园本课程和学前班管理。","2":"小学从解放初46所发展到百余所，看学制课程、第二课堂和鲁巷、街道口等名校。","3":"1958年郊区始办中学，此后几经起伏，形成关山、卓刀泉、英格等各具特色的中学。","4":"华科、华师、华农、地大等20余所驻区高校逐一介绍，洪山因此成为智力密集高地。","5":"百年盲校与第二聋校，盲生学定向行走和按摩，聋生学美术、读职业高中。","6":"农民扫盲、文化技术学校、职工培训和职业高中，洪山成为武汉农村第一个基本无盲区。","7":"民主党派、企事业和个人兴办的60所民办学校，补充了公办教育的不足。","8":"教育经费从哪里来、校舍怎么建，还有学校办厂开酒家的勤工俭学往事。","9":"教育管理机构的分合、教育督导与办学体制、职业教育结构改革。","0":"1986年建校的洪山区老年大学，从一间教室到百余个班，老人们学有所乐。"},"keywords":["高校密集","普九达标","扫盲","武汉盲童学校","民办教育","老年大学","勤工俭学","职业教育"],"chapters":[{"no":1,"title":"幼儿教育","page":633,"zhuanji":false,"sections":["概況","教学","师资","幼儿教育管理","幼儿园选介"]},{"no":2,"title":"小学教育","page":645,"zhuanji":false,"sections":["概况","学校 教师 学生","学制、课程","教学","德育","体育 卫生 艺术教育","小学教育管理","学校选介"]},{"no":3,"title":"中学教育","page":662,"zhuanji":false,"sections":["概况","学校 教师学生","学制 课程","教学","德 育","体育卫生","中学管理","学校选介"]},{"no":4,"title":"高等教育","page":677,"zhuanji":false,"sections":["概況","学校简介"]},{"no":5,"title":"特殊教育","page":691,"zhuanji":false,"sections":["概况","学校简介"]},{"no":6,"title":"职业技术教育 成人教育","page":698,"zhuanji":false,"sections":["概况","职业技术教育","成人教育","职业技术教育","学校选介"]},{"no":7,"title":"社会力量办学","page":703,"zhuanji":false,"sections":["概况","社会办学管理","学校选介"]},{"no":8,"title":"教育经费 教育设施 勤工俭学","page":707,"zhuanji":false,"sections":["教育经费","教育设施","勤工俭学"]},{"no":9,"title":"教育事业管理","page":711,"zhuanji":false,"sections":["第一节","教育督导","教育体制改革"]},{"no":0,"title":"洪山区老年大学","page":718,"zhuanji":true,"sections":[]}]},{"id":"p25","no":25,"title":"科学技术","start":721,"end":751,"group":"wenjiao","tagline":"珞喻路上，长出一个“武汉硅谷”","lead":"说洪山是“科技之区”并不夸张：放鹰台出土的稻壳烧土、宝通寺的南宋万斤铁钟，说明这里的先民很早就懂种稻、制陶、铸造。到了现代，大学和研究院所扎堆于此——2000年驻区科研、设计机构多达190多个，全区科技人员12750人。这一篇最精彩的，是一条街的故事：1987年，受北京中关村“电子一条街”启发，洪山决定把珞喻路建成“科技一条街”，鼓励科技人员下海办企业；短短几年，街上冒出几百家民营科技公司，后来又沿着大学周边建起15个孵化器，被称作“全国第一条科技企业孵化带”。邮科院在这里建起国内第一条实用市话光纤通信工程，东湖开发区成为全国首批新技术开发区试点。从“小改小革”到光纤、激光、生物医药，洪山的科技之路写满了“敢为人先”。","numbers":[{"value":"12750","unit":"人","label":"2000年底全区科技人员总数","page":728},{"value":"46","unit":"%","label":"2000年科技进步对经济增长的贡献率","page":722},{"value":"700","unit":"多家","label":"1990年科技一条街上的民营科技企业","page":732},{"value":"15","unit":"个","label":"沿大学周边建成的科技孵化器，号称“全国第一条科技企业孵化带”","page":733}],"stories":[{"title":"导弹工程师来办企业","text":"1985年4月，原航空航天工业部第三设计所导弹自动控制室工程师刘金生离职，从北京来到洪山，创办了洪山区第一家民办科研机构——洪峰电子应用技术开发部。此后民办科技机构接连诞生，到1988年底全区登记近100家，洪山科技一条街初见雏形。","page":723},{"title":"照着中关村建一条街","text":"1986年《人民日报》报道了中关村电子一条街的崛起，给洪山很大启发。1987年洪山提出建武汉“硅谷”，组团赴北京海淀考察，决定把珞喻路建成科技一条街。一期工程从陆军总医院到街道口，二期延至卓刀泉，后来又向东伸到关山，总长10多公里。","page":732},{"title":"一根光纤打30路电话","text":"1974年在吴家湾建立的武汉邮电科学研究院，是国家专业化光纤通信基地。它研制的光通信端机可在一对光纤上同时传输30路到1920路电话；1982年，又在武汉建成国内第一条34MB/S实用市话光纤通信工程，此后推广到北京、广州等十几个城市。","page":727},{"title":"企业也会“孵化”","text":"1987年6月7日，武汉东湖新技术创业中心成立，这是中国第一家企业“孵化器”，专门扶持刚起步的科技小企业。1989年首批17家高新技术企业在开发区诞生，到1990年1月已发展到73家，当年总收入首次突破1亿元。","page":749},{"title":"大起大落再出发","text":"科技一条街1992年底有民营科技企业410多家，可东湖开发区政策更优，当代科技、力源电子等税源大户纷纷迁走，1997年底只剩不足100家。洪山随后调整思路，到2000年民营科技企业回升到189家，年销售过千万元的有12家，实现亿元企业零的突破。","page":730}],"chapterNotes":{"1":"区属农业科研机构与民办科研机构，加上邮科院等驻区院所，盘点洪山的科研家底。","2":"科技人员从1986年的3779人增至2000年的12750人，驻区高级人才高度密集。","3":"民营科技企业的创立、发展、转型、壮大四个阶段，以及珞喻路科技一条街的兴衰与新生。","4":"1986—2000年的科技项目与鉴定成果，涵盖蔬菜、水产、工业等领域。","5":"科技沙龙、信息网、技术交易所与厂校“联姻”，看科技成果如何走进乡镇和企业。","6":"区科委从1960年建立到几经分合的沿革，以及科技“三项费”等经费管理。","0":"东湖新技术开发区从“经济小区”设想到国家高新区，成为光纤通信与生物医药重镇。"},"keywords":["科教兴区","科技一条街","民营科技企业","孵化器","光纤通信","东湖开发区","三联一创"],"chapters":[{"no":1,"title":"科研机构","page":722,"zhuanji":false,"sections":["区属科研机构","驻区科研机构"]},{"no":2,"title":"科技人员","page":727,"zhuanji":false,"sections":["第一节","第二节"]},{"no":3,"title":"民营科技企业","page":730,"zhuanji":false,"sections":["发展沿革","洪山区科技一条街"]},{"no":4,"title":"科技成果","page":733,"zhuanji":false,"sections":["科技项目","自然科学研究成果"]},{"no":5,"title":"科技市场","page":741,"zhuanji":false,"sections":["市场开发与管理","厂校科技协作","科技成果转化"]},{"no":6,"title":"科技管理","page":747,"zhuanji":false,"sections":["管理机构","经费管理"]},{"no":0,"title":"东湖高新技术开发区","page":748,"zhuanji":true,"sections":[]}]},{"id":"p26","no":26,"title":"文化体育","start":752,"end":775,"group":"wenjiao","tagline":"古塔摩崖之间，唱响武汉之夏","lead":"洪山是建国后才新设的行政区，起步时连一座文化馆、一块正规运动场都没有，乡亲们的娱乐只有过年舞龙灯、划采莲船。可脚下这片土地并不“年轻”：东湖边的放鹰台埋着五六千年前的稻壳烧土，元代的洪山宝塔八角七级、高十三丈三尺，明代九峰山崖壁上还刻着朱元璋写给僧人无念的诗文。这一篇一手写“新”——文化馆、图书馆、影剧院、游泳馆陆续建起，“武汉之夏”社区展演从1978年办到2000年共22届，农民运动员横渡长江、赛龙舟拿回冠军；一手写“老”——遗址、摩崖、古塔、古桥、古庙一一点名，连“三月二十八吃甘蔗”的天齐会来历都讲得明明白白。新旧交织，正是洪山文化的底色。","numbers":[{"value":"10.5","unit":"万册","label":"区图书馆总藏书，人均0.2册，高于全省人均0.12册","page":754},{"value":"22","unit":"届","label":"1978—2000年已举办的“武汉之夏”社区展演","page":758},{"value":"13000","unit":"斤","label":"同治年间大修时洪山宝塔新安的铸铜塔刹重量","page":767},{"value":"294","unit":"枚","label":"至2000年全区运动员获市级以上金牌数","page":774}],"stories":[{"title":"三月二十八吃甘蔗","text":"洪山东侧的东岳庙供奉黄飞虎，农历三月二十八“天齐会”这天，绅商百姓结伴上山，又叫“甘蔗节”。民谣唱：“三月二十八，洪山敬菩萨，钱多吃甘蔗，钱少吃麻花。”相传元末邹普胜智取武昌，约定内应手持甘蔗为号，此后民间便有这天吃甘蔗消灾的说法。1938年庙会被禁，甘蔗节从此消失。","page":770},{"title":"“东土西天”变“东王西天”","text":"青菱湖畔的云隐寺俗称青菱寺，明清时有大小殿宇36幢。太平军东王杨秀清曾进驻附近，寺庙在战火中几乎烧光，唯独一座殿里的木匾“东土西天”因“土”字上方剥落一块，恰似多了一横，成了“东王西天”。杨秀清见了，特意下令把这座殿保留下来。1956年这里改建为青菱小学。","page":769},{"title":"关羽卓刀出清泉","text":"相传东汉末年关羽驻兵伏虎山麓，天旱无水，他一急之下把刀往地上一插，泉水涌出，这就是“卓刀泉”。碑文说泉水“冬温而夏洌”“味甘如酒”。明初楚王朱桢为泉筑井台、修石栏，亲书“卓刀泉”三字。1993年，这里建成洪山区第一个公园——卓刀泉公园。","page":769},{"title":"农民也能拿冠军","text":"1978年，洪山公社风光大队的三位农家妇女参加全市横渡长江，包揽女子组前三名。1987年风光村农民代表武汉参加全省首届农民游泳赛，夺得女子团体冠军；1988年风光村农民龙舟队又拿下国际龙舟邀请赛冠军。同年和平乡办起首届农民运动会，720名运动员参赛，在湖北全省尚属首次。","page":773},{"title":"大喇叭响遍村湾","text":"50年代刚建广播站时没有专线，借电话线传信号，每天早中晚开广播，手摇电话就得停用。后来铁丝作线、木杆架起，1969年喇叭进了农户，1972年入户率达到95%。天兴洲当时不通电，公社自买发电机办广播，1976年被评为全国广播宣传先进单位。","page":771}],"relics":[{"name":"放鹰台文化遗址","text":"位于东湖西岸，相传因李白在此观看放鹰得名。1965年发掘出羼有稻壳的烧土，鉴定为粳型稻，另有磨光石斧、陶鼎等，属屈家岭文化类型，距今6000—5000年，1959年公布为市级文物保护单位。","page":765},{"name":"南湖“老人桥”遗址","text":"位于南湖周家大湾，因附近有“老人桥”地名而得名，60年代中期发现。高地面积约9000平方米，散布石斧、石凿和灰陶鼎、罐、网坠等，属新石器时代晚期聚落，1981年列为省级文物保护单位。","page":766},{"name":"许家墩遗址","text":"在花山镇联合村严西湖边，分大、小许家墩，面积7000平方米，采集有蓝纹缸片、鼎足、石斧、纺轮等，属湖北龙山期文化。小许家墩像一盘圆石磨立在田中，1983年列为市级文物保护单位。","page":766},{"name":"棋子墩、后山遗址","text":"同在花山镇联合村，1984年全市文物普查时发现，由棋子墩和后山两个台地构成，面积约4000平方米。采集到石斧、石铲、石凿和鸭嘴形鼎足、黑陶豆把等，属湖北龙山期文化，遗址保存较好。","page":766},{"name":"洪山摩崖","text":"在洪山南坡宝塔周围。南宋庆元元年（1195），赵淳在山上建东岩阁，依怪石形态命名“云扃”“栖霞”“翠屏”“狮子峰”等八景并刻于石上。如今仍有七景字迹清晰，1959年列为市级文物保护单位。","page":766},{"name":"九峰摩崖","text":"在九峰山九峰寺后崖壁。明洪武年间，无念禅师的高徒开龛刻下朱元璋御制“谕僧无念”诗文，正书30行计930字，四周饰腾龙祥云；左侧另刻无念禅师端坐像。是研究武汉佛教史和朱元璋佛教思想的珍贵实物。","page":767},{"name":"洪山宝塔","text":"又名灵济塔、宝通塔，元至元十七年（1280）始建，历时11年完工，号称“鄂中第一”。八角七级，高13丈3尺，内有旋转石级可登。同治年间大修换上重13000斤的铜塔刹，1956年列为省级文物保护单位。","page":767},{"name":"北洋桥","text":"在和平乡，是武汉市唯一尚存原貌的古石拱桥，单拱坡顶，结构似赵州桥。碑文称“此桥兴自唐代”，明代屡建屡圮，民国四年（1915）乡人李凌重建。抗战时引桥改成混凝土坡，1988年列为市级保护文物。","page":768},{"name":"黄鹄亭","text":"在洪山宝通寺之后，因矶名黄鹄而得名。宝通寺界内原还有斗牛亭、秋香亭、映月亭、遇仙亭、悠然亭、百子亭和白云阁，如今均已无存。唐代诗人李白游洪山时，曾留下《望黄鹄山》诗篇。","page":768},{"name":"晋安寺和无影塔","text":"晋安寺建于南朝梁代，隋代改名兴福寺。南宋咸淳六年（1270）重建时建无影塔，传说塔下有井通江。寺早毁，1963年无影塔移建洪山西麓，塔内发现铜佛像和宋代铜钱二百多枚，为省级文物保护单位。","page":768},{"name":"修静寺","text":"在洪山右侧，寺址相传是唐代大书法家李邕（李北海）的旧宅，传说寺僧天如在此修成正果。李白游江夏时专程来参拜，留下“我家北海宅”的诗句。修静寺今已无存。","page":769},{"name":"青菱寺（云隐寺）","text":"位于青菱湖畔，相传常有祥云缭绕、古寺若隐若现，故名云隐寺，明清时有殿宇36幢。传说建文帝曾驻锡于此；太平天国时仅存一殿，因匾额被看成“东王西天”而保留，1956年改建为青菱小学。","page":769},{"name":"岳忠武王庙","text":"岳飞平反后，乾道六年（1170）鄂州民众在洪山立忠烈庙祭祀，后改称鄂王庙，庙旁有岳飞手植的“岳松”。元代被拆毁，明正德十四年（1519）重建，清同治十三年（1874）再修，今已无存。","page":769},{"name":"卓刀泉（关圣庙）","text":"又名御泉寺，位于伏虎山麓，相传关羽卓刀出泉，明初楚王朱桢亲书“卓刀泉”。这里是武昌城东古驿道隘口，屡经战火，现存建筑为1916年重建，1959年定为市级文物保护单位，1988年恢复为寺庙。","page":769},{"name":"东岳庙","text":"建在洪山东侧，供奉东岳大帝黄飞虎。每年农历三月二十八办“天齐会”，又称“甘蔗节”，百姓烧香踏青、吃甘蔗祈福，热闹非凡。1938年国民政府以防空袭为由禁办庙会，此后这一节俗不复存在。","page":770},{"name":"九峰庙（正觉寺）","text":"在九峰山狮子峰下，依坡建上下九重院落，号称“九十九重天”，占地近200亩，兴旺时僧尼各七八十人。相传建于明洪武年间，朱元璋曾赐诗文和器用。历经兵劫火劫，1964年改作骨灰盒存放处，1996年后逐渐拆除。","page":770}],"chapterNotes":{"1":"文化馆、图书馆、博物馆到遗址摩崖、宝塔古桥古庙，再到广播进村，盘点洪山文化家底。","2":"业余体校与游泳馆，学校、职工、农民、老年人体育，以及武术、横渡长江等竞技佳绩。"},"keywords":["洪山宝塔","卓刀泉","放鹰台遗址","九峰摩崖","武汉之夏","甘蔗节","横渡长江","农民运动会"],"chapters":[{"no":1,"title":"文化","page":752,"zhuanji":false,"sections":["文化设施","文化社团","群众文化","文艺创作","第五节","文物 古迹","广播电视","文化管理"]},{"no":2,"title":"体育","page":772,"zhuanji":false,"sections":["体育设施","群众体育","竞技体育","体育管理"]}]},{"id":"p27","no":27,"title":"卫生","start":776,"end":814,"group":"wenjiao","tagline":"送走“瘟神”，人均寿命多活24岁","lead":"洪山地处古云梦泽，湖塘密布，在过去既是中草药的宝库，也是疾病的温床。老歌谣里唱“患病求神，死生由命；孕妇临产，自行接生”；血吸虫病让湖乡人“腰鼓形，乌脚板，黄眼睛”，一些村湾成了“寡妇墩”“无人村”；血丝虫病又叫“粗腿子”，腿肿得“八人围一席，狗子不能钻桌底”。这一篇讲的，就是洪山人怎样一步步把这些“瘟神”送走：民间有治蛇伤的草医、正骨的“教师爷”；新中国成立后有新法接生员、背着药箱的赤脚医生，有4万多人上天兴洲围堤灭螺的冬天。到1999年，全区医疗卫生机构241个，人均期望寿命从1949年的50.5岁提高到75.1岁。数字背后，是几代医护人员和普通农民共同打赢的一场健康仗。","numbers":[{"value":"75.1","unit":"岁","label":"1999年人均期望寿命，1949年仅50.5岁","page":776},{"value":"241","unit":"个","label":"1999年底全区医疗卫生机构，含村级医疗站146个","page":776},{"value":"13285","unit":"人","label":"至1979年全区累计发现的血吸虫病人","page":800},{"value":"4","unit":"万多人","label":"1977年冬奔赴天兴洲围堤灭螺的军民","page":803}],"stories":[{"title":"“谭半天”看病","text":"清光绪年间，九峰秀才谭汉卿在王店自设药店行医。他每看一个病人，都要把病情来龙去脉、处方用药一五一十讲给患者听，一个病人要花很长时间，乡亲们便送他雅号“谭半天”。他终身行医，70多岁去世，是洪山私人坐堂行医史上的早期人物。","page":777},{"title":"跟乞丐学来的蛇医","text":"建设公社群力大队的傅木林7岁时，从一位叫李长子的乞丐那里学会了治蛇伤的法子，20世纪30年代起行医40多年，治蛇伤的药物就有70多种，蜈蚣、蝎子螫伤也能治，只是秘方从不外传。九峰还有祖传蛇医用磁针放血、敷草药治毒蛇咬伤。","page":783},{"title":"从“咬脐”到新法接生","text":"旧时接生，产婆用碎瓷片、镰刀甚至锈剪刀断脐，没人接生时产妇只好用口咬断脐带，孩子就取名“咬脐”，产褥热和“脐带风”夺去许多母婴生命。1952年郊区第一批新法接生员培训出来，消毒产包进了村，1955年后全区基本消灭新生儿破伤风。","page":792},{"title":"江心岛上的灭螺大会战","text":"1977年夏，天兴公社突然暴发血吸虫病急性感染，当年查出病人1057人，阳性率达32.5%。11月下旬，全区9个公社农民、驻军和全市支援人员4万多人登上江心的天兴洲，奋战两个月筑起35华里长堤，灭钉螺面积8000多亩。","page":803},{"title":"赤脚医生能开刀","text":"合作医疗兴起后，赤脚医生成了农村不脱产的“家门口医生”：打预防针、给饮水消毒、看感冒肠炎、清创缝合样样能干，青菱公社红霞大队的赤脚医生还能做阑尾切除手术。1981年起他们开始领国家津贴，后来159人晋升为乡村医生。","page":791}],"chapterNotes":{"1":"从清末王店的中药铺、建国前60余家个体诊所，到第十二医院、乡镇卫生院和驻区大医院。","2":"民间蛇医、正骨“教师爷”与单方验方，再到脑外科、显微外科，以及抗洪救灾中的医疗队。","3":"合作医疗与赤脚医生的兴起、培训和转型，以及村医疗站的初级卫生保健达标。","4":"旧法接生的风险与新法接生的推广，农村妇女“五期”保护和儿童保健。","5":"爱国卫生运动、饮水与食品卫生、学校卫生和传染病防治，天花、霍乱等逐步绝迹。","6":"血吸虫病、血丝虫病、钩虫病、疟疾等地方病的惨痛历史与几十年的围歼战。","7":"区卫生局的沿革，医政药政、人事财务和公费医疗管理。"},"keywords":["血吸虫病","血丝虫病","赤脚医生","合作医疗","新法接生","民间草医","天兴洲灭螺","人均寿命"],"chapters":[{"no":1,"title":"医疗机构 卫生团体","page":777,"zhuanji":false,"sections":["建国前医疗机构","建国后医疗机构","卫生团体"]},{"no":2,"title":"诊疗技术","page":783,"zhuanji":false,"sections":["中医","西医","护理技术","救灾医疗"]},{"no":3,"title":"农村合作医疗与初级保健","page":789,"zhuanji":false,"sections":["农村合作医疗与赤脚医生","农村初级卫生保健"]},{"no":4,"title":"妇幼保健","page":791,"zhuanji":false,"sections":["农村推广新法接生","农村妇女“五期”保护","农村妇科病检查与治疗","儿童保健"]},{"no":5,"title":"卫生防疫","page":794,"zhuanji":false,"sections":["爱国卫生运动","饮水卫生","食品卫生","环境卫生","劳动卫生","学校卫生","传染病防治"]},{"no":6,"title":"地方病防治","page":798,"zhuanji":false,"sections":["血吸虫病疫情及防治","血丝虫病流行及防治","钩虫病防治","第四节"]},{"no":7,"title":"卫生事业管理","page":812,"zhuanji":false,"sections":["管理机构","医政药政管理","人事财务管理","公费医疗管理"]}]},{"id":"p28","no":28,"title":"精神文明创建","start":815,"end":833,"group":"minsheng","tagline":"从扫“垃圾山”到挂“十星牌”","lead":"“文明”两个字听起来有点抽象，可在洪山区志里，它是一件件看得见的事。1982年第一个“文明礼貌月”，全区21万多人次上街扫除，一个月清掉“垃圾山”238处、4万多吨；唐家墩街把“垃圾多、污水多、晴天灰尘多、雨天泥水多”等“七多”逐一治好。农村里，村干部敲锣打鼓给“双文明户”挂匾，后来又评起“爱国星、致富星、卫生星”等“十星级农户”；城里，关山街1991年办起全市第一所市民文明学校，“不随地吐痰、不乱穿马路”的“十不”规范家喻户晓。还有离休老人江诗信，把5万元家财捐给大山里的孩子，冒着大雪翻山去把辍学兄妹接回学校。到2001年，洪山被命名为省级文明城区——这背后，是几十年一点一滴的习惯改变。","numbers":[{"value":"219600","unit":"人次","label":"1982年首个“文明礼貌月”上街搞卫生的人数","page":828},{"value":"449","unit":"个","label":"至2000年全区文明单位数，1984年首届仅表彰26个","page":816},{"value":"7800","unit":"米","label":"1992年军民共建文明大道全长（石牌岭至关山口）","page":832},{"value":"126","unit":"所","label":"1997年全区市民文明学校数，培训市民10万人以上","page":831}],"stories":[{"title":"雪地里走来的“希望老人”","text":"严西湖渔场离休干部江诗信当过10年校长，离休后学摄影，在贫困山区看到许多孩子失学，便把5万元家财全部捐出。2000年冬天大雪封山，他踩着一尺多深的雪、翻过海拔1330米的山峰走了25公里，把再次辍学的张斌兄妹接回学校，被授予“全国希望老人”称号。","page":830},{"title":"全市第一所市民学校","text":"1991年12月6日，关山街市民文明学校开学，这是武汉全市第一所市民文明学校。街党委书记当校长，请大学教师当教员，《文明市民读本》共9讲、20个学时，学完还要结业考试。此后各街各单位纷纷仿效，到1997年全区办起126所。","page":831},{"title":"农民搬进了公寓楼","text":"和平乡徐东村1993年投资1400万元建起8栋6层农民公寓，首批154户入住，1996年全村500多户全部搬进新居，后来又免费装上煤气、程控电话和闭路电视。村里还出资800万元扶持武汉交响乐团，组建农民管弦乐队，一时轰动。","page":817},{"title":"“十颗星”挂在门口","text":"1997年起洪山评选“十星级文明农户”，爱国、法纪、致富、计生、科技、文教、新风、勤俭、团结、卫生各一颗星。1998年大水时，左岭镇金王村卖黄沙的村民按“爱国星”要求自觉封港，3户人家为加宽堤身让出住房，全村评出200户星级农户并全部挂牌。","page":820},{"title":"菜场也能拿“新风杯”","text":"广埠屯菜场在“新风杯”竞赛中坚持预订登记、送菜上门，逢年过节给老红军、教师、孤寡老人送菜。后来又严把“放心肉”“放心菜”关，很多市民舍近求远来买菜，2000年各项经济指标都以10%的速度增长，多次获评文明窗口。","page":821}],"chapterNotes":{"1":"从文明村、双文明户、十星级农户到文明单位、文明小区、文明街道，看城乡创建活动层层铺开。","2":"文明礼貌月、市民文明学校、“十不”行为规范和移风易俗，讲公民素质教育的点点滴滴。","3":"驻军与村庄、学校、街道结对共建，从1000米文明路段延伸到7800米文明大道。"},"keywords":["文明礼貌月","十星级农户","双文明户","市民文明学校","江诗信","文明大道","移风易俗"],"chapters":[{"no":1,"title":"群众性文明创建活动","page":816,"zhuanji":false,"sections":["指导机构","文明村镇（乡）创建活动","“双文明户”","文明单位（行业）创建活动","文明城区创建活动"]},{"no":2,"title":"全民文明道德教育活动","page":828,"zhuanji":false,"sections":["公民素质教育","移风易俗"]},{"no":3,"title":"文明共建活动","page":831,"zhuanji":false,"sections":["军民共建","结对共建"]}]},{"id":"p29","no":29,"title":"社会生活","start":834,"end":909,"group":"minsheng","tagline":"过早、打豆丝，听洪山人“板眼”多","lead":"想认识洪山人，最好从一天的生活看起：早上出门叫“过早”，夸人能干说“有两刷子”，哥哥喊“拐子”，外婆叫“家家”，傻乎乎的人被笑作“苕”。这一篇把老百姓的日子摊开来讲——吃的有冬月打豆丝、腊月揣糍粑、渔船上用湖水煮活鱼；穿的有孩子头上绣着“长命百岁”的狗头帽；过节有三月三吃地菜煮鸡蛋、中秋添一碗仔鸡烧板栗。日子也在一点点变：农民人均年收入从1985年的662元涨到2000年的4230元，结婚“三大件”从“三转一响”换成了全自动洗衣机和数码相机。篇里还记下了近千个村湾名字的来历、宝通寺和莲溪寺的兴衰，以及洪山、伏虎山、石门峰上一座座陵园墓葬，让人在家长里短之外，看见这片土地厚重的历史。","numbers":[{"value":"4230","unit":"元","label":"2000年农村人均年收入，1985年仅662元","page":835},{"value":"34","unit":"个","label":"2000年区内少数民族数，共13638人","page":834},{"value":"近千","unit":"个","label":"境内农村自然村湾","page":834},{"value":"99","unit":"%","label":"20世纪90年代末全区火葬率","page":841}],"stories":[{"title":"庙里也有“大财主”","text":"宝通禅寺历史可追溯到南朝，宋代把随州大洪山的禅院迁来，东山从此改叫洪山。民国时寺产遍布嘉鱼、纸坊、豹澥等十多处，还在武昌开了4个店铺，和黎元洪等一起被称为当时武昌县“三大财主”。每逢清明，全寺60多名僧众列队出外“踩界”，巡视庙产。","page":860},{"title":"一座墓带出一个回民村","text":"明末清初，伊斯兰教经堂教育的奠基人之一马铨在洪山马家庄购置土地，一部分作回民墓地，一部分租给回民耕种。他去世后葬在这里，各地穆斯林纷纷前来朝拜，不少人就此落户，渐渐形成上、下马家庄两个回民村，2000年仍有180多人居住。","page":906},{"title":"二婆嘴变二府嘴","text":"村湾地名里藏着许多小故事。左岭镇的二府嘴，最初叫“二婆嘴”，因妯娌两人在此居住得名，后来才演化成今天的名字；和平乡的落步嘴，传说是神话里的二郎神下凡时在这里停过脚，当地还因此建过一座二郎庙。","page":902},{"title":"从“三转一响”到铂金","text":"60—70年代，年轻人结婚以自行车、缝纫机、手表、收音机“三转一响”为时尚；1983年调查，农家每百户才有1台电视机。到2000年，每百户农家有电视机117台、汽车2辆，农村婚嫁流行铂金首饰，这一项就要花5000—10000元。","page":838},{"title":"黄米粘，两头尖","text":"九峰、花山一带有顺口溜：“黄米粘，两头尖，一人吃，两人添。”说的是黄米粘的饭配油炸刁子鱼，香得一人吃要两人添。稻区农家用大锅煮饭，锅底锅巴加米汤熬成锅巴粥，“饭后一碗锅巴粥，又脆又香心中留”。","page":840}],"dialect":[{"word":"过早","meaning":"吃早饭"},{"word":"日头","meaning":"太阳"},{"word":"扯霍","meaning":"闪电"},{"word":"麻喷雨","meaning":"毛毛雨"},{"word":"罩子","meaning":"雾"},{"word":"天狗吃日头","meaning":"日食"},{"word":"水凼子","meaning":"水坑"},{"word":"门年","meaning":"明年"},{"word":"煞黑","meaning":"傍晚"},{"word":"苕","meaning":"甘薯；也指傻子"},{"word":"大胡椒","meaning":"辣椒"},{"word":"啰啰","meaning":"小猪"},{"word":"檐老鼠","meaning":"蝙蝠"},{"word":"亮火虫","meaning":"萤火虫"},{"word":"打屁虫","meaning":"椿象"},{"word":"喜头鱼","meaning":"鲫鱼"},{"word":"脚鱼","meaning":"鳖"},{"word":"灶屋","meaning":"厨房"},{"word":"炊子","meaning":"烧开水的水壶"},{"word":"男将、女将","meaning":"男人、女人"},{"word":"小把戏","meaning":"小孩子"},{"word":"半铫子","meaning":"二百五，做事不靠谱的人"},{"word":"寡汉条","meaning":"单身汉"},{"word":"三只手","meaning":"扒手"},{"word":"家家","meaning":"外祖母"},{"word":"拐子","meaning":"哥哥"},{"word":"堂客","meaning":"妻子"},{"word":"随娘伢","meaning":"随母改嫁带来的孩子（拖油瓶）"},{"word":"倒拐","meaning":"胳膊肘"},{"word":"克膝头","meaning":"膝盖"},{"word":"打摆子","meaning":"发疟疾"},{"word":"现饭","meaning":"剩饭"},{"word":"白喜事","meaning":"丧事"},{"word":"发梦天","meaning":"说梦话"},{"word":"吃鸡下巴","meaning":"插嘴"},{"word":"不服周","meaning":"不服气"},{"word":"笋子炒肉","meaning":"（用戒尺）打手心"},{"word":"躲猫","meaning":"捉迷藏"},{"word":"板眼","meaning":"名堂、花样"},{"word":"跑反","meaning":"逃难"}],"customs":[{"title":"冬打豆丝腊揣粑","text":"农历冬月，家家把大米和黄豆泡水磨浆、摊饼、切丝晒干做成豆丝；糯米煮熟后几个人轮流用木棒揣打成泥，压进木模做成糍粑。客人上门，一碗煮糍粑和豆丝再卧几个荷包蛋，又快又可口。","page":840},{"title":"湖水煮活鱼","text":"湖乡渔民最爱清水煮活鱼：刚打上来的鱼去鳃去内脏，用湖水洗净，就在船上架灶，舀湖水入锅现煮，汤鲜肉嫩。家常还有肉丸、藕丸、绿豆丸、鱼丸，各有蒸、炸、煮的吃法。","page":840},{"title":"娃娃戴狗头帽","text":"旧时农家男童冬天戴“狗头帽”，帽两侧缀着“狗耳朵”，绣上“长命百岁”“长命富贵”，盼孩子像小狗一样少病好养；也有虎头帽、狮头帽，用来“镇邪”。婴儿则戴顶上有圆孔的“月亮帽”。","page":840},{"title":"给牛王爷过生","text":"耕牛是农家宝。除夕夜点灯照牛栏、添好料；清明一早争着牵牛吃新草；端午用艾叶水给牛洗澡；六月初八“牛王爷”生日，牛歇一天，喂黄豆、糍粑，点香烛祝寿；七月七还要给牛换新鼻栓。","page":840},{"title":"杀年猪有头有尾","text":"腊月杀年猪，烫猪刨毛时头上尾上各留一撮毛，叫“有头有尾”。屠夫除了工钱还能得小肠和猪鬃，到腊月二十六“封刀”。鸡窝里放个空蛋壳当“引窝蛋”，诱母鸡多下蛋。","page":841},{"title":"发八字与报日","text":"旧式婚礼讲究门当户对、生辰八字。定亲时男方送“七包点心，八包茶”，女方把写着生辰的“庚书”交媒人，叫“发八字”；再选吉日写“龙签”“凤简”送女家，叫“报日”，然后花轿迎亲、拜堂，三朝回门才算礼成。","page":841},{"title":"拜年有讲究","text":"从腊月二十四“过小年”起送灶神、打扬尘，三十贴春联吃团年饭、守岁，长辈给压岁钱。初一凌晨放爆竹后拜年，老规矩是初一拜父族、初二拜母族、初三拜妻族、初四拜亲友。","page":842},{"title":"三月三与中秋","text":"农历三月三吃油炸春卷和地菜花煮鸡蛋，俗说能明目、防头晕；端午吃盐蛋、粽子，门挂艾蒿菖蒲；中秋这天家家饭桌上要多一碗“仔鸡烧板栗”，一家人边吃月饼边赏月。","page":840}],"sayings":["四月八，冻死鸭","萝卜上了街，药铺无买卖","三月三，九月九，无事莫打江边走","人大分家，树大分桠","天黄有雨，人黄有病","猪来穷，狗来富，猫子来了开当铺","吃饭大似皇帝","早起三光，晏起三慌","荒年饿不死手艺人","黄鹤楼上看翻船","糍粑屁股（久坐不走）","染坊失了火——架子还在","刷子掉了毛——尽是板眼","蟹子夹豌豆——连滚带爬","两个哑巴见面——冒得话说"],"tombs":[{"name":"施洋烈士陵园","text":"施洋是著名律师、二七大罢工领导人之一，1923年2月在洪山就义，年仅35岁。1953年墓由洪山南麓迁至山腰，建纪念碑和塑像，列为湖北省文物保护单位。","page":903},{"name":"独立团烈士陵园","text":"1926年秋叶挺独立团攻打武昌城，牺牲官兵191名（一说194名），次年合葬洪山南麓，碑上刻有阵亡官兵英名。1986年建纪念碑和牌坊，列为湖北省文物保护单位。","page":903},{"name":"石门峰烈士陵园","text":"1985年落成，建在石门峰主峰上，四周苍松翠柏，大门拱额上刻“烈士陵园”4个行书大字。园内有陈定一、陈柱天、柯良材等烈士墓，墓前大理石碑记有烈士生平。","page":903},{"name":"石门峰都市陵园","text":"位于东湖之滨，原是荒山，1953年定为公墓山，总面积1109.98亩，已有120多万人安葬于此。1952年马家庄800余座回民墓迁来，另辟回民墓区；1994年起改造为都市陵园。","page":904},{"name":"石门峰名人文化公园","text":"位于石门峰都市陵园北面，占地约600亩，1995年规划、2002年5月完成一期工程。荆楚名人纪念长廊刻录了各行各业的荆楚名人2000位，集人文纪念与旅游观光于一体。","page":904},{"name":"蛮王冢","text":"位于南望山脚下，与东汉时迁到江夏的“江夏蛮”有关。原为并列3冢，西冢解放初被挖，中冢“文革”中被挖开，为东汉墓葬形制，现仅存东边一冢，1981年列为市级文物保护单位。","page":905},{"name":"李邕墓","text":"唐代书法家李邕曾任北海太守，人称“李北海”，书法初学王羲之，主张“学我者死”，反对一味模仿。因祖籍江夏葬于九峰山，明代楚王建九峰寺时迁墓，具体地点今已不明。","page":905},{"name":"马铨墓","text":"又称马斯巴巴墓，在伏虎山马庄村，圆顶拱包状，极具伊斯兰特色，为马铨夫妇同穴墓，室壁嵌有清康熙年间汉文碑和回文碑。马铨是中国伊斯兰经堂教育奠基人之一，墓为市级文物保护单位。","page":905},{"name":"九女墩","text":"在东湖西北岸，是1856年清军攻破武昌、太平军突围时牺牲于湖边的9名女战士之墓。乡人为避清廷追究，称“墩”不称“坟”。解放后培修陵墓、立纪念碑，列为湖北省文物保护单位。","page":906},{"name":"庚子革命烈士墓","text":"位于洪山北麓，安葬1900年自立军起事失败牺牲的唐才常、傅慈祥等7位烈士。1912年孙中山到武汉时决定建园，立“铁血精神庚子之墓”碑，后扩建并建纪念堂，现为省级文物保护单位。","page":906},{"name":"刘静庵墓","text":"在伏虎山西北麓，椭圆土顶，墓碑高2.7米。刘静庵是湖北潜江人，曾任武昌日知会总干事，日知会后成为同盟会在湖北的据点；他1906年被捕，1911年病逝狱中。","page":907},{"name":"刘公墓","text":"在伏虎山西北麓，形制与刘静庵墓相近，苍松环绕。刘公是湖北襄阳人，留日时加入同盟会，出资资助革命，参加辛亥武昌起义，后任军政府总监察，1920年病逝上海。","page":907},{"name":"蓝天蔚墓","text":"在伏虎山西北麓，墓碑刻“蓝天蔚先生之墓”，墓周有9米见方护院。蓝天蔚是黄陂人，早年留学日本，民国初任关外大都督，后组织讨袁，1921年兵败入川时被俘身亡。","page":907},{"name":"陈定一墓","text":"1926年立于洪山山麓，1985年移至九峰石门峰烈士陵园，碑高2.5米，背刻墓志。陈定一是汉阳人，投身工人运动、宣传支援北伐，1926年8月被捕，就义于武昌大巷口。","page":907},{"name":"李汉俊墓","text":"在伏虎山西坡、卓刀泉古寺后面，宝塔形墓碑高2.6米，四周翠柏环绕。李汉俊是湖北潜江人，中国早期马克思主义启蒙者之一，1927年遇害，1952年被追认为革命烈士。","page":907},{"name":"黎元洪墓","text":"在卓刀泉后的土公山上，圆包状，周长15米，墓前石碑刻“大总统黎元洪墓”，墓道两旁松柏成荫。黎元洪辛亥时出任湖北都督，后出任大总统，1928年病逝天津，墓为市级文物保护单位。","page":908},{"name":"郝梦龄墓","text":"在卓刀泉伏虎山西北侧山腰，门前33级台阶，塔形碑刻“郝梦龄烈士之墓”。郝梦龄是河北人，1937年率第九军北上抗日，在忻口战役中殉国，后以国葬仪式安葬于此。","page":908},{"name":"孙武墓","text":"在伏虎山辛亥首义烈士公墓，与吴兆麟墓并肩，墓地护以矩形墙，间植青松红枫。孙武是汉阳柏泉人，武昌起义时任参谋长，后任湖北军政府军务部长，1939年卒于北京，墓为省级文物保护单位。","page":909},{"name":"吴兆麟墓","text":"在伏虎山北麓，占地约90平方米，苍松环绕。吴兆麟是湖北葛店人，辛亥首义时任起义军临时总指挥，率军攻克武昌全城；民国后解甲从事社会公益，倡修武昌首义公园，1942年病逝。","page":909},{"name":"熊秉坤墓","text":"在九峰山烈士公墓内，原为无碑土堆，1981年整修，立“熊秉坤之墓”石碑。熊秉坤早年当过码头搬运工，辛亥首义时组织敢死队攻入督署东辕门，后迁居青菱乡，1969年去世。","page":909}],"chapterNotes":{"1":"从“吃上餐愁下餐”到百户农家117台电视，看收入和衣食住行的半世纪变迁。","2":"饮食服饰、农事饲养、婚丧礼俗、四时节令，还有数百条洪山方言和俗语。","3":"34个少数民族在洪山的分布，回民马家庄与各民族的饮食、婚丧、禁忌。","4":"宝通禅寺、莲溪寺等佛教丛林的千年兴衰，以及伊斯兰教的传入和清真寺。","5":"近千个村湾地名的来历：以姓氏、地形、传说命名，藏着浓郁的乡土气息。","6":"施洋、独立团等烈士陵园与蛮王冢、九女墩、黎元洪墓等名人墓葬。"},"keywords":["方言","过早","豆丝糍粑","节令习俗","村湾地名","宝通禅寺","九女墩","石门峰"],"chapters":[{"no":1,"title":"人民生活","page":834,"zhuanji":false,"sections":["收入状况","消费水平"]},{"no":2,"title":"民俗","page":839,"zhuanji":false,"sections":["生活习俗","生产习俗","礼仪习俗","节令习俗","方言"]},{"no":3,"title":"少数民族","page":857,"zhuanji":false,"sections":["第一节","风俗习惯"]},{"no":4,"title":"宗教","page":859,"zhuanji":false,"sections":["佛教","伊斯兰教"]},{"no":5,"title":"村湾地名","page":863,"zhuanji":false,"sections":["洪山乡村湾地名","和平乡村湾地名","建设乡村湾地名","青菱乡村湾地名","九峰乡村湾地名","花山镇村湾地名","左岭镇村湾地名"]},{"no":6,"title":"陵园 墓葬","page":903,"zhuanji":false,"sections":["烈士陵园","名人墓葬"]}]},{"id":"renwu","no":null,"title":"人物","start":910,"end":942,"group":null,"tagline":"伶界大王、首义先锋与百位名师","lead":"《洪山区志·人物》遵循“生不立传”的原则，为已故的重要人物立传。这里有“伶界大王”谭鑫培，有率工程营首义的熊秉坤；有华中师大、华中农大、华中工学院、武汉测绘学院的创校元勋，也有选育锦橙、华椒、华棉101的农学家；还有带头办合作社的农民、守护乡亲的乡村医生，以及为救人、追凶而牺牲的知青、大学生、民警和联防队员。附上的英烈名录，记下了从大革命到1998年抗洪中为国捐躯的名字。","stats":[{"value":"75","unit":"人","label":"原书人物传略收录"},{"value":"45","unit":"人","label":"英烈名录收录"},{"value":"27","unit":"位","label":"2000年洪山地区两院院士（科学院15、工程院12）"},{"value":"225","unit":"人","label":"人物表收录的院士、学者与劳模"}],"people":[{"name":"谭鑫培","years":"1847—1917","origin":"江夏宾阳门（今武昌大东门）外谭家湾","tag":"京剧“伶界大王”","text":"艺名“小叫天”，博采程长庚、余三胜等名家之长，以“云遮月”嗓音创出“谭派”唱腔，被誉为“伶界大王”。1905年主演的《定军山》被拍成电影，是中国最早的戏曲片。谭门绵延七代，成为梨园罕见的世家。","page":910,"field":"文化艺术"},{"name":"黄嘉今","years":"1903—1930","origin":"和平乡武丰村","tag":"革命烈士","text":"在共进中学读书时受董必武教诲，1927年加入中国共产党，以“黄鹄”小书店为掩护组织进步学生读书会。1930年再次被捕，受尽酷刑也不吐露组织秘密，在武昌阅马场英勇就义，年仅27岁。","page":910,"field":"革命"},{"name":"万葆元","years":"1884—1948","origin":"青菱乡建阳村","tag":"同盟会员","text":"1906年留学日本攻读土木建筑，在东京加入同盟会；辛亥后回国，曾当选国会议员。因不满袁世凯迫害革命党人而辞官。晚年集资修建花园小学，规模在当时武昌县屈指可数。","page":910,"field":"军政"},{"name":"鲁方才","years":"1876—1948","origin":"建设乡星火村鲁家大湾","tag":"营造业商人","text":"渔家子弟，12岁学木工，后在汉口开办汉兴昌营造厂。1917年参与集股建造汉口新市场（今民众乐园）并承建工程。1921年借银修筑武惠堤，东起白浒山脚，西至青山武丰闸。","page":910,"field":"工商"},{"name":"徐荣廷","years":"1857—1949","origin":"青菱乡长江村","tag":"纺织实业家","text":"学徒出身，辛亥首义后任湖北官钱局总办，组建楚兴公司承租纱、布、丝、麻四局。后创办石家庄大兴纱厂、武昌裕华纱厂，逐步发展为裕大华集团；还曾向工商界募捐白银10余万两支持辛亥革命。","page":910,"field":"工商"},{"name":"王自申","years":"1898—1954","origin":"湖南湘潭","tag":"华中师院奠基人","text":"1932年加入中国共产党，抗战时任徐特立秘书，经手输送五六百名青年奔赴延安。后参与创办北方大学、中原大学，1953年华中师范学院成立时主持院务，师生赞他“创学育才，一代师表”。","page":911,"field":"学术"},{"name":"钱基博","years":"1886—1957","origin":"江苏无锡","tag":"国学大师","text":"16岁就发表4万字的《中国舆地大势论》崭露头角，著有《中国文学史》《现代中国文学史》等。1952年起任华中师范学院中文系教授，将5万册藏书和200多件历代文物捐给学校。","page":911,"field":"学术"},{"name":"张植安","years":"1888—1961","origin":"九峰乡新跃村","tag":"乡村教育家","text":"北京大学英文系毕业，曾任南洋《三宝垄日报》总编。1934年兼任青山区区长，把办学与乡政、筑堤、造林结合，发动民众修筑武惠堤。1949年他自带行装住到堤上，防止武惠堤遭到破坏。","page":913,"field":"学术"},{"name":"金通尹","years":"1891—1964","origin":"浙江平湖","tag":"武汉测绘学院创办者","text":"在复旦大学创办土木工程学系，曾任理学院院长。1955年到武汉筹建武汉测绘学院，任副院长、一级教授，昼夜操劳，还把自藏的二十四史连同书柜捐赠学院。曾任全国政协第一至四届委员。","page":913,"field":"学术"},{"name":"严家马","years":"1933—1965","origin":"左岭镇朝阳村","tag":"舍己救人英雄","text":"1965年7月20日带领10名社员到南塘湖捞草，返程时八级大风掀翻船只。他先让大家抓住救生物，再把被浪冲散的4人一个个抱上船，自己却筋疲力尽溺水身亡，被追认为中共正式党员。","page":913,"field":"其他"},{"name":"叶雪安","years":"1905—1966","origin":"江苏金山","tag":"大地测量学家","text":"留学德国学习测量，主持完成上海、天津两城市大三角测量，奠定中国城市测量基础。1955年参与创建武汉测绘制图学校，任一级教授。女儿后用他生前存款设立“叶雪安大地测量奖学金”。","page":913,"field":"学术"},{"name":"崔燕华","years":"1945—1965","origin":"河南新蔡（1957年迁居洪山区）","tag":"舍己救人知青","text":"1964年初中毕业后下乡插队，担任大队团支部书记，还帮生产队办夜校、教失学青少年识字。1965年7月3日为抢救落水的女社员跳入水库，献出了年轻的生命，被追认为中共党员。","page":914,"field":"其他"},{"name":"闵乃扬","years":"1916—1967","origin":"江苏如皋","tag":"棉花专家","text":"与棉花专家俞启葆合作育成泾斯棉，在陕西大面积增产。后主持中南和湖北的棉花品种区域试验，评选出的岱字15号在华中地区普遍推广；1962年还赴印度尼西亚传授植棉技术。","page":914,"field":"学术"},{"name":"曾省","years":"1899—1968","origin":"浙江瑞安","tag":"植物保护学家","text":"留学法国、瑞士获博士学位，筹建中南农科所。曾率队战胜小麦吸浆虫，使河南3000万亩小麦免受灾害；又从浙江移植大红瓢虫防治柑橘害虫获成功，是湖北植保科研的奠基人之一。","page":914,"field":"学术"},{"name":"吴宗鹏","years":"1909—1969","origin":"左岭镇上街村","tag":"长征老红军","text":"雇农出身，半岁丧父，6岁给地主放牛。1933年参加红军，1935年参加二万五千里长征。新中国成立后长期在铁道系统任职，历任铁路工程局局长等。“文革”中被迫害致死，1986年彻底平反。","page":915,"field":"革命"},{"name":"熊秉坤","years":"1885—1969","origin":"青菱乡石嘴","tag":"武昌首义元勋","text":"码头搬运工出身，入湖北新军后加入共进会，任工程营革命军大队长。1911年10月10日工程营率先发难，他首先率部占领楚望台军械库，又组织敢死队攻破督署东辕门。逝世后葬于九峰山。","page":915,"field":"革命"},{"name":"王凌云","years":"1913—1970","origin":"湖北公安","tag":"文史学者","text":"黄侃门下弟子，专研《左传》礼制与中国礼制史，撰写《辛亥武昌首义先烈传》等。1952年起任华中师范学院教授，应中华书局之约撰写《史通注》约30万字，留下100多万字手稿。","page":916,"field":"学术"},{"name":"潘梓年","years":"1893—1972","origin":"江苏宜兴","tag":"《新华日报》社长","text":"1927年入党，1933年被捕入狱。出狱后奔走筹办《新华日报》，1938年1月在武汉创刊并任社长。后任中原大学校长，1952年任华中师范学院院长，1954年调任中国科学院哲学社会科学部副主任。","page":916,"field":"革命"},{"name":"刘惠芳","years":"1910—1972","origin":"湖北孝感","tag":"盲童教育家","text":"1942年出任武昌瞽目女校首任中国籍校长，带领师生8次搬迁保住学校。1950年从美国提前回国，带回盲文打字机等器材。她不许任何人喊学生“瞎子”，学校1958年被评为全国卫生红旗单位。","page":916,"field":"学术"},{"name":"周焕章","years":"1897—1973","origin":"湖北黄陂","tag":"武汉工学院首任院长","text":"五四运动“火烧赵家楼”时曾被捕。留美获化学硕士，1945年与胡厥文、马寅初等发起成立中国民主建国会。任武汉市公用事业管理局局长时建议筹建电车公司，1958年出任武汉工学院首任院长。","page":917,"field":"学术"},{"name":"曾运英","years":"1929—1974","origin":"和平乡","tag":"女劳动模范","text":"贫苦农家出身，16岁当雇工。任任家路大队干部时组织修建排灌渠和抽水站，引种上海白菜“四月慢”，次年4月上市蔬菜31万公斤，缓解了武汉春季缺菜。后任中共洪山区委常委。","page":917,"field":"其他"},{"name":"许宗岳","years":"1881—1974","origin":"江夏","tag":"电波传播专家","text":"留美获布朗大学博士，在美国发明的高频加热仪器获得专利。回国后任武汉大学、华中工学院教授，是中国最早从事电离层、水声、超声研究的专家之一，参与建立武汉大学游离层实验室。","page":917,"field":"学术"},{"name":"夏良才","years":"1911—1975","origin":"四川仁寿","tag":"颌面外科专家","text":"在成都创办中国第一个颌面外科病房，主持编纂中国第一部《口腔颌面外科学》。1960年来湖北医学院筹建口腔系，1962年因陋就简建成中南地区第一个口腔医院门诊部。","page":917,"field":"学术"},{"name":"查谦","years":"1896—1975","origin":"安徽泾县","tag":"华中工学院首任院长","text":"美国明尼苏达大学物理学博士，在武汉大学任物理系主任、理学院院长，学生说听他讲课是“享受”。1953年主持筹建华中工学院，仅年余建成十几万平方米校舍，1955年任院长。","page":917,"field":"学术"},{"name":"韦卓民","years":"1888—1976","origin":"广东香山（今中山市）","tag":"华中大学校长","text":"伦敦大学哲学博士，长期任华中大学校长，尤精康德哲学。武汉解放前夕坚拒南迁，护校保产迎接解放；1951年华中大学改为公立后继任校长。著有《孔门伦理》《康德哲学讲解》等10多种。","page":918,"field":"学术"},{"name":"夏坚白","years":"1903—1977","origin":"江苏常熟","tag":"测绘学家","text":"留学英德获工学博士，1956年任武汉测绘学院院长。学院1970年被撤销后，他大声疾呼并写信给周恩来总理建议恢复，1973年学院重建。曾任中国科学院地学部委员。","page":918,"field":"学术"},{"name":"朱希亮","years":"1900—1977","origin":"江西临川","tag":"心理学家","text":"格式塔心理学派创始人考夫卡的门生，曾与苏联心理学家巴甫洛夫共同研讨心理学问题。1952年起任华中师范学院心理学教授，是中国心理学会创始人之一，讲课深入浅出深受欢迎。","page":919,"field":"学术"},{"name":"万流一","years":"1907—1978","origin":"汉阳奓山镇万家嘴","tag":"“东湖开拓者”","text":"1951年起任东湖风景区管理处处长，主持修建行吟阁、屈原纪念馆、九女墩纪念碑和朱碑亭，倡导“沿湖插柳、有坡皆松”，还主持兴建关山公园等。去世后葬于九峰山。","page":919,"field":"军政"},{"name":"高庆赐","years":"1910—1978","origin":"河北遵化","tag":"语言学家","text":"华中师范学院教务长兼中文系教授，擅长现代汉语研究。与邢福义合著的《现代汉语语法知识》被译成日文出版；主持编写的《现代汉语词汇知识》多次再版，印数达70余万册。","page":920,"field":"学术"},{"name":"詹剑峰","years":"1902—1978","origin":"安徽婺源（今属江西）","tag":"哲学家、逻辑学家","text":"曾赴法国勤工俭学，1952年后一直任华中师范学院政治系教授，讲授过17门课程。代表作《墨家的形式逻辑》独创墨家形式逻辑体系学说，行销多个国家和地区。","page":920,"field":"学术"},{"name":"杨东莼","years":"1900—1979","origin":"湖南","tag":"华中师院首任院长","text":"北大读书时与邓中夏等发起马克思学说研究会，后翻译《古代社会》等著作，参与发起救国会。1953年任华中师范学院首任院长，后任民进中央副主席、国务院副秘书长。","page":920,"field":"学术"},{"name":"范宗先","years":"1913—1979","origin":"河北定兴","tag":"体育教育家","text":"1953年任中南体育学院筹备委员，后任武汉体育学院教务长兼体育系主任。曾获湖北省首届运动会男子铁饼冠军，1956年出席全国先进生产者代表大会，著有《体育理论》《篮球》等教材。","page":921,"field":"学术"},{"name":"邱永喜","years":"1918—1980","origin":"祖籍南京，生于湖北大冶","tag":"固体物理学家","text":"在剑桥师从诺贝尔奖得主布拉格，1949年谢绝挽留回国。任华中师范学院物理系主任，1960年指导中南地区半导体大会战，研制隧道二极管半年完成，达到当时国际先进水平。","page":921,"field":"学术"},{"name":"陈鹤峰","years":"1904—1981","origin":"浙江鄞县","tag":"麒派京剧名家","text":"周信芳（麒麟童）的弟子，曾临时替师父演闻太师，声容酷似而一举成名。1950年任中南京剧工作团副团长，赴朝慰问志愿军，1954年防汛时率队上工地演出荣立三等功，后任湖北省戏曲学校校长。","page":921,"field":"文化艺术"},{"name":"黄溥","years":"1896—1982","origin":"湖南宁乡","tag":"教育家","text":"留美获哥伦比亚大学博士，1932年起任华中大学教育学院院长、副校长，多次代理校长。武汉解放前夕有人劝他去台湾任“教育部部长”，他坚决留在大陆，说“虽高官厚禄，不攀附”。","page":922,"field":"学术"},{"name":"姚康","years":"1913—1983","origin":"安徽桐城","tag":"昆虫学家","text":"华中农学院教授，1953年撰写的《增订中国仓库害虫及益虫初步名录》是中国最早的综合性仓虫名录。1980年从美国引进天敌黄色花蝽繁殖成功，病重住院时仍坚持撰写《仓库害虫及益虫》。","page":922,"field":"学术"},{"name":"杨惠安","years":"1906—1983","origin":"湖北天门","tag":"蔬菜学家","text":"华中农学院园艺系主任。1956年在武汉试种大白菜成功，亩产8000多公斤；推广温床、冷床育苗，使郊区番茄、辣椒等提早15—20天上市；1976年育成早熟辣椒“华椒1号”“华椒2号”。","page":922,"field":"学术"},{"name":"赵师梅","years":"1894—1984","origin":"湖北巴东","tag":"辛亥志士、电机学家","text":"辛亥前受命与人仿制十八星旗20面，首义当天赶往南湖通知炮队配合进攻督署。后由孙中山派赴美国留学，1930年任武汉大学电机系主任。临终将1万元积蓄捐给武汉工学院设立奖学金。","page":923,"field":"革命"},{"name":"胡雪","years":"1909—1985","origin":"湖北黄冈","tag":"文学家、翻译家","text":"早年考入黄埔军校，抗战时在军委会政治部第三厅与周恩来、郭沫若等组成对日宣传核心小组。建国后任华中师范学院中文系主任、图书馆馆长，通晓5国语言，译有《夏目漱石选集》等。","page":923,"field":"学术"},{"name":"杜合清","years":"1903—1985","origin":"洪山乡东湖村","tag":"农业劳动模范","text":"佃农出身。1952年把互助组扩大为武汉市郊区第一个初级农业生产合作社——灯塔农业生产合作社，当年被评为市农业劳模，赴京参加国庆观礼。1954年大水中带领社员日夜奋战江堤。","page":924,"field":"其他"},{"name":"胡仲紫","years":"1909—1986","origin":"湖南攸县","tag":"水稻专家","text":"1933年把改良稻种“帽子头”十余万斤运往衡阳灾区，是国内水稻首次大规模推广良种的创举。在华中农学院任教授，育成“胜利籼”“茶粘一号”等6个良种，累计推广7千万亩。","page":924,"field":"学术"},{"name":"李光裕","years":"1932—1986","origin":"武汉市郊区汉桥乡","tag":"农村改革带头人","text":"1975年当选全国人大代表，后任洪山区委副书记。1980年农村改革起步时顶住阻力，以星火9队为试点把土地承包到户，获市区肯定并推广；还鼓励妻子带头养猪，带动磨山大队养猪专业户发展。","page":924,"field":"军政"},{"name":"高原","years":"1920—1986","origin":"辽宁义县","tag":"科学社会主义学者","text":"1944年投身革命，后任华中师范学院副院长、党委书记。1978年倡导筹建科学社会主义研究所；主编的高校文科教材《科学社会主义》成为国内权威著作，屡次再版，并有少数民族文字译本。","page":924,"field":"学术"},{"name":"闻汝贤","years":"1909—1986","origin":"左岭镇金王村闻家湾","tag":"报人、词学家","text":"留学日本攻读新闻，曾任新加坡商务参赞、合肥市市长、上海《真实晚报》社长。1950年赴台湾，任多所大学教授，著有《词牌汇释》《新闻概论》等，1986年在台北去世。","page":925,"field":"文化艺术"},{"name":"闵瑞亭","years":"1909—1987","origin":"洪山乡","tag":"乡村名医","text":"出身世代行医之家，擅治各类外科疾病，武昌、黄陂、孝感、新洲等地患者慕名而来。他常为贫困病人免收诊费、补贴药品，大医院高薪聘请都被谢绝，退休后仍为乡亲治病。","page":925,"field":"其他"},{"name":"黄振","years":"1920—1987","origin":"湖北黄陂","tag":"戏曲教育家、剧作家","text":"1938年参加革命文艺工作，后任湖北地方歌剧团团长、湖北省戏曲学校校长兼党委书记。创作《赶会》《三拜堂》等戏曲，领导改编的楚剧《双教子》获奖并拍成戏曲电影。","page":925,"field":"文化艺术"},{"name":"陶军","years":"1917—1987","origin":"安徽贵池","tag":"华中师院创办人之一","text":"燕京大学学生，1941年奔赴晋察冀根据地，后任《晋察冀日报》编辑。1949年参与接收华中大学、创建华中师范学院，1981—1983年任我国驻联合国教科文组织副代表。","page":925,"field":"学术"},{"name":"郭抵","years":"1909—1987","origin":"陕西安康","tag":"教育家","text":"1937年被特务逮捕，经营救脱险后奔赴延安。参与创建中原大学，1952年起在华中师范学院任党委副书记、副院长；“文革”后是湖北省教育学会恢复活动后的第一任会长。","page":925,"field":"学术"},{"name":"许子威","years":"1908—1989","origin":"湖北应城","tag":"华中农学院院长","text":"1927年加入中国共产党，参加广州暴动。抗战时任豫鄂边区行政公署主席，建国后任荆江分洪工程副总指挥、湖北省政协副主席、华中农学院院长等职。","page":926,"field":"革命"},{"name":"傅碧人","years":"1907—1989","origin":"湖南涟源","tag":"起义将领","text":"黄埔六期生，参加淞沪、中条山等战役，3次负伤3次重返前线。1949年12月24日率9000余人起义。后任洪山区人民政府副区长、区人大常委会副主任，湖北省黄埔同学会副会长。","page":926,"field":"军政"},{"name":"章锡昌","years":"1910—1990","origin":"江苏武进","tag":"小麦育种专家","text":"留美获明尼苏达大学博士。育成的“南大2419”小麦在长江、淮河流域广泛种植，成为当时全国推广面积最大的小麦品种；推广的棉麦宽窄行、宽幅条播法在湖北长期沿用。","page":927,"field":"学术"},{"name":"卞彭","years":"1901—1990","origin":"江苏仪征","tag":"物理学家","text":"麻省理工学院科学博士，曾任华中大学理学院院长和代校长、华中师范学院教务长。1958—1964年任中国电子学会副理事长，晚年仍主编《中国电子科学学刊》。","page":927,"field":"学术"},{"name":"孔繁玉","years":"1919—1990","origin":"河南西平","tag":"花鸟画家","text":"杭州国立艺专毕业，专攻国画花鸟。1942年在重庆办个人画展，郭沫若等为之题词。曾任洪山区文化馆副馆长，65岁入党；患喉癌后仍举办两次画展，1990年在作画时逝世。","page":927,"field":"文化艺术"},{"name":"吴泽霖","years":"1898—1990","origin":"江苏常熟","tag":"民族学家","text":"留美获博士，我国社会学、人类学、民族学的先驱之一。1982年志愿调到中南民族学院，主持创办我国第一个民族学博物馆，又主持编译我国第一部《人类学词典》。","page":927,"field":"学术"},{"name":"王小波","years":"1969—1990","origin":"山东齐河","tag":"人民警察烈士","text":"洪山公安分局巡逻中队民警。1990年12月20日晚巡逻时在珞狮北路发现5名劫车杀人犯，临危不惧与歹徒搏斗，不幸牺牲，被湖北省人民政府批准为革命烈士。","page":927,"field":"其他"},{"name":"章恢志","years":"1911—1991","origin":"浙江温州","tag":"枇杷专家","text":"华中农业大学果树学教授，首次发现枇杷属新分类群“大渡河枇杷”，提出枇杷起源于中国的观点；选育“华宝”系列枇杷良种，出版论著24部。","page":928,"field":"学术"},{"name":"刘介愚","years":"1909—1991","origin":"重庆","tag":"华中师院院长","text":"1937年奔赴延安，在冀东打游击时入党。1954年起主持华中师范学院党政工作，后任武汉大学代校长。八旬高龄时把节衣缩食攒下的1万元以“新梅”名义捐给华中师大作奖学金。","page":928,"field":"学术"},{"name":"张舜徽","years":"1911—1992","origin":"湖南沅江","tag":"历史文献学家","text":"幼年在家乡自学文史，1951年起在华中师大执教。1981年成为全国第一位历史文献学博士生导师，出版著作24种31册，包括《说文解字约注》《中国文献学》《中华人民通史》等。","page":928,"field":"学术"},{"name":"刘若曾","years":"1912—1992","origin":"湖北鄂城","tag":"教育家","text":"少年时受陈潭秋等影响，1938年经董必武介绍赴陕甘宁边区，同年入党，在延安从事教育。新中国成立后任陕西省教育局局长、华中师范学院院长、湖北省教育学会会长。","page":928,"field":"学术"},{"name":"张景龄","years":"1927—1993","origin":"湖北武昌","tag":"有机磷化学家","text":"留苏攻读有机磷化学，在华中师范大学领导研制“水胺硫磷”等8个农药新品种，其中两种成为取代六六六的大吨位品种。1989年被国务院授予“全国先进工作者”称号。","page":929,"field":"学术"},{"name":"宋争","years":"1975—1994","origin":"洪山","tag":"联防队员烈士","text":"红旗街派出所治安联防队员。1994年7月22日夜巡逻时发现被劫出租车，追捕杀人犯时被自制火枪击中腹部，仍顽强搏斗，终因失血过多牺牲，后被追认为烈士。","page":929,"field":"其他"},{"name":"朱伯石","years":"1919—1995","origin":"江西泰和","tag":"写作学家","text":"1956年起在华中师范学院中文系任教，组建写作教研室，是我国写作学科的创建人之一。主编的《写作概论》多次再版，发行量近百万册，被国内许多高校选作教材。","page":930,"field":"学术"},{"name":"江望梅","years":"1945—1996","origin":"湖北汉川","tag":"物价战线标兵","text":"从花山镇供销社统计员做起，后任洪山区物价局副局长、党组书记，几十年屡获先进，被誉为“物价战线的一面光荣旗帜”。去世后区委组织部号召全区向她学习。","page":930,"field":"其他"},{"name":"白瑞西","years":"1916—1998","origin":"山西太谷","tag":"中南民族学院院长","text":"1937年投笔从戎参加抗日游击队。1958年由周恩来总理任命为中南民族学院院长；1980年学院恢复重建，他带病主持，1981年9月招生开学，为学院发展奠定基础。","page":930,"field":"学术"},{"name":"纪兢心","years":"1921—1998","origin":"湖北大冶","tag":"中西医结合名医","text":"十岁学医，20岁左右已是乡里名医，后又学西医，分配到洪山区工作。用中西医结合治好许多疑难杂病，被患者称为“神医”“神针”，著有《人体病症特征》。","page":931,"field":"其他"},{"name":"章文才","years":"1904—1998","origin":"浙江杭州","tag":"柑橘专家","text":"中国现代果树科学奠基人之一。1939年选出的鹅蛋柑26号、20号，后被命名为锦橙、先锋橙，成为我国甜橙主栽品种；举办技术培训600多次，受训学员和听众达80余万人次。","page":931,"field":"学术"},{"name":"孙济中","years":"1926—1998","origin":"安徽怀远","tag":"棉花育种专家","text":"留苏获博士学位，育成华棉4号等品种；80年代培育出我国第一个常规棉花抗虫新品种“华棉101”。1984年至1995年任华中农学院院长、华中农业大学校长。","page":931,"field":"学术"},{"name":"肖栋栋","years":"1972—1999","origin":"湖北巴东（土家族）","tag":"舍己救人研究生","text":"武汉汽车工业大学研究生。1999年2月28日在长江边发现一名轻生女子走向江中，不顾同学劝阻跳入寒冷江水施救，不幸牺牲，被追认为中共党员和革命烈士。","page":931,"field":"其他"},{"name":"谢岳峰","years":"1929—1999","origin":"湖南湘潭","tag":"水稻育种专家","text":"选育华矮4号、华矮8号等6个水稻品种，累计种植8000多万亩。在国际上首次证实成株期抗病基因的显性反转现象，1992年受聘筹建作物遗传改良国家重点实验室。","page":932,"field":"学术"},{"name":"晏炎吾","years":"1925—2000","origin":"湖北随州","tag":"文字学家、诗人","text":"受业于钱基博门下，1983年被正式任命为《汉语大字典》副主编。晚年任湖北省文史研究馆馆长，擅长旧体诗词和楹联，《蕉窗集》收其诗词244首、楹联166副。","page":932,"field":"文化艺术"},{"name":"李茂顺","years":"1922—2000","origin":"青菱乡长江村","tag":"全国劳动模范","text":"1954年防汛中多次跳进几米深的水里堵漏，带队员手挽手组成防浪人墙。后任青菱公社社长，1958年出席全国群英会受到毛泽东等接见，1962年当选第三届全国人大代表。","page":932,"field":"其他"}],"heroes":["明维周","刘子良","潘阳明","叶炳松","何济功","黄全德","陶德洪","邓少清","戚世康","王体炳","冯香庭","孙青山","胡幼林","张粟周","张友义","陈方金","郑德坤","叶顺昌","叶方根","李邦则","黄启荣","袁家清","蔡清","徐中繁","李金洪","肖振和","李元忠","舒秀峰","田吉超","容乃盛","古炼友","舒小信","胡梅生","熊厚轩","韩昌胜","向家友","王云","李信岩","闻新波","吴用智","梁力","廖国栋","丁云丰","惠伟为"],"chapters":[]},{"id":"fulu","no":null,"title":"附录","start":943,"end":973,"group":null,"legends":[{"title":"卓刀泉与伏虎山","text":"相传三国时期，关羽率一支队伍路过今武昌偏东南时，正遇三伏酷暑，将士们热得迈不动步，干渴难忍。关羽令部下在一座山脚下休息，赶忙打发人去找水应急。过一会，找水的人都无精打采地空手而归。关羽又令随从找来一个年老的乡民询问当地情况。老人说：“这里过去山清水秀，后来跑来个老虎精，一切都变样了，逢年过节老百姓还要献上一对童男玉女。”\n正说着，一只吊睛白额猛虎正张牙舞爪向关羽扑来。关羽大喝一声，随手将青龙偃月刀一挥，大刀瞬间化作青龙，呼啸着冲向猛虎。一时间，龙虎相斗，飞沙走石，天昏地暗。不到半个时辰，猛虎惨叫一声，趴在地上不能动弹，转眼间变成一座光秃秃的石头山。青龙降服了猛虎，又变成大刀飞回关羽手中。关羽以刀卓地，仰天大笑。突然，卓刀之处涌出一股清泉。关羽又将大刀在泉水里蘸了一下，挥刀向石山一洒，石山一下子青松林立。\n后来，人们把石头山叫伏虎山。又在山前建成一座青瓦白墙的庙宇，将泉水涌出的地方用三层条石砌成小井，名为卓刀泉。久之，卓刀泉又变成这一带的地名。","page":970},{"title":"洪山菜薹传说","text":"相传1700多年前，洪山脚下的小村里有个叫玉叶的姑娘，年方十八，相貌娟秀，心灵手巧。邻村有个叫田勇的小伙子，勤劳朴实，热心助人。两人互相倾慕，早已相爱。\n阳春三月，他们到风景秀丽的洪山游玩，被人称“恶太岁”的杨熊撞见。杨熊见玉叶十分漂亮，令兵勇将她抢走。田勇奋力拼打，将玉叶救出，拉着她就往山下跑。杨熊见漂亮姑娘得而复失，叫兵勇将两人乱箭射死。顿时，田勇和玉叶的鲜血染红了脚下的土地。杨熊见出了人命，策马逃跑，突然一阵雷电，将杨熊一伙全炸死在山腰。\n事后，当地百姓将田勇和玉叶埋在死难的地方。到来年秋天，坟堆周围长满了紫红色的小苗苗，乡亲们常给它们浇水施肥。到了秋天，当地遇上大虫灾，庄稼颗粒无收，乡亲们将坟堆周围的紫红菜的薹秆采来食用，觉得甜脆清香，且越采越多，渡过了荒年。秋后，家家户户采集菜籽，在自家菜园里种植，且时常挑菜薹到城里去卖。城里人吃到这种稀有的菜，赞不绝口，红菜薹的名声从此越来越大。","page":971},{"title":"孝子菜","text":"公元221年，割据江东的孙权见曹丕代汉称魏帝，刘备亦在蜀称帝，遂作称帝的准备，自公安迁鄂（今鄂州），取“武而昌”之义，改鄂为武昌。一日，孙权偕母亲吴国太等一行出城游玩，途经东山（洪山），当地官员置酒相迎，席间杯盏交错，宾主尽兴。吴国太对一盘紫色菜肴赞不绝口，夸其甜脆清香，他处所不及。自此以后，每逢洪山菜薹上市季节，孙权必派人来索取，以供吴国太食用。\n一年冬天，吴国太病重，不思茶饭，唯想一尝洪山菜薹，但是在宫中久等不见当地官员送来。孙权大怒，亲至洪山询问缘由。原来当时天寒地冻、大雪封山，菜薹根本没有抽薹。孙权大怒之下，将当地官员重打80大板，责其办事不力，同时在山脚下搭建一棚，将部分菜薹转移至棚中，每日亲自照料。不出半月，棚中菜薹终于抽薹。孙权大喜，立即派人快马送回宫中，吴国太食用之后病情日见好转。\n公元229年，孙权迁都建业（今南京）。临离开武昌时，孙权特地带了一些洪山菜薹的种子去建业，可是所种菜薹的味道总不如洪山产的好。为了满足老母亲的心愿，孙权于是派专人到洪山取了很多土，用船运回去种菜薹，但效果亦不佳。孙权便命当地官员每年在洪山菜薹上市时候，用船将洪山菜薹运至建业，直到吴国太过世。孙权孝顺母亲一事便在洪山传为美谈，洪山菜薹因此又被世人称之为“孝子菜”。","page":971},{"title":"洪山宝塔与红菜薹","text":"相传唐朝开国元勋尉迟敬德出任襄州（今湖北襄樊一带）都督时，路过江夏，鄂州刺史忙令家人预备了一桌丰盛酒宴为尉迟敬德接风。席间尉迟敬德对满桌的山珍海味不怎么感兴趣，而最后上桌的一道紫色蔬菜却使他食欲大增。他边吃边赞道：“好菜！好菜！色香味皆美，脆嫩可口。”尉迟敬德从未见此佳肴，不知其名。鄂州刺史告诉他：“这是楚天名菜‘芸薹’，与武昌鱼齐名，若长期食用，可益寿延年。”尉迟敬德闻之，甚为欢喜，一口气将满盘芸薹吃得精光。临行时，鄂州刺史令人给尉迟敬德备了一份厚礼。尉迟敬德一件未收，唯独要了一筐芸薹菜，准备带在路上享用，同时嘱咐鄂州差役，每年给他送一筐芸薹菜去。\n三年过去了，尉迟敬德在府上苦等芸薹未到，心情十分急躁。心想，这鄂州刺史为何如此不守信用？于是派人到江夏催促。差役回报说，东山（洪山）出了“井蛛湖怪”，芸薹都被妖怪吃了。尉迟敬德不信，亲自带领一班人马，浩浩荡荡来到江夏，一则看个究竟，二则当面责问鄂州刺史。尉迟敬德来到东山，果然看见一大片芸薹菜全都有叶无薹。这时，弥勒寺（今宝通寺）的住持见尉迟敬德到来，忙率全寺僧众出门迎接，并对尉迟敬德说：“要整治这些害人的妖怪不难，只要在东山南麓、本寺西面建一座七层八面的宝塔即可。”\n尉迟敬德听此言后，急忙亲自进京见驾，请皇帝赐金建塔。唐太宗李世民当即下诏，拨皇银万两，命尉迟敬德立刻建塔。结果，宝塔建成了，妖怪镇住了，而尉迟敬德因积劳成疾，还没有来得及吃上新长起来的芸薹就不幸谢世了。从此，由于宝塔神威，弥勒寺钟声播及之处，长满了茂盛的芸薹菜，其中以宝塔投影之地的“学垄田”生长的薹菜味道最佳。人们又可以吃到又脆又嫩的芸薹菜了。这“芸薹菜”，就是今天的洪山菜薹。","page":971},{"title":"放鹰台","text":"相传唐代诗人李白在安陆成家后，还想建功立业，便四处拜谒名人，但处处碰壁，十分沮丧。他来到江夏，去访问东郊（今洪山脚下）李邕故居，只见故居墙上挂着李邕写的中堂：“学我者死，似我者俗”，龙飞凤舞，气势不凡。及至访问主人，才知李邕死后，家境贫寒，他儿子到梁子湖边的龙泉寺当和尚去了。\n李白想到李邕生前高官厚禄，字写得绝好，名气极大，但在官场上因说直话而时遭非议，又不得不与人周旋而难免俗气，且后代连衣食都不保，心里十分难过，便信步沿洪山北麓向东走去。不觉到了湖边，忽听阵阵鸟叫，他拨开树丛，见一只小鹰被猎人下的套子套住了，即解开套子。小鹰冲上天空，绕着李白盘旋两圈后飞走了。望着远去的小鹰，李白豁然开朗。从此，他云游四海，长吟狂歌，再不求官了。李白放鹰之处，人称放鹰台，成为东湖一景。","page":971},{"title":"美人店","text":"美人店，位于伏虎山北，与卓刀泉寺为邻。传说清末民初，葛店人高跛子（本名洪元）为谋生携妻迁居于此。当时伏虎山边仅有一条小道，名曰“北大路”，是生意人来来往往的必经之地。高跛子在山脚下搭起了一间低矮的茅棚，以卖麻花、油条、油饼和大碗茶为生。其妻熊氏，貌美姣好，为人热情，迎来不少过往客商在此歇脚喝茶，一时生意火红。低矮的茅棚被人戏称为“美人店”，进店者趋之若鹜。\n几年光景，这家小店也渐渐有了些许积蓄。不料一天夜里，一伙歹人窜进店里抢劫，哪知聪明的熊氏早有防备，歹人一无所获，一怒之下，将茅棚烧为灰烬。后来，熊氏和丈夫又东拼西凑，重新在此盖起了3间土坯房，经营品种新增了酒菜、便饭，生意比以往更为兴隆，常常是顾客满座，“美人店”的名声越来越大。\n正当“美人店”兴旺之时，有好事者开始对熊氏飞短流长，有心术不正者甚至打起熊氏的坏主意。这些人来到店里，正是冲着美人店里的美人，每每遇此，熊氏总是正颜厉色回绝道：这里没有美人店，只有姑妈店。心怀不轨的无赖碰了一鼻子灰，只好悻悻离去。可惜熊氏的丈夫轻信流言，从此夫妻间有了裂痕。熊氏虽苦口婆心，仍得不到丈夫的信任。一天夜晚，她趁夜深人静，偷偷跑到山林自缢身亡，以示清白。从此以后，“美人店”生意冷落萧条，难以为继。不久，熊氏的丈夫高跛子也在悔恨交加中死去，只留下了“美人店”的传说。","page":972},{"title":"四眼井","text":"“四眼井”是街道口的一个地名。据说200年前，这里原有一口水井，深约40米，井台四周用大块青石铺成。井底有4个铜钱大小的泉眼，故取名“四眼井”。井水一年四季不涸不漫，水质甘洌，冬暖夏凉，当地群众世代饮用此水。\n传说，后因当地一个小媳妇投井自尽，水质遂差了许多。1956年国家修建武（汉）黄（石）公路珞喻段时，填井筑路，四眼井从此消失，地名仍沿用至今。","page":972},{"title":"白马洲","text":"白马洲位于东湖边上。相传三国时期，曹操率83万人马直扑江南。这时，刘琮新降，刘备大败于长坂坡，折往夏口，暂屯兵于大小军山。诸葛亮舌战群儒，说服孙权与刘备联合抗曹。柴桑会后，鲁肃对联合抗曹协议能否执行，放心不下。于是，他取得孙权同意，骑上一匹白马，沿江岸西奔，赶赴夏口与刘备联络。\n白马驮着主人，跋山涉水，日夜兼程，铁打的马掌磨穿了，肚子饿瘪了。一日黄昏，他正策马飞奔，不料前面湖水隔断了去路。白马冲向湖里，陷在湖滩之上，再也不能动弹了。鲁肃痛惜白马累死，遂厚葬白马于荒洲之上，后来人们便叫此洲为白马洲。","page":972},{"title":"落雁岛","text":"落雁岛地处和平乡湖光村。传说春秋时期，楚庄王率部征战到东湖东岸，见湖光山色十分优美，便沿磨山一带驻扎下来。不料大将斗越椒叛变，领兵杀来。庄王擂鼓督战，击败叛贼，斗越椒乘船逃到这片荒岛上，射雁充饥。\n一日，他射伤一雁，那雁带伤直飞庄王营中，庄王将雁伤包扎，由雁带路，终将叛贼逮住。为了纪念引路雁，庄王将这个荒岛取名为“落雁岛”。","page":972},{"title":"白龙泉","text":"很早以前，洪山宝通寺内缺水。一个冬天的晚上，一位巡更的和尚发现前方有个发亮的东西，仔细一看，原来是条小银蛇。和尚善心大发，便解下袈裟盖在小蛇身上。当他离开时，听到小蛇发出响声，回头一看，小蛇头尾都露在外面。和尚便跑回屋里，将自己的棉被抱来盖在蛇身上。\n一会儿，被子底下发出“可咚可咚”的声音，和尚揭开被子一看，小蛇变成了一条小白龙。和尚正在惊奇，小白龙腾空飞走了，在卧过的地方却留下一汪清泉。从此，僧人称这眼泉为白龙泉。","page":972},{"title":"白玉山","text":"白玉山位于建设乡境内。传说，此山古时藏有一条大白蛇，欲修仙成龙，常把尾部绕在山头上，将头部伸向北湖喝水，因而山顶有猛长之势。\n为了镇邪，有人在山上修建了一座寺庙，名为白龙古寺。寺庙的上殿供有菩萨，下殿住有4名尼姑，中间两侧是厢房。寺庙在1958年拆除，现无遗迹。","page":972},{"title":"八吉府","text":"八吉府，位于建设乡东部，上起杜家井，下到张家墩；东北面临长江，南邻北湖，西与工业港村相连。\n相传，古代的八吉府地势低洼，常闹洪灾，民不聊生。清朝顺治年间皇帝巡视江南，路过此地，询察民情，用斗量米，仅有八斤一斗米（约13斤），便责令地方官员丈量土地，修筑堤坝，改良土壤，豁免赋税，鼓励耕作，故名此地为八斤府。抗日战争时期，百姓祈祷平安大吉，因改此地为“八吉府”，沿用至今。","page":973},{"title":"侯家庙","text":"侯家庙位于洪山区和平乡东南部，在武丰村境内，侯家庙地片包括犁头尖、杨家旗杆、常家墩、田家墩、石家墩、赵家村等自然村。\n相传，明朝正德皇帝微服私访，一日驾到武昌，天色不早，需在此处权过一宵。当地群众和一些有钱的人闻讯纷纷前来迎驾，后建3庙，把等候皇帝的地方称为“候驾庙”，皇帝驻驾的地方称“下马庙”，皇帝安歇的地方称为“落王庙”。从古至今已有400余年，成为四乡闻名的地名。","page":973},{"title":"活灵泉","text":"左岭镇吴家桥附近，有口井因天然喷泉，人称活灵泉，又称“泉井”。“泉井”是一地下喷泉，其水色清亮，水质纯净，常年恒温18℃，冬暖夏凉，是极好的天然饮用水。冬天，附近群众常到此洗涤衣被等物品；夏天，过往行人常常来此盥洗以消暑爽身。常有附近村民到此汲水回家饮用。\n相传，在很久以前，泉井旁曾因发大水冲来一具女尸，当地群众发觉后，立即将此女尸葬于泉井西北不远的山包上，并立碑命名为“仙姑坟”，以寄托对她的哀思，并祈求保佑。人们亟望“仙姑显灵”，募款在其坟前修建了座庵堂，名曰“仙姑庵”。此庵原仅供奉“仙姑”神像，以后又增供多位神像，当门就是“红脸关公”，“关平”、“周仓”伫立左右。至此，“庵”变成了“庙”，人们就通称它为“仙姑庙”。\n此后，人们又把这座庙与近处的泉井联系起来，称泉水为“圣水”。每到庙堂求神拜佛之余，总要到泉井喝泉水，祈祷消灾祛邪，延年益寿，以求得心灵慰藉。","page":973},{"title":"圣水口","text":"圣水口原名顺水口，是花山镇的一个自然村，位于土桥村吴家桥，距鸡笼山不远。相传，当地曾有一座黄莲寺，寺前有井，叫龙王井，井水源源溢出，不枯竭，顺水而下流，因名“顺水口”。\n后来该村出了一位秀才方文渠，进京应试，金榜题名。一天，上官问及家住何处，他随口答曰：“下官家住鸡笼山接驾岭圣水口。”上官听后大悦，视为心腹。顺水口于是更名圣水口，流传于今。","page":973},{"title":"南望兄弟","text":"南望山与喻家山遥遥相望。相传此山原名茅王山，荒山秃顶，周围多茅柴，山下农民就是靠砍卖茅柴为生。\n山南脚下有大张村、小张村，居民多姓张，据说是江西移民的后代。他们的祖先两兄弟，哥哥叫张有来，弟弟叫张有望，因改山名为“来望”。后又因“来”与“南”音近，故又讹为“南望山”，且沿用至今。","page":973},{"title":"左岭轶事","text":"传说明代洪武初年，有一左氏家庭自江西省饶州府馀干县瓦屑坝迁徙来此定居，名为左家湾。后因左家湾坐落在岭岗上，故又名左岭。\n左岭人中流传着这样的故事：1645年，明末农民起义军领袖李自成和张献忠率部转移湖北，进入鄂城县境后，在左岭分手。张献忠径直西去洪山，转赴岳州。而李自成则拐向东南，由左岭的严家湖夺舟南下，以单骑登九宫山。退走九宫山前，在左岭地区留下了多处遗址，如下马嘴（李闯王至此下马）、失马港（李闯王在此“失掉战马”）、卸甲（李闯王在此丢盔卸甲）、毛长嘴（李闯王在此抛掉大枪长矛）。","page":973},{"title":"鼓架山的传说","text":"花山镇严西湖畔有座山名叫鼓架山。传说春秋战国时期，楚庄王兴兵作战，败逃至鼓架山被困，与追敌在清河桥相望，形势十分危急。无奈何，庄王置大鼓于山上，击鼓求援，并声称：有人救得孤王的命，孤与他江山平半分。\n果然，远在十数里外八吉府的勇士养由基正牧马江边，听到鼓声后飞马奔援。天从人愿，养由基杀败了敌人，救了楚庄王的命。庄王虽然食言，未将江山平半分，却也将养由基收为大将。因庄王在此击鼓，后人将山改名鼓架山。","page":973}],"poems":[{"title":"题江夏修静寺","author":"李白","dynasty":"唐","text":"我家北海宅，作寺南江滨。\n空庭无玉树，高殿坐幽人。\n书带留青草，琴堂幂素尘。\n平生种桃李，寂灭不成春。"},{"title":"游武昌东湖","author":"袁说友","dynasty":"宋","text":"只说西湖在帝都，武昌新又说东湖。\n一围烟浪六十里，几队寒鸥千百只。\n野木迢迢遮去雁，渔舟点点映飞乌。\n如何不作钱塘景，要与江城作画图。"},{"title":"雪后晚晴，四山皆青，惟东山全白，赋最爱东山晴后雪绝句","author":"杨万里","dynasty":"南宋","text":"只知逐胜忽忘寒，小立春风夕照间。\n最爱东山晴后雪，软红光里涌银山。"},{"title":"武昌南湖度夏","author":"丁鹤年","dynasty":"元","text":"南浦幽栖地，当门罨画开。\n青山入云去，白雨渡湖来。\n石润生龙气，川光媚蚌胎。\n芙蕖三百顷，何处着炎埃。"},{"title":"悟偈","author":"释无念","dynasty":"明","text":"数载空山昏雾蒙，凭栏终日待晴空。\n夜来忽睹霜天月，万象全彰一镜中。"},{"title":"游洪山","author":"袁中道","dynasty":"明","text":"醒却秾华梦，来为冷石游。\n纡回缘绿嶂，枕藉见红楼。\n雪净江天静，林烟沙渚浮。\n倚栏神顿爽，信矣癖山邱。"},{"title":"洪山寺","author":"冯云路","dynasty":"明","text":"杖藜登绝岩，曲径绕孤亭。\n欲向传心偈，重来问译经。\n江云连水白，野竹上山青。\n寂寂禅房久，山中夜不扃。"},{"title":"东湖","author":"吴桂芳","dynasty":"明","text":"东湖行一曲，十里柳烟齐。\n远坞浮空碧，长云压水低。\n岸香闻杜若，沙净浴凫鹥。\n更爱维舟处，夕阳莲叶西。"},{"title":"登江夏洪山寺塔","author":"施闰章","dynasty":"清","text":"峰头开古寺，塔下俯浮云。\n山势龟蛇斗，江流沔汉分。\n柳荒陶侃庙，风竞伏波军。\n南望湖光白，鸿归渡夕曛。"},{"title":"登宝通塔寺","author":"刘淳","dynasty":"清","text":"罡风吹到九霄来，塔顶摇摇势欲摧。\n叠嶂有灵横地出，长江如线画天开。\n吾生幸得观三楚，此笔曾经赋五台。\n久客悲秋殊潦倒，盛年空负菊花杯。"},{"title":"登洪山","author":"刘朝英","dynasty":"清","text":"手板朝朝兴未穷，秋来蹑屐到龙宫。\n金银气色寒郊外，楼阁参差暮霭中。\n塔势欲飞初罢磬，禅心方定一闻钟。\n谁言世出莲花国，却是城头姑射峰。"},{"title":"登宝通寺塔","author":"沈榘","dynasty":"清","text":"一入龙蛇窟，浑如洞里仙。\n兴豪频历险，步健每当先。\n眺远三千界，登险咫尺天。\n褰裳成羽翼，飞绕白云边。"},{"title":"赞洪山菜薹","author":"陈广敷","dynasty":"清","text":"紫干经霜脆，黄英带雪娇。\n晚菘珍黑白，同是楚中翘。"},{"title":"雪中猎洪山","author":"陈廷敬","dynasty":"清","text":"使君千骑围猎长，雪夜风流在武昌。\n为报襄阳耆旧语，呼鹰台上笑刘郎。"},{"title":"悼施洋烈士","author":"董必武","dynasty":"现代","text":"二七工仇血史留，吴萧遗臭万千秋。\n律师应仗人间义，身殉名存烈士俦。"},{"title":"登洪山谒施洋烈士墓","author":"公木","dynasty":"现代","text":"萧吴之辈今安在？烈士英名万世传。\n浩气如虹映江水，血光似火燎中原。\n惊涛滚滚吞东海，碧霭沉沉接楚天。\n有幸青山埋硬骨，行人路上仰头看。"},{"title":"谒九女墩","author":"宋庆龄","dynasty":"现代","text":"鄂中巾帼九英雄，壮烈牺牲后世风。\n辛亥革命前后起，推翻帝制古今崇。"},{"title":"九女墩","author":"赵朴初","dynasty":"现代","text":"天京久困无一叛，武昌三破争死战。\n有女慷慨为国殇，太平风义可慨见。\n青冢何须著姓名，千秋忠骨作兰馨。\n几多华表成尘土，永耀东湖九女墩。"},{"title":"忆江南·东湖","author":"侯孝琼","dynasty":"当代","text":"东湖好，最好是春晴。百里风来湖面绿，一场雨过柳梢青，处处啭黄莺。\n东湖好，夏日弄清流。水共碧天浑上下，人同白鹭竞沉浮，击浪溅飞舟。\n东湖好，秋浦住行吟。一阁清风飞玉笛，两行霜树入湖心，浩气涤尘襟。"}],"couplets":[{"place":"宝通寺（张朝珍撰）","text":"长廊古殿高开，万里青天端坐金轮顶上；\n层台翠山现出，一江明月如行白玉镜中。"},{"place":"宝通寺（横批：为善最乐）","text":"层台直接青天，百尺竿头须进步；\n兰若高临大壑，万峰顶上好清修。"},{"place":"宝通寺（横批：法流慧日）","text":"白日传灯，千丈香云天上见；\n青山说法，一江花雨月中来。"},{"place":"宝通寺白云阁","text":"一钩明月常古今，\n万壑闲云自往来。"},{"place":"宝通寺方丈室","text":"坐入云中千树绿，\n分来江上数峰青。"},{"place":"宝通寺","text":"塔涌香花地，\n山围日月天。"},{"place":"岳飞庙（李瀚章撰）","text":"浩气满中原，当年绣帜撝军，壁垒分屯诸统制；\n故封仍岳鄂，可惜金牌趣召，江山忽换小朝廷。"},{"place":"岳武穆遗像亭（刘伯绳撰）","text":"鄂渚波连，拍岸惊天，为洗奇冤莫须有；\n楚歌声里，撼心动魄，更添壮志满江红。"},{"place":"洪山宝塔","text":"锦簇花团，三镇风光收眼底；\n星移物换，千年兴废在心头。"},{"place":"沙湖琴堤水月（任桐撰）","text":"故乡亦有湖山，都亏几段柳堤锁住烟景；\n此处正多水月，忽听数声芦笛吹断夕阳。"},{"place":"莲溪寺（本智撰）","text":"开口便笑，笑古笑今，凡事付之一笑；\n大肚能容，容天容地，于人无所不容。"}],"wencun":[{"title":"市人民政府关于调整武昌、洪山区行政区划的通知（武政〔1986〕59号）","summary":"武汉市人民政府决定自1986年7月1日起将洪山区改为“城区带郊区”：狮子山、关山、葛化街道及珞珈山街道27个居委会划归洪山，新设珞南街。调整后洪山区辖六街、六乡、二镇，并划定了与武昌区的具体界线。","page":951}],"chapters":[]}]};